const BitWriter = struct {
    out: *std.ArrayList(u8),
    bit_index: u3 = 0,
    bounded: bool = false,

    pub fn writeBits(self: *BitWriter, allocator: std.mem.Allocator, value: u64, count: u6) Error!void {
        if (count > 64) return error.CorruptFrame;
        if (count == 0) return;
        var remaining: usize = count;
        var cursor = value;
        while (remaining != 0) {
            if (self.bit_index == 0) try self.appendZeroByte(allocator);
            const available: usize = 8 - @as(usize, self.bit_index);
            const take = @min(remaining, available);
            const mask = (@as(u64, 1) << @intCast(take)) - 1;
            self.out.items[self.out.items.len - 1] |= @as(u8, @intCast(cursor & mask)) << self.bit_index;
            cursor >>= @intCast(take);
            remaining -= take;
            const next = @as(usize, self.bit_index) + take;
            self.bit_index = @intCast(next & 7);
        }
    }

    /// Writes a validated, non-empty Brotli Huffman code. Huffman code widths
    /// are capped at 15 bits, so the code can touch at most three bytes. The
    /// payload encoder has already validated the tree and code width; spelling
    /// out those writes avoids the general bit writer's per-byte loop in its
    /// hottest call sites while preserving the same growth and bounded-output
    /// behavior through `appendZeroByte`.
    pub inline fn writeHuffmanBits(self: *BitWriter, allocator: std.mem.Allocator, value: u16, count: u4) Error!void {
        std.debug.assert(count != 0);
        std.debug.assert(value < (@as(u16, 1) << count));

        if (self.bit_index == 0) try self.appendZeroByte(allocator);
        const shifted = @as(u32, value) << self.bit_index;
        self.out.items[self.out.items.len - 1] |= @truncate(shifted);

        const total_bits = @as(u5, self.bit_index) + @as(u5, count);
        if (total_bits > 8) {
            try self.appendZeroByte(allocator);
            self.out.items[self.out.items.len - 1] = @truncate(shifted >> 8);
            if (total_bits > 16) {
                try self.appendZeroByte(allocator);
                self.out.items[self.out.items.len - 1] = @truncate(shifted >> 16);
            }
        }
        self.bit_index = @truncate(total_bits & 7);
    }

    inline fn appendZeroByte(self: *BitWriter, allocator: std.mem.Allocator) Error!void {
        if (self.out.items.len < self.out.capacity) {
            self.out.appendAssumeCapacity(0);
        } else if (self.bounded) {
            return error.OutOfMemory;
        } else {
            try self.out.append(allocator, 0);
        }
    }

    fn alignToByte(self: *BitWriter) void {
        self.bit_index = 0;
    }

    fn bitPosition(self: *const BitWriter) usize {
        if (self.bit_index == 0) return self.out.items.len * 8;
        return (self.out.items.len - 1) * 8 + self.bit_index;
    }

    fn writeAlignedBytes(self: *BitWriter, allocator: std.mem.Allocator, bytes: []const u8) Error!void {
        if (self.bit_index != 0) return error.CorruptFrame;
        if (self.bounded) {
            try self.out.appendSliceBounded(bytes);
        } else {
            try self.out.appendSlice(allocator, bytes);
        }
    }
};

test "Brotli bit writer uses reserved and bounded capacity" {
    var storage: [2]u8 = undefined;
    var out: std.ArrayList(u8) = .{
        .items = storage[0..0],
        .capacity = storage.len,
    };
    var writer = BitWriter{ .out = &out, .bounded = true };
    try writer.writeBits(std.testing.allocator, 0xabcd, 16);
    try std.testing.expectEqualSlices(u8, &.{ 0xcd, 0xab }, out.items);
    try std.testing.expectError(error.OutOfMemory, writer.writeBits(std.testing.allocator, 1, 1));
}

test "Brotli narrow Huffman bit writer matches the general writer" {
    const values = [_]u16{ 0, 1, 0x5555, 0x7fff };
    for (0..8) |initial_bits| {
        for (1..huffman.max_code_bits + 1) |count| {
            const mask = (@as(u16, 1) << @intCast(count)) - 1;
            for (values) |unmasked| {
                const value = unmasked & mask;
                var general: std.ArrayList(u8) = .empty;
                defer general.deinit(std.testing.allocator);
                var narrow: std.ArrayList(u8) = .empty;
                defer narrow.deinit(std.testing.allocator);

                if (initial_bits != 0) {
                    const initial_byte = @as(u8, 0xa5) & ((@as(u8, 1) << @intCast(initial_bits)) - 1);
                    try general.append(std.testing.allocator, initial_byte);
                    try narrow.append(std.testing.allocator, initial_byte);
                }
                var general_writer = BitWriter{ .out = &general, .bit_index = @intCast(initial_bits) };
                var narrow_writer = BitWriter{ .out = &narrow, .bit_index = @intCast(initial_bits) };
                try general_writer.writeBits(std.testing.allocator, value, @intCast(count));
                try narrow_writer.writeHuffmanBits(std.testing.allocator, value, @intCast(count));

                try std.testing.expectEqual(general_writer.bit_index, narrow_writer.bit_index);
                try std.testing.expectEqualSlices(u8, general.items, narrow.items);
            }
        }
    }
}

test "Brotli narrow Huffman bit writer preserves bounded overflow" {
    var storage = [_]u8{0} ** 2;
    var out: std.ArrayList(u8) = .{
        .items = storage[0..1],
        .capacity = storage.len,
    };
    out.items[0] = 0x7f;
    var writer = BitWriter{ .out = &out, .bit_index = 7, .bounded = true };

    try std.testing.expectError(error.OutOfMemory, writer.writeHuffmanBits(std.testing.allocator, 0x7fff, 15));
}

pub fn PrefixCode(comptime alphabet_size: usize) type {
    return struct {
        single_symbol: ?u16 = null,
        table: huffman.HuffmanTable(alphabet_size) = .{},

        const Self = @This();

        pub fn decode(self: *const Self, reader: anytype) Error!u16 {
            if (self.single_symbol) |symbol| return symbol;
            return try self.table.decodeValue(reader);
        }

        pub fn prepareTailLookup(self: *Self) bool {
            if (self.single_symbol != null) return true;
            return self.table.buildTailLookup8();
        }

        pub fn canPrepareTailLookup(self: *const Self) bool {
            return self.single_symbol != null or self.table.canBuildTailLookup8();
        }

        pub inline fn decodeTailLookup(self: *const Self, reader: anytype) Error!u16 {
            if (self.single_symbol) |symbol| return symbol;
            return self.table.decodeValueTailLookup8(reader);
        }

        pub inline fn decodeTailLookup9(self: *const Self, reader: anytype) Error!u16 {
            if (self.single_symbol) |symbol| return symbol;
            return self.table.decodeValueTailLookup9(reader);
        }

        pub inline fn decodeTailLookup9Fixed(self: *const Self, reader: anytype) Error!u16 {
            if (self.single_symbol) |symbol| return symbol;
            return self.table.decodeValueTailLookup9Fixed(reader);
        }

        pub inline fn decodeTailLookup10Fixed(self: *const Self, reader: anytype) Error!u16 {
            if (self.single_symbol) |symbol| return symbol;
            return self.table.decodeValueTailLookup10Fixed(reader);
        }
    };
}

fn PackedPrefixCode(comptime alphabet_size: usize) type {
    return struct {
        single_symbol_plus_one: u16 = 0,
        active_entries: u16 = 0,
        lengths: [(alphabet_size + 1) / 2]u8 = @splat(0),

        const Self = @This();

        fn init(tree: *const PrefixCode(alphabet_size)) Self {
            var compact: Self = .{};
            if (tree.single_symbol) |symbol| {
                compact.single_symbol_plus_one = symbol + 1;
                return compact;
            }
            compact.active_entries = @intCast(tree.table.len);
            for (tree.table.entries[0..tree.table.len]) |entry| {
                const byte_index = entry.symbol / 2;
                const shift: u3 = @intCast((entry.symbol & 1) * 4);
                compact.lengths[byte_index] |= @as(u8, entry.bits) << shift;
            }
            return compact;
        }

        fn expand(self: *const Self) Error!PrefixCode(alphabet_size) {
            if (self.single_symbol_plus_one != 0)
                return .{ .single_symbol = self.single_symbol_plus_one - 1 };
            var lengths: [alphabet_size]u4 = undefined;
            for (&lengths, 0..) |*length, symbol| {
                const shift: u3 = @intCast((symbol & 1) * 4);
                length.* = @truncate(self.lengths[symbol / 2] >> shift);
            }
            const tree: PrefixCode(alphabet_size) = .{
                .table = try huffman.HuffmanTable(alphabet_size).init(&lengths),
            };
            if (tree.table.len != self.active_entries) return error.InvalidHuffmanCode;
            return tree;
        }
    };
}

const inline_literal_tree_count = 64;
const inline_command_tree_count = 32;
const inline_distance_tree_count = 64;

const max_distance_alphabet_size = 16 + 120 + (48 << 3);
// Large Window Brotli deliberately advertises 62 distance-bit groups in its
// wire alphabet. Unlike RFC 7932's 24 groups, each group has two halves, so
// the maximum wire shape is 16 + 120 + (62 << (3 + 1)) = 1128 symbols. The
// 32-bit-safe distance ceiling restricts the usable prefix to at most 544
// symbols (NPOSTFIX=3, NDIRECT=120), so decoder tables need only that bound.
const large_wire_max_distance_alphabet_size = 16 + 120 + (62 << (3 + 1));
const large_max_distance_alphabet_size = 544;
// Planned streams fix NPOSTFIX=0 and NDIRECT=15, so their distance alphabet is
// exactly 79 symbols even though the decoder accepts the RFC-wide 520-symbol
// maximum. Keep encoder scratch proportional to what its header advertises.
const planned_distance_alphabet_size = 16 + 15 + 48;
const max_context_map_alphabet_size = 256 + 16;
// RFC 7932 uses the same bounded varlen uint8 count for all three block-type
// families. Real quality-11 streams already exercise more than 32 literal
// types, and keeping the complete range costs only the context-mode/map bytes
// plus the small block-switch tree; literal Huffman trees remain independently
// capped by their own complete 256-entry wire range.
const max_literal_block_types = 256;
// Large upstream source streams can use more than 128 literal trees. Retain
// the complete one-byte wire range; direct-to-header parsing initializes only
// declared slots, so ordinary streams do not pay per-tree setup cost.
const max_literal_context_trees = 256;
// Keep the common first 32 command trees in their ready-to-decode form. The
// remaining RFC range is retained as packed 4-bit code lengths and expanded
// into one cache only when a stream switches there, avoiding roughly 1 MiB of
// fixed decoder state.
const max_command_block_types = 256;
// RFC 7932 encodes block-type and context-tree counts with a bounded 8-bit
// varlen code. Real mixed-source libbrotli streams can exceed the former
// 64-entry implementation tier (68 distance types in the retained corpus), so
// keep the complete wire range rather than rejecting otherwise valid input.
const max_distance_block_types = 256;
const max_distance_context_trees = 256;

fn MinimalCompressedHeaderType(comptime literal_alphabet_capacity: usize, comptime command_alphabet_capacity: usize, comptime distance_alphabet_capacity: usize) type {
    return struct {
        npostfix: u2,
        ndirect: u16,
        literal_tree_count: u16 = 1,
        distance_tree_count: u16 = 1,
        literal_context_modes: [max_literal_block_types]u2,
        literal_block: BlockSwitchState(max_literal_block_types),
        literal_context_map: [max_literal_block_types * 64]u8,
        literal_trees: [inline_literal_tree_count]PrefixCode(literal_alphabet_capacity),
        packed_literal_trees: [max_literal_context_trees - inline_literal_tree_count]PackedPrefixCode(literal_alphabet_capacity) = @splat(.{}),
        active_packed_literal_tree: PrefixCode(literal_alphabet_capacity) = .{},
        active_packed_literal_tree_index: u16 = std.math.maxInt(u16),
        command_block: BlockSwitchState(max_command_block_types),
        insert_copy_trees: [inline_command_tree_count]PrefixCode(command_alphabet_capacity),
        packed_insert_copy_trees: [max_command_block_types - inline_command_tree_count]PackedPrefixCode(command_alphabet_capacity) = @splat(.{}),
        active_packed_insert_copy_tree: PrefixCode(command_alphabet_capacity) = .{},
        active_packed_insert_copy_tree_index: u16 = std.math.maxInt(u16),
        distance_block: BlockSwitchState(max_distance_block_types),
        distance_context_map: [max_distance_block_types * 4]u8,
        distance_trees: [inline_distance_tree_count]PrefixCode(distance_alphabet_capacity),
        packed_distance_trees: [max_distance_context_trees - inline_distance_tree_count]PackedPrefixCode(distance_alphabet_capacity) = @splat(.{}),
        active_packed_distance_tree: PrefixCode(distance_alphabet_capacity) = .{},
        active_packed_distance_tree_index: u16 = std.math.maxInt(u16),
    };
}

const MinimalCompressedHeader = struct {
    npostfix: u2,
    ndirect: u16,
    literal_tree_count: u16 = 1,
    distance_tree_count: u16 = 1,
    literal_context_modes: [max_literal_block_types]u2,
    literal_block: BlockSwitchState(max_literal_block_types),
    literal_context_map: [max_literal_block_types * 64]u8,
    literal_trees: [inline_literal_tree_count]PrefixCode(256),
    packed_literal_trees: [max_literal_context_trees - inline_literal_tree_count]PackedPrefixCode(256) = @splat(.{}),
    active_packed_literal_tree: PrefixCode(256) = .{},
    active_packed_literal_tree_index: u16 = std.math.maxInt(u16),
    command_block: BlockSwitchState(max_command_block_types),
    insert_copy_trees: [inline_command_tree_count]PrefixCode(704),
    packed_insert_copy_trees: [max_command_block_types - inline_command_tree_count]PackedPrefixCode(704) = @splat(.{}),
    active_packed_insert_copy_tree: PrefixCode(704) = .{},
    active_packed_insert_copy_tree_index: u16 = std.math.maxInt(u16),
    distance_block: BlockSwitchState(max_distance_block_types),
    distance_context_map: [max_distance_block_types * 4]u8,
    distance_trees: [inline_distance_tree_count]PrefixCode(max_distance_alphabet_size),
    packed_distance_trees: [max_distance_context_trees - inline_distance_tree_count]PackedPrefixCode(max_distance_alphabet_size) = @splat(.{}),
    active_packed_distance_tree: PrefixCode(max_distance_alphabet_size) = .{},
    active_packed_distance_tree_index: u16 = std.math.maxInt(u16),
    distance_extra_bits: [max_distance_alphabet_size]u5 = undefined,
    distance_offsets: [max_distance_alphabet_size]u32 = undefined,
};
const large_literal_alphabet_capacity = 257;
const large_command_alphabet_capacity = 705;
const LargeWindowCompressedHeader = MinimalCompressedHeaderType(
    large_literal_alphabet_capacity,
    large_command_alphabet_capacity,
    large_max_distance_alphabet_size,
);

pub const CompressedHeaderProfile = header_profile.Profile;
pub const CompressedHeaderFamily = header_profile.Family;

const initial_last_distances = [_]usize{ 16, 15, 11, 4 };
const planner_max_backward_distance = (@as(usize, 1) << default_window_bits) - 16;
const SummaryError = Error || error{SummaryHistoryExhausted};

pub const CompressedSupportLimits = struct {
    max_literal_block_types: usize,
    max_literal_context_trees: usize,
    max_command_block_types: usize,
    max_distance_block_types: usize,
    max_distance_context_trees: usize,
    max_distance_alphabet_size: usize,
};

fn maxBackwardDistanceForWindow(window_bits: u5, output_len: usize) usize {
    return @min(output_len, (@as(usize, 1) << window_bits) - 16);
}

const WindowInfo = struct {
    bits: u5,
    large: bool = false,
};

pub fn compressedSupportLimits() CompressedSupportLimits {
    return .{
        .max_literal_block_types = max_literal_block_types,
        .max_literal_context_trees = max_literal_context_trees,
        .max_command_block_types = max_command_block_types,
        .max_distance_block_types = max_distance_block_types,
        .max_distance_context_trees = max_distance_context_trees,
        .max_distance_alphabet_size = max_distance_alphabet_size,
    };
}

fn BlockSwitchState(comptime max_block_types: usize) type {
    return struct {
        block_type_count: u16 = 1,
        current_type: u16 = 0,
        previous_type: u16 = 1,
        remaining: usize = max_uncompressed_meta_block_len,
        type_tree: PrefixCode(max_block_types + 2) = .{},
        length_tree: PrefixCode(26) = .{},
    };
}

const InsertCopyLengths = struct {
    insert_len: usize,
    copy_len: usize,
    distance_symbol_zero: bool,
};

const LiteralHistory = struct {
    external: ?[]u8 = null,
    previous: [2]u8 = .{ 0, 0 },
    // Summary/size preflight does not materialize decoded output, so it keeps
    // enough recent bytes to replay copies that feed following literal-context
    // decisions. The actual decoder can look back through the full output
    // buffer; this bounded preflight history intentionally grows in audited
    // compatibility slices as we add coverage for farther Brotli distances.
    // The production ratio planner can search the full advertised 16-bit
    // Brotli window. Retaining that exact maximum lets decoded-size preflight
    // preserve literal contexts even after its farthest legal match.
    // `tail_len` gates every read, so clearing this relatively large buffer on
    // each summary would only initialize bytes that cannot yet be observed.
    tail: [planner_max_backward_distance]u8 = undefined,
    tail_len: usize = 0,
    tail_start: usize = 0,
    // The implicit bytes before stream start are zero, so both context bytes
    // begin known. A copy beyond this bounded summary history invalidates them;
    // two subsequently decoded literals are required to restore both values.
    known_suffix_len: u2 = 2,

    fn context(self: *const LiteralHistory, header: *const MinimalCompressedHeader) SummaryError!usize {
        const mode = header.literal_context_modes[header.literal_block.current_type];
        const needed: u2 = if (mode <= 1) 1 else 2;
        if (self.known_suffix_len < needed) return contextIndependentLiteralContext(header) orelse error.SummaryHistoryExhausted;
        return try literalContextFromMode(
            mode,
            self.previous[1],
            self.previous[0],
        );
    }

    fn contextLarge(self: *const LiteralHistory, header: *const LargeWindowCompressedHeader) SummaryError!usize {
        const mode = header.literal_context_modes[header.literal_block.current_type];
        const needed: u2 = if (mode <= 1) 1 else 2;
        if (self.known_suffix_len < needed) return contextIndependentLargeLiteralContext(header) orelse error.SummaryHistoryExhausted;
        return try literalContextFromMode(
            mode,
            self.previous[1],
            self.previous[0],
        );
    }

    fn push(self: *LiteralHistory, value: u8) void {
        self.previous[0] = self.previous[1];
        self.previous[1] = value;
        const bytes = self.storage();
        if (bytes.len == 0) {
            self.known_suffix_len = @min(2, self.known_suffix_len + 1);
            return;
        }
        if (self.tail_len < bytes.len) {
            bytes[(self.tail_start + self.tail_len) % bytes.len] = value;
            self.tail_len += 1;
        } else {
            bytes[self.tail_start] = value;
            self.tail_start = (self.tail_start + 1) % bytes.len;
        }
        self.known_suffix_len = @min(2, self.known_suffix_len + 1);
    }

    fn pushSlice(self: *LiteralHistory, values: []const u8) void {
        if (values.len == 0) return;

        if (values.len == 1) {
            self.previous[0] = self.previous[1];
            self.previous[1] = values[0];
            self.known_suffix_len = @min(2, self.known_suffix_len + 1);
        } else {
            self.previous = .{ values[values.len - 2], values[values.len - 1] };
            self.known_suffix_len = 2;
        }

        const ring = self.storage();
        if (ring.len == 0) return;
        if (values.len >= ring.len) {
            // The newest complete window is already contiguous in `values`;
            // replacing the ring avoids one modulo operation per stored byte.
            @memcpy(ring, values[values.len - ring.len ..]);
            self.tail_len = ring.len;
            self.tail_start = 0;
            return;
        }

        if (self.tail_len < ring.len) {
            // A partially filled ring has never wrapped (markUnknown resets it),
            // so append the first span directly and wrap only any overflow.
            std.debug.assert(self.tail_start == 0);
            const append_len = @min(values.len, ring.len - self.tail_len);
            @memcpy(ring[self.tail_len..][0..append_len], values[0..append_len]);
            self.tail_len += append_len;
            if (append_len == values.len) return;

            const wrapped = values[append_len..];
            @memcpy(ring[0..wrapped.len], wrapped);
            self.tail_start = wrapped.len;
            return;
        }

        const first_len = @min(values.len, ring.len - self.tail_start);
        @memcpy(ring[self.tail_start..][0..first_len], values[0..first_len]);
        @memcpy(ring[0 .. values.len - first_len], values[first_len..]);
        self.tail_start = (self.tail_start + values.len) % ring.len;
    }

    fn copy(self: *LiteralHistory, distance: usize, len: usize) void {
        if (len == 0) return;
        if (distance == 0 or distance > self.tail_len) {
            self.markUnknown();
            return;
        }

        // Copy through a small temporary so the ring needs only one modulo and
        // at most two source spans per batch. Limiting the initial seed to the
        // distance preserves Brotli's forward-overlap semantics; doubling that
        // seed in scratch then expands short periodic matches in logarithmically
        // many contiguous copies rather than one ring operation per output byte.
        var scratch: [256]u8 = undefined;
        var remaining = len;
        while (remaining != 0) {
            const batch_len = @min(remaining, scratch.len);
            const seed_len = @min(distance, batch_len);
            const ring = self.storage();
            const source_index = (self.tail_start + self.tail_len - distance) % ring.len;
            const first_len = @min(seed_len, ring.len - source_index);
            @memcpy(scratch[0..first_len], ring[source_index..][0..first_len]);
            @memcpy(scratch[first_len..seed_len], ring[0 .. seed_len - first_len]);

            if (seed_len == 1) {
                @memset(scratch[1..batch_len], scratch[0]);
            } else {
                var initialized = seed_len;
                while (initialized < batch_len) {
                    const take = @min(initialized, batch_len - initialized);
                    @memcpy(scratch[initialized..][0..take], scratch[0..take]);
                    initialized += take;
                }
            }
            self.pushSlice(scratch[0..batch_len]);
            remaining -= batch_len;
        }
    }

    fn storage(self: *LiteralHistory) []u8 {
        return self.external orelse self.tail[0..];
    }

    fn markUnknown(self: *LiteralHistory) void {
        self.known_suffix_len = 0;
        self.tail_len = 0;
        self.tail_start = 0;
    }
};

fn contextIndependentLiteralContext(header: *const MinimalCompressedHeader) ?usize {
    const block_type = header.literal_block.current_type;
    if (block_type >= max_literal_block_types) return null;
    const map_start = @as(usize, block_type) * 64;
    const first_tree = header.literal_context_map[map_start];
    for (header.literal_context_map[map_start..][0..64]) |tree_index| {
        if (tree_index != first_tree) return null;
    }
    return 0;
}

fn contextIndependentLargeLiteralContext(header: *const LargeWindowCompressedHeader) ?usize {
    const block_type = header.literal_block.current_type;
    if (block_type >= max_literal_block_types) return null;
    const map_start = @as(usize, block_type) * 64;
    const first_tree = header.literal_context_map[map_start];
    for (header.literal_context_map[map_start..][0..64]) |tree_index| {
        if (tree_index != first_tree) return null;
    }
    return 0;
}

test "br summary context needs two literals after unknown history" {
    var history = LiteralHistory{};
    history.markUnknown();
    try std.testing.expectEqual(@as(u2, 0), history.known_suffix_len);
    history.push('a');
    try std.testing.expectEqual(@as(u2, 1), history.known_suffix_len);
    history.push('b');
    try std.testing.expectEqual(@as(u2, 2), history.known_suffix_len);

    history.markUnknown();
    history.push('x');
    history.copy(1, 2);
    try std.testing.expectEqual(@as(u2, 2), history.known_suffix_len);
    try std.testing.expectEqual([2]u8{ 'x', 'x' }, history.previous);
}

test "br summary history appends slices across ring boundaries" {
    var storage: [5]u8 = undefined;
    var history = LiteralHistory{ .external = &storage };

    history.pushSlice("abc");
    try std.testing.expectEqual(@as(usize, 3), history.tail_len);
    try std.testing.expectEqual(@as(usize, 0), history.tail_start);
    try std.testing.expectEqualSlices(u8, "abc", storage[0..3]);
    try std.testing.expectEqual([2]u8{ 'b', 'c' }, history.previous);

    history.pushSlice("defg");
    try std.testing.expectEqual(@as(usize, 5), history.tail_len);
    try std.testing.expectEqual(@as(usize, 2), history.tail_start);
    try std.testing.expectEqualSlices(u8, "fgcde", &storage);
    history.copy(5, 5);
    try std.testing.expectEqual(@as(usize, 0), history.tail_start);
    try std.testing.expectEqualSlices(u8, "cdefg", &storage);
    try std.testing.expectEqual([2]u8{ 'f', 'g' }, history.previous);

    history.pushSlice("123456");
    try std.testing.expectEqual(@as(usize, 0), history.tail_start);
    try std.testing.expectEqualSlices(u8, "23456", &storage);
    try std.testing.expectEqual([2]u8{ '5', '6' }, history.previous);
}

test "br summary history copy matches forward overlap oracle" {
    var storage: [31]u8 = undefined;
    var history = LiteralHistory{ .external = &storage };
    var expected: std.ArrayList(u8) = .empty;
    defer expected.deinit(std.testing.allocator);

    var state: u32 = 0x75a3_b19d;
    for (0..500) |_| {
        state = state *% 1_664_525 +% 1_013_904_223;
        if (expected.items.len == 0 or state & 3 == 0) {
            var literals: [19]u8 = undefined;
            const literal_len = 1 + (state % literals.len);
            for (literals[0..literal_len]) |*value| {
                state = state *% 1_664_525 +% 1_013_904_223;
                value.* = @truncate(state >> 16);
            }
            history.pushSlice(literals[0..literal_len]);
            try expected.appendSlice(std.testing.allocator, literals[0..literal_len]);
        } else {
            const available = @min(expected.items.len, storage.len);
            const distance = 1 + (state % available);
            state = state *% 1_664_525 +% 1_013_904_223;
            const copy_len = 1 + (state % 700);
            for (0..copy_len) |_| {
                try expected.append(std.testing.allocator, expected.items[expected.items.len - distance]);
            }
            history.copy(distance, copy_len);
        }

        const retained = @min(expected.items.len, storage.len);
        for (0..retained) |i| {
            const actual = storage[(history.tail_start + i) % storage.len];
            try std.testing.expectEqual(expected.items[expected.items.len - retained + i], actual);
        }
        try std.testing.expectEqual(retained, history.tail_len);
        try std.testing.expectEqual(expected.items[expected.items.len - 1], history.previous[1]);
        if (expected.items.len >= 2)
            try std.testing.expectEqual(expected.items[expected.items.len - 2], history.previous[0]);
    }
}

pub fn encodeStoredStreamAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    return try encodeStoredStreamWithOptionsAlloc(allocator, input, .{});
}

pub fn encodeStoredStreamWithOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, options: StoredStreamOptions) Error![]u8 {
    const output = try allocator.alloc(u8, try encodedStoredStreamBoundWithOptions(input.len, options));
    errdefer allocator.free(output);
    const written = try encodeStoredStreamWithOptionsInto(input, output, options);
    if (written != output.len) return error.SizeMismatch;
    return output;
}

pub fn encodeStoredStreamChunksAlloc(allocator: std.mem.Allocator, chunks: []const []const u8) Error![]u8 {
    return try encodeStoredStreamChunksWithOptionsAlloc(allocator, chunks, .{});
}

pub fn encodeStoredStreamChunksWithOptionsAlloc(allocator: std.mem.Allocator, chunks: []const []const u8, options: StoredStreamOptions) Error![]u8 {
    const output = try allocator.alloc(u8, try encodedStoredStreamChunksBoundWithOptions(chunks, options));
    errdefer allocator.free(output);
    const written = try encodeStoredStreamChunksWithOptionsInto(chunks, output, options);
    if (written != output.len) return error.SizeMismatch;
    return output;
}

pub fn encodeStoredStreamAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8) Error!void {
    try encodeStoredStreamWithOptionsAppend(allocator, out, input, .{});
}

pub fn encodeStoredStreamWithOptionsAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8, options: StoredStreamOptions) Error!void {
    var writer = BitWriter{ .out = out };
    try encodeStoredStreamWithOptionsWrite(allocator, &writer, input, options);
}

pub fn encodeStoredStreamChunksAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), chunks: []const []const u8) Error!void {
    try encodeStoredStreamChunksWithOptionsAppend(allocator, out, chunks, .{});
}

pub fn encodeStoredStreamChunksWithOptionsAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), chunks: []const []const u8, options: StoredStreamOptions) Error!void {
    var writer = BitWriter{ .out = out };
    try encodeStoredStreamChunksWithOptionsWrite(allocator, &writer, chunks, options);
}

/// Encode a single-byte run as one compressed Brotli meta-block. This is a
/// deliberately narrow first production compressed-encoder slice; non-runs or
/// lengths below five are rejected rather than silently falling back to stored.
pub fn encodeRleStreamAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try encodeRleStreamAppend(allocator, &out, input);
    return out.toOwnedSlice(allocator);
}

/// Encode the already externally-validated `ababa` compressed-distance shape.
/// This intentionally exposes only the proven five-byte slice while the
/// general command/literal encoder is still under construction.
pub fn encodeAbabaStreamAlloc(allocator: std.mem.Allocator) Error![]u8 {
    return encodeAbabaPatternStreamAlloc(allocator, 'a', 'b');
}

pub fn encodeAbabaPatternStreamAlloc(allocator: std.mem.Allocator, first: u8, second: u8) Error![]u8 {
    return encodeAlternatingStreamAlloc(allocator, first, second, 5);
}

pub fn encodeAlternatingStreamAlloc(allocator: std.mem.Allocator, first: u8, second: u8, len: usize) Error![]u8 {
    if (first == second or len < 5 or len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var writer = BitWriter{ .out = &out };
    try writeWindowBits(allocator, &writer, default_window_bits);
    try writeLastCompressedMetaBlockHeader(allocator, &writer, len);
    const copy_len = len - 2;
    const entry = commandEntryForLengths(2, copy_len) orelse return error.InvalidBlockPlan;
    try writeMinimalCompressedHeaderForAlternatingPattern(allocator, &writer, first, second, entry.symbol);
    if (entry.command.copy_extra_bits != 0)
        try writer.writeBits(allocator, copy_len - entry.command.copy_base, entry.command.copy_extra_bits);
    // Two-symbol simple trees assign code 0/1 by listed symbol order.
    try writer.writeBits(allocator, 0, 1);
    try writer.writeBits(allocator, 1, 1);
    if (writer.bit_index != 0) writer.alignToByte();
    return out.toOwnedSlice(allocator);
}

/// Encode a byte prefix followed by copies of that prefix. This is the first
/// production multi-command Brotli slice: it emits one seed command and one
/// copy command per repetition instead of relying on a
/// single copy whose overlap happens to generate the rest of the payload.
pub fn encodeRepeatedPrefixStreamAlloc(allocator: std.mem.Allocator, prefix: []const u8, repeat_count: usize) Error![]u8 {
    if (prefix.len < 2 or prefix.len > 4 or repeat_count < 2) return error.InvalidBlockPlan;
    const len = std.math.mul(usize, prefix.len, repeat_count) catch return error.IntegerOverflow;
    if (len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    for (prefix, 0..) |byte, i|
        for (prefix[0..i]) |previous|
            if (byte == previous) return error.InvalidBlockPlan;

    const seed = commandEntryForLengths(prefix.len, prefix.len) orelse return error.InvalidBlockPlan;
    const copy = commandEntryForLengths(0, prefix.len) orelse return error.InvalidBlockPlan;
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var writer = BitWriter{ .out = &out };
    try writeWindowBits(allocator, &writer, default_window_bits);
    try writeLastCompressedMetaBlockHeader(allocator, &writer, len);
    try writeRepeatedPrefixCompressedHeader(allocator, &writer, prefix, seed.symbol, copy.symbol);
    try writer.writeBits(allocator, 1, 1); // seed command code
    try writeCommandLengthExtras(allocator, &writer, seed, prefix.len, prefix.len);
    var literal_lengths: [256]u4 = @splat(0);
    for (prefix, 0..) |byte, i| literal_lengths[byte] = if (prefix.len == 3 and i == 0) 1 else @intCast(std.math.log2_int_ceil(usize, prefix.len));
    const literal_encoder = try huffman.HuffmanTable(256).Encoder.init(&literal_lengths);
    for (prefix) |byte| try writer.writeBits(allocator, literal_encoder.codes[byte], literal_encoder.bits[byte]);
    for (1..repeat_count - 1) |_| {
        try writer.writeBits(allocator, 0, 1); // copy-only command code
        try writeCommandLengthExtras(allocator, &writer, copy, 0, prefix.len);
    }
    if (writer.bit_index != 0) writer.alignToByte();
    return out.toOwnedSlice(allocator);
}

/// Build a general single-meta-block Brotli command stream from the shared LZ77
/// matcher. Prefix alphabets use simple or complex trees automatically; inputs
/// outside the current one-block/32 KiB matcher contract return a precise error
/// so the convenience encoder can retain its stored fallback.
pub fn encodePlannedStreamAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    var stats: encoder_stats.PlannedEncodeStats = .{};
    return encodePlannedStreamAllocWithStats(allocator, input, &stats);
}

pub fn encodePlannedStreamWithOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, options: PlannedEncodeOptions) Error![]u8 {
    try validatePlannedEncodeOptions(input.len, options);
    return switch (options.level) {
        .fast, .balanced => encodePlannedStreamOrStoredAlloc(allocator, input, options),
        .ratio => encodePlannedStreamRatioWithOptionsAlloc(allocator, input, options),
    };
}

/// Conservative bound for every stable planned level. Stable selection always
/// falls back to the stored representation before returning a larger stream.
pub fn encodedPlannedStreamBound(input_len: usize) Error!usize {
    return encodedPlannedStreamBoundWithOptions(input_len, .{});
}

pub fn encodedPlannedStreamBoundWithOptions(input_len: usize, options: PlannedEncodeOptions) Error!usize {
    try validatePlannedEncodeOptions(input_len, options);
    const window_bits = options.window_bits orelse default_window_bits;
    return encodedStoredStreamBoundWithOptions(input_len, .{ .window_bits = window_bits, .metadata = options.metadata });
}

/// Conservative bound for a fast planned stream with one independently
/// planned meta-block per non-empty chunk. Oversized chunks are split into
/// 32 KiB blocks so parser memory remains bounded.
pub fn encodedPlannedStreamChunksBound(chunks: []const []const u8) Error!usize {
    return encodedPlannedStreamChunksBoundWithOptions(chunks, .{});
}

pub fn encodedPlannedStreamChunksBoundWithOptions(chunks: []const []const u8, options: PlannedStreamChunksOptions) Error!usize {
    var bit_count = try storedWindowBitsLen(options.window_bits);
    if (options.metadata.len != 0)
        bit_count = try addStoredMetadataMetaBlockBitsLen(bit_count, options.metadata.len);
    for (chunks) |chunk| {
        var offset: usize = 0;
        while (offset < chunk.len) {
            const block_len = @min(chunk.len - offset, planned_chunk_max_input_len);
            bit_count = try addStoredUncompressedMetaBlockBitsLen(bit_count, block_len);
            offset += block_len;
        }
    }
    bit_count = std.math.add(usize, bit_count, 2) catch return error.IntegerOverflow;
    return bytesForBits(bit_count);
}

pub fn encodePlannedStreamChunksAlloc(allocator: std.mem.Allocator, chunks: []const []const u8) Error![]u8 {
    return encodePlannedStreamChunksWithOptionsAlloc(allocator, chunks, .{});
}

pub fn encodePlannedStreamChunksWithOptionsAlloc(allocator: std.mem.Allocator, chunks: []const []const u8, options: PlannedStreamChunksOptions) Error![]u8 {
    var encoder = PlannedStreamEncoder.init(allocator);
    defer encoder.deinit();
    return encoder.encodeChunksWithOptionsAlloc(allocator, chunks, options);
}

pub fn encodePlannedStreamChunksInto(chunks: []const []const u8, output: []u8) Error!usize {
    return encodePlannedStreamChunksWithOptionsInto(chunks, output, .{});
}

pub fn encodePlannedStreamChunksWithOptionsInto(chunks: []const []const u8, output: []u8, options: PlannedStreamChunksOptions) Error!usize {
    const needed = try encodedPlannedStreamChunksBoundWithOptions(chunks, options);
    if (output.len < needed) return error.OutOfMemory;
    var encoder = PlannedStreamEncoder.init(std.heap.smp_allocator);
    defer encoder.deinit();
    return encoder.encodeChunksWithOptionsInto(chunks, output, options);
}

pub fn encodePlannedStreamChunksAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), chunks: []const []const u8) Error!void {
    return encodePlannedStreamChunksWithOptionsAppend(allocator, out, chunks, .{});
}

pub fn encodePlannedStreamChunksWithOptionsAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), chunks: []const []const u8, options: PlannedStreamChunksOptions) Error!void {
    var encoder = PlannedStreamEncoder.init(allocator);
    defer encoder.deinit();
    try encoder.encodeChunksWithOptionsAppend(out, chunks, options);
}

pub fn encodePlannedStreamInto(input: []const u8, output: []u8) Error!usize {
    return encodePlannedStreamWithOptionsInto(input, output, .{});
}

pub fn encodePlannedStreamWithOptionsInto(input: []const u8, output: []u8, options: PlannedEncodeOptions) Error!usize {
    var encoder = PlannedStreamEncoder.init(std.heap.smp_allocator);
    defer encoder.deinit();
    return encoder.encodeIntoWithOptions(input, output, options);
}

fn encodePlannedStreamOrStoredAlloc(allocator: std.mem.Allocator, input: []const u8, options: PlannedEncodeOptions) Error![]u8 {
    const window_bits = options.window_bits orelse default_window_bits;
    const advertised_window_len = try plannedWindowLen(options.level, window_bits);
    const window_len = if (options.window_bits == null) lz77.default_window_len else advertised_window_len;
    const compressed = switch (options.level) {
        .fast => encodePlannedStreamAllocForWindow(allocator, input, window_bits, window_len, options.metadata),
        .balanced => encodePlannedStreamLazyWithWireOptionsAlloc(allocator, input, .{
            .window_len = window_len,
        }, .{ .window_bits = window_bits, .metadata = options.metadata }),
        .ratio => unreachable,
    };
    const encoded = compressed catch |err| switch (err) {
        error.InvalidBlockPlan => return encodeStoredStreamWithOptionsAlloc(allocator, input, .{ .window_bits = window_bits, .metadata = options.metadata }),
        else => return err,
    };
    return chooseStoredIfSmallerWithOptions(allocator, input, encoded, .{ .window_bits = window_bits, .metadata = options.metadata });
}

fn encodePlannedStreamAllocForWindow(allocator: std.mem.Allocator, input: []const u8, window_bits: u5, window_len: usize, metadata: []const u8) Error![]u8 {
    var stats: encoder_stats.PlannedEncodeStats = .{};
    return encodePlannedStreamAllocWithStatsTimedForWindow(allocator, input, null, &stats, window_bits, window_len, metadata);
}

/// Ratio-oriented planner variant using the shared lazy LZ77 parser. The wire
/// format and Huffman construction are identical to the fast planner; only the
/// token choice differs.
pub fn encodePlannedStreamLazyAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    return encodePlannedStreamLazyWithOptionsAlloc(allocator, input, .{});
}

/// Ratio-oriented level for callers willing to trade additional match-chain
/// search for smaller Brotli streams. Keeping this distinct from `.balanced`
/// makes the substantial encode-time cost explicit rather than silently
/// slowing latency-sensitive users. Short inputs without a backward match use
/// static-dictionary/stored arbitration so this stable level still accepts
/// arbitrary payloads inside its documented one-meta-block size range.
pub fn encodePlannedStreamRatioAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    return encodePlannedStreamRatioWithOptionsAlloc(allocator, input, .{ .level = .ratio });
}

/// Profile the exact default-window ratio pipeline for one bounded block. The
/// returned bytes have the same ownership and wire semantics as
/// `encodePlannedStreamRatioAlloc`; timing is intentionally isolated from the
/// production entry point so normal callers pay no instrumentation overhead.
pub fn profilePlannedRatioBlockAlloc(allocator: std.mem.Allocator, input: []const u8, io: std.Io, profile: *RatioEncodeProfile) Error![]u8 {
    if (input.len < 4 * 1024 or input.len > 64 * 1024) return error.InvalidBlockPlan;
    profile.* = .{ .input_bytes = input.len };
    const total_start = std.Io.Clock.awake.now(io);
    const parser_options = PlannedParserOptions{
        .window_len = @min(input.len, planner_max_backward_distance),
        .max_chain = 512,
        .nice_len = lz77.max_match_len,
    };

    var stage_start = std.Io.Clock.awake.now(io);
    const lazy_plan = try lz77.lazyGreedyPlanAlloc(allocator, input, .{
        .window_len = @min(input.len, parser_options.window_len),
        .max_chain = parser_options.max_chain,
        .nice_len = parser_options.nice_len,
        .max_candidates = 1,
        .lazy_min_gain = parser_options.lazy_min_gain,
        .min_match = 3,
        .max_match = lz77.max_match_len,
    });
    defer lazy_plan.deinit(allocator);
    profile.lazy_plan_ns = elapsedNs(stage_start, io);
    profile.lazy_token_count = lazy_plan.tokens.len;
    profile.lazy_literal_count = lazy_plan.stats.literals;
    profile.lazy_match_count = lazy_plan.stats.matches;
    profile.lazy_matched_bytes = lazy_plan.stats.matched_bytes;
    profile.lazy_fixed_bits = lz77.fixedBitCost(lazy_plan.tokens);
    if (lazy_plan.stats.matches == 0) {
        stage_start = std.Io.Clock.awake.now(io);
        const stored = try encodeStoredStreamAlloc(allocator, input);
        profile.selection_ns = elapsedNs(stage_start, io);
        profile.stored_bytes = stored.len;
        profile.selected_bytes = stored.len;
        profile.total_ns = elapsedNs(total_start, io);
        return stored;
    }

    profile.optimal_attempted = true;
    stage_start = std.Io.Clock.awake.now(io);
    const lazy_commands = try command_plan.buildAlloc(allocator, input, lazy_plan.tokens);
    defer lazy_commands.deinit(allocator);
    profile.lazy_command_ns = elapsedNs(stage_start, io);
    profile.lazy_command_count = lazy_commands.commands.len;
    const lazy_shape = try commandShapeStats(allocator, lazy_commands.commands);
    profile.lazy_recent_distance_count = lazy_shape.recent;
    profile.lazy_last_distance_count = lazy_shape.last;
    profile.lazy_explicit_distance_count = lazy_shape.explicit;
    profile.lazy_insert_code_histogram = lazy_shape.insert_codes;
    profile.lazy_copy_code_histogram = lazy_shape.copy_codes;
    profile.lazy_recent_symbol_histogram = lazy_shape.recent_symbols;
    profile.lazy_top_distances = lazy_shape.top_distances;
    profile.lazy_top_distance_counts = lazy_shape.top_distance_counts;

    var wire_stats: encoder_stats.PlannedEncodeStats = .{};
    stage_start = std.Io.Clock.awake.now(io);
    var selected = try encodeLazyCommandPlanAlloc(allocator, input, lazy_commands.commands, &wire_stats, .{
        .try_recent_distances = true,
        .try_literal_split = true,
        .try_command_split = true,
        .try_distance_split = true,
    });
    var selected_owned = true;
    errdefer if (selected_owned) allocator.free(selected);
    profile.lazy_wire_ns = elapsedNs(stage_start, io);
    profile.lazy_bytes = selected.len;

    stage_start = std.Io.Clock.awake.now(io);
    var optimal_profile: lz77.OptimalSearchProfile = .{};
    const optimal_plan = try lz77.optimalPlanAllocProfiled(allocator, input, .{
        .window_len = @min(input.len, @min(parser_options.window_len, lz77.default_window_len)),
        .max_chain = @min(parser_options.max_chain, 256),
        .nice_len = parser_options.nice_len,
        .max_candidates = 128,
        .min_match = 4,
        .max_match = lz77.max_match_len,
    }, io, &optimal_profile);
    defer optimal_plan.deinit(allocator);
    profile.optimal_plan_ns = elapsedNs(stage_start, io);
    profile.optimal_token_count = optimal_plan.tokens.len;
    profile.optimal_literal_count = optimal_plan.stats.literals;
    profile.optimal_match_count = optimal_plan.stats.matches;
    profile.optimal_matched_bytes = optimal_plan.stats.matched_bytes;
    profile.optimal_fixed_bits = lz77.fixedBitCost(optimal_plan.tokens);
    profile.optimal_index_bytes = optimal_profile.index_bytes;
    profile.optimal_positions = optimal_profile.positions;
    profile.optimal_chain_nodes = optimal_profile.chain_nodes;
    profile.optimal_prefix_rejections = optimal_profile.prefix_rejections;
    profile.optimal_prefix_mismatch_histogram = optimal_profile.prefix_mismatch_histogram;
    profile.optimal_bound_rejections = optimal_profile.bound_rejections;
    profile.optimal_bound_length_histogram = optimal_profile.bound_length_histogram;
    profile.optimal_bound_distance_cost_histogram = optimal_profile.bound_distance_cost_histogram;
    profile.optimal_bound_slack_histogram = optimal_profile.bound_slack_histogram;
    profile.optimal_match_length_calls = optimal_profile.match_length_calls;
    profile.optimal_valid_match_candidates = optimal_profile.valid_match_candidates;
    profile.optimal_length_choices_built = optimal_profile.length_choices_built;
    profile.optimal_length_extension_histogram = optimal_profile.length_extension_histogram;
    profile.optimal_candidate_budget_stops = optimal_profile.candidate_budget_stops;
    profile.optimal_index_ns = optimal_profile.index_ns;
    profile.optimal_search_ns = optimal_profile.search_ns;
    profile.optimal_reconstruct_ns = optimal_profile.reconstruct_ns;

    if (optimal_plan.stats.matches != 0) {
        stage_start = std.Io.Clock.awake.now(io);
        const optimal_commands = try command_plan.buildAlloc(allocator, input, optimal_plan.tokens);
        defer optimal_commands.deinit(allocator);
        profile.optimal_command_ns = elapsedNs(stage_start, io);
        profile.optimal_command_count = optimal_commands.commands.len;
        const optimal_shape = try commandShapeStats(allocator, optimal_commands.commands);
        profile.optimal_recent_distance_count = optimal_shape.recent;
        profile.optimal_last_distance_count = optimal_shape.last;
        profile.optimal_explicit_distance_count = optimal_shape.explicit;
        profile.optimal_insert_code_histogram = optimal_shape.insert_codes;
        profile.optimal_copy_code_histogram = optimal_shape.copy_codes;
        profile.optimal_recent_symbol_histogram = optimal_shape.recent_symbols;
        profile.optimal_top_distances = optimal_shape.top_distances;
        profile.optimal_top_distance_counts = optimal_shape.top_distance_counts;

        stage_start = std.Io.Clock.awake.now(io);
        const optimal_candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, optimal_commands.commands, null, &wire_stats, .{
            .use_recent_distances = true,
            .use_utf8_text_contexts = true,
            .utf8_context_cutoff = 48,
            .ndirect = 0,
        });
        profile.optimal_wire_ns = elapsedNs(stage_start, io);
        profile.optimal_bytes = optimal_candidate.len;
        if (optimal_candidate.len < selected.len) {
            allocator.free(selected);
            selected = optimal_candidate;
            profile.optimal_selected = true;
        } else allocator.free(optimal_candidate);
    }

    if (vortBrStableFixedWidthRecord(input.ptr, input.len) != 0) {
        profile.record_optimal_attempted = true;
        stage_start = std.Io.Clock.awake.now(io);
        const record_plan = (try recordOptimalPlanAlloc(allocator, input)) orelse return error.InvalidBlockPlan;
        defer record_plan.deinit(allocator);
        const record_commands = try command_plan.buildAlloc(allocator, input, record_plan.tokens);
        defer record_commands.deinit(allocator);
        const record_shape = try commandShapeStats(allocator, record_commands.commands);
        const record = try encodeCommandPlanWithOptionsAlloc(allocator, input, record_commands.commands, null, &wire_stats, .{
            .use_recent_distances = true,
            // Fixed-width record literals share one stable alphabet. A second
            // UTF-8 context tree adds more header cost than payload savings.
            .use_utf8_text_contexts = false,
            .optimize_literal_tree_wire = true,
            .utf8_context_cutoff = 48,
            .ndirect = 0,
        });
        profile.record_optimal_ns = elapsedNs(stage_start, io);
        profile.record_optimal_bytes = record.len;
        profile.record_optimal_token_count = record_plan.tokens.len;
        profile.record_optimal_literal_count = record_plan.stats.literals;
        profile.record_optimal_match_count = record_plan.stats.matches;
        profile.record_optimal_matched_bytes = record_plan.stats.matched_bytes;
        profile.record_optimal_command_count = record_commands.commands.len;
        profile.record_optimal_fixed_bits = lz77.fixedBitCost(record_plan.tokens);
        profile.record_optimal_recent_distance_count = record_shape.recent;
        profile.record_optimal_last_distance_count = record_shape.last;
        profile.record_optimal_explicit_distance_count = record_shape.explicit;
        profile.record_optimal_insert_code_histogram = record_shape.insert_codes;
        profile.record_optimal_copy_code_histogram = record_shape.copy_codes;
        profile.record_optimal_recent_symbol_histogram = record_shape.recent_symbols;
        profile.record_optimal_top_distances = record_shape.top_distances;
        profile.record_optimal_top_distance_counts = record_shape.top_distance_counts;
        if (record.len < selected.len) {
            allocator.free(selected);
            selected = record;
            profile.record_optimal_selected = true;
            profile.optimal_selected = false;
        } else allocator.free(record);
    }

    stage_start = std.Io.Clock.awake.now(io);
    profile.stored_bytes = try encodedStoredStreamBound(input.len);
    selected_owned = false;
    const result = try chooseStoredIfSmaller(allocator, input, selected);
    profile.selection_ns = elapsedNs(stage_start, io);
    profile.selected_bytes = result.len;
    profile.total_ns = elapsedNs(total_start, io);
    return result;
}

fn encodePlannedStreamRatioWithOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, options: PlannedEncodeOptions) Error![]u8 {
    const use_record_optimal = (options.window_bits == null or options.window_bits.? == default_window_bits) and
        input.len >= 4 * 1024 and input.len <= 64 * 1024 and
        input[input.len - 1] == '\n' and vortBrStableFixedWidthRecord(input.ptr, input.len) != 0;
    const explicit_window_bits = options.window_bits;
    const window_bits = options.window_bits orelse default_window_bits;
    const window_len = try plannedWindowLen(.ratio, window_bits);
    const primary_window_len = @min(window_len, planner_max_backward_distance);
    if (input.len > max_uncompressed_meta_block_len) {
        // A Brotli meta-block can describe at most 2^24 output bytes. Keep the
        // stable ratio API total over larger slices by emitting one bounded
        // stream of independently planned blocks rather than failing or
        // returning concatenated Brotli streams (which the format forbids).
        const chunks = [_][]const u8{input};
        return encodePlannedStreamChunksWithOptionsAlloc(allocator, &chunks, .{ .window_bits = window_bits, .metadata = options.metadata });
    }
    if (input.len < 5) return encodeStoredStreamWithOptionsAlloc(allocator, input, .{ .window_bits = window_bits, .metadata = options.metadata });
    const parser_options = PlannedParserOptions{
        .window_len = primary_window_len,
        .max_chain = 512,
        .nice_len = lz77.max_match_len,
    };
    const lz_plan = try lz77.lazyGreedyPlanAlloc(allocator, input, .{
        .window_len = @min(input.len, parser_options.window_len),
        .max_chain = parser_options.max_chain,
        .nice_len = parser_options.nice_len,
        .max_candidates = 1,
        .lazy_min_gain = parser_options.lazy_min_gain,
        .min_match = 3,
        .max_match = lz77.max_match_len,
    });
    defer lz_plan.deinit(allocator);
    if (lz_plan.stats.matches == 0) {
        if (input.len <= ratio_static_dictionary_max_input_len) {
            return encodeRatioStaticDictionaryOrStoredAlloc(allocator, input, window_bits, options.metadata);
        }
        var baseline = try encodeStoredStreamWithOptionsAlloc(allocator, input, .{ .window_bits = window_bits, .metadata = options.metadata });
        errdefer allocator.free(baseline);
        if (options.extended_dictionary_probes != 0) {
            const literal_plan = [_]command_plan.Command{.{
                .insert_start = 0,
                .insert_len = input.len,
            }};
            try selectExtendedRatioStaticDictionary(allocator, input, &literal_plan, window_bits, options.metadata, options.extended_dictionary_probes, &baseline);
        }
        return baseline;
    }
    const plan = try command_plan.buildAlloc(allocator, input, lz_plan.tokens);
    defer plan.deinit(allocator);
    var stats: encoder_stats.PlannedEncodeStats = .{};
    var baseline = try encodeLazyCommandPlanAlloc(allocator, input, plan.commands, &stats, .{
        .try_recent_distances = true,
        .try_literal_split = true,
        .try_command_split = true,
        .try_distance_split = true,
        .window_bits = window_bits,
        .metadata = options.metadata,
    });
    errdefer allocator.free(baseline);

    // The shared optimal parser uses a bounded fixed-bit proxy rather than
    // Brotli's final Huffman cost. Run it only for moderate ratio-mode blocks,
    // then retain it solely when exact wire encoding beats the lazy baseline.
    // This makes the new search monotonic in output size and keeps large-input
    // memory/latency on the existing path.
    if (input.len >= 4 * 1024 and input.len <= 64 * 1024) {
        if (use_record_optimal)
            try selectRecordOptimalRatioCandidate(allocator, input, window_bits, options.metadata, &stats, &baseline)
        else
            try selectOptimalRatioCandidates(allocator, input, parser_options, window_bits, options.metadata, &stats, &baseline);
    }
    if (input.len <= ratio_static_dictionary_max_input_len) return selectRatioStaticDictionaryAlloc(allocator, input, plan.commands, baseline, window_bits, options.metadata);
    if (options.extended_dictionary_probes != 0)
        try selectExtendedRatioStaticDictionary(allocator, input, plan.commands, window_bits, options.metadata, options.extended_dictionary_probes, &baseline);
    if ((explicit_window_bits != null and window_bits < 17) or input.len <= long_distance.min_distance)
        return chooseStoredIfSmallerWithOptions(allocator, input, baseline, .{ .window_bits = window_bits, .metadata = options.metadata });

    const long_window_bits: u5 = explicit_window_bits orelse 17;
    const long_max_distance = (@as(usize, 1) << long_window_bits) - 16;
    const commands = try long_distance.augmentAllocWithMaxDistance(allocator, input, plan.commands, long_max_distance) orelse return chooseStoredIfSmallerWithOptions(allocator, input, baseline, .{ .window_bits = window_bits, .metadata = options.metadata });
    defer allocator.free(commands);
    const candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, commands, null, &stats, .{
        .use_recent_distances = true,
        .use_utf8_text_contexts = true,
        .window_bits = long_window_bits,
        .metadata = options.metadata,
    });
    if (candidate.len < baseline.len) {
        allocator.free(baseline);
        return if (explicit_window_bits == null)
            chooseStoredIfSmallerWithOptions(allocator, input, candidate, .{ .metadata = options.metadata })
        else
            chooseStoredIfSmallerWithOptions(allocator, input, candidate, .{ .window_bits = window_bits, .metadata = options.metadata });
    }
    allocator.free(candidate);
    return chooseStoredIfSmallerWithOptions(allocator, input, baseline, .{ .window_bits = window_bits, .metadata = options.metadata });
}

fn selectOptimalRatioCandidates(allocator: std.mem.Allocator, input: []const u8, parser_options: PlannedParserOptions, window_bits: u5, metadata: []const u8, stats: *encoder_stats.PlannedEncodeStats, baseline: *[]u8) Error!void {
    // Four-byte matching avoids expensive one-off command/distance symbols on
    // the retained source corpus. The fixed-bit DP is only a proposal stage:
    // exact Brotli wire size decides whether the candidate survives.
    const optimal_plan = try lz77.optimalPlanAlloc(allocator, input, .{
        // `optimalPlanAlloc` currently has a precomputed 32 KiB distance-cost
        // table. The existing lazy and long-distance paths cover farther hits.
        .window_len = @min(input.len, @min(parser_options.window_len, lz77.default_window_len)),
        .max_chain = @min(parser_options.max_chain, 256),
        .nice_len = parser_options.nice_len,
        .max_candidates = 128,
        .min_match = 4,
        .max_match = lz77.max_match_len,
    });
    defer optimal_plan.deinit(allocator);
    if (optimal_plan.stats.matches == 0) return;
    const optimal_commands = try command_plan.buildAlloc(allocator, input, optimal_plan.tokens);
    defer optimal_commands.deinit(allocator);
    const candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, optimal_commands.commands, null, stats, .{
        .use_recent_distances = true,
        .use_utf8_text_contexts = true,
        .utf8_context_cutoff = 48,
        .ndirect = 0,
        .window_bits = window_bits,
        .metadata = metadata,
    });
    if (candidate.len < baseline.*.len) {
        allocator.free(baseline.*);
        baseline.* = candidate;
    } else allocator.free(candidate);
}

fn recordOptimalPlanAlloc(allocator: std.mem.Allocator, input: []const u8) Error!?lz77.GreedyPlan {
    if (input.len < 4 * 1024 or input.len > 64 * 1024) return null;
    const head = try allocator.alloc(u32, record_optimal_abi.hash_head_len);
    defer allocator.free(head);
    const head_initialized = try allocator.alloc(u64, record_optimal_abi.hash_head_init_words);
    defer allocator.free(head_initialized);
    const prev = try allocator.alloc(u32, input.len);
    defer allocator.free(prev);
    const costs = try allocator.alloc(u32, input.len + 1);
    defer allocator.free(costs);
    const steps = try allocator.alloc(u32, input.len);
    defer allocator.free(steps);
    const abi_tokens = try allocator.alloc(record_optimal_abi.Token, input.len);
    defer allocator.free(abi_tokens);
    var abi_stats: record_optimal_abi.Stats = .{};
    if (vortBrRecordOptimalPlan(input.ptr, input.len, head.ptr, head_initialized.ptr, prev.ptr, costs.ptr, steps.ptr, abi_tokens.ptr, &abi_stats) == 0) return null;
    if (vortBrRefineRecordDistances(input.ptr, input.len, abi_tokens.ptr, abi_stats.token_count) == 0) return error.InvalidBlockPlan;
    if (abi_stats.token_count > input.len or abi_stats.literal_count + abi_stats.matched_bytes != input.len or abi_stats.literal_count + abi_stats.match_count != abi_stats.token_count) return error.InvalidBlockPlan;
    const tokens = try allocator.alloc(lz77.Token, abi_stats.token_count);
    errdefer allocator.free(tokens);
    for (tokens, abi_tokens[0..abi_stats.token_count]) |*token, abi_token| {
        token.* = switch (abi_token.kind) {
            0 => .{ .literal = abi_token.literal },
            1 => .{ .match = .{ .length = abi_token.length, .distance = abi_token.distance } },
            else => return error.InvalidBlockPlan,
        };
    }
    return .{
        .tokens = tokens,
        .stats = .{
            .literals = abi_stats.literal_count,
            .matches = abi_stats.match_count,
            .matched_bytes = abi_stats.matched_bytes,
        },
    };
}

fn selectRecordOptimalRatioCandidate(allocator: std.mem.Allocator, input: []const u8, window_bits: u5, metadata: []const u8, stats: *encoder_stats.PlannedEncodeStats, baseline: *[]u8) Error!void {
    const record = (try encodeRecordOptimalCandidateWithOptionsAlloc(allocator, input, window_bits, metadata, stats)) orelse return;
    if (record.len < baseline.*.len) {
        allocator.free(baseline.*);
        baseline.* = record;
    } else allocator.free(record);
}

fn encodeRecordOptimalCandidateWithOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, window_bits: u5, metadata: []const u8, stats: *encoder_stats.PlannedEncodeStats) Error!?[]u8 {
    const plan = (try recordOptimalPlanAlloc(allocator, input)) orelse return null;
    defer plan.deinit(allocator);
    const commands = try command_plan.buildAlloc(allocator, input, plan.tokens);
    defer commands.deinit(allocator);
    const encoded = try encodeCommandPlanWithOptionsAlloc(allocator, input, commands.commands, null, stats, .{
        .use_recent_distances = true,
        // The record classifier already proves a stable field layout; one
        // literal tree is smaller across the audited record family.
        .use_utf8_text_contexts = false,
        .optimize_literal_tree_wire = true,
        .utf8_context_cutoff = 48,
        .ndirect = 0,
        .window_bits = window_bits,
        .metadata = metadata,
    });
    return encoded;
}

fn chooseStoredIfSmaller(allocator: std.mem.Allocator, input: []const u8, compressed: []u8) Error![]u8 {
    return chooseStoredIfSmallerWithWindow(allocator, input, compressed, default_window_bits);
}

fn chooseStoredIfSmallerWithWindow(allocator: std.mem.Allocator, input: []const u8, compressed: []u8, window_bits: u5) Error![]u8 {
    return chooseStoredIfSmallerWithOptions(allocator, input, compressed, .{ .window_bits = window_bits });
}

fn chooseStoredIfSmallerWithOptions(allocator: std.mem.Allocator, input: []const u8, compressed: []u8, options: StoredStreamOptions) Error![]u8 {
    errdefer allocator.free(compressed);
    const stored_len = try encodedStoredStreamBoundWithOptions(input.len, options);
    if (compressed.len <= stored_len) return compressed;
    const stored = try encodeStoredStreamWithOptionsAlloc(allocator, input, options);
    allocator.free(compressed);
    return stored;
}

// The indexed static-dictionary planner is still substantially more expensive
// than LZ77, so ratio mode only evaluates it for short payloads where RFC 7932
// words can dominate the complete stream. Exact final-byte arbitration keeps
// ordinary short JSON/source data from regressing in size.
const ratio_static_dictionary_max_input_len: usize = 256;
const ratio_extended_static_dictionary_max_input_len: usize = 4096;
const ratio_static_dictionary_candidate_capacity: usize = encodedStoredStreamBoundWithOptions(ratio_static_dictionary_max_input_len, .{ .window_bits = 10 }) catch unreachable;

fn validatePlannedEncodeOptions(input_len: usize, options: PlannedEncodeOptions) Error!void {
    const window_bits = options.window_bits orelse default_window_bits;
    _ = try plannedWindowLen(options.level, window_bits);
    if (options.extended_dictionary_probes == 0) return;
    if (options.level != .ratio or
        options.extended_dictionary_probes > max_extended_dictionary_probes or
        input_len > ratio_extended_static_dictionary_max_input_len)
        return error.InvalidBlockPlan;
}

fn selectExtendedRatioStaticDictionary(allocator: std.mem.Allocator, input: []const u8, lz_commands: []const command_plan.Command, window_bits: u5, metadata: []const u8, probe_limit: usize, baseline: *[]u8) Error!void {
    std.debug.assert(input.len > ratio_static_dictionary_max_input_len);
    std.debug.assert(input.len <= ratio_extended_static_dictionary_max_input_len);
    std.debug.assert(probe_limit != 0 and probe_limit <= max_extended_dictionary_probes);
    const mixed_plan = try command_plan.mixStaticDictionaryWithCacheProbeLimitAlloc(allocator, input, lz_commands, null, probe_limit);
    defer mixed_plan.deinit(allocator);
    if (mixed_plan.match_count == 0) return;

    var stats: encoder_stats.PlannedEncodeStats = .{};
    const candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, mixed_plan.commands, null, &stats, .{
        .window_bits = window_bits,
        .metadata = metadata,
    });
    if (candidate.len < baseline.*.len) {
        allocator.free(baseline.*);
        baseline.* = candidate;
    } else allocator.free(candidate);
}

fn encodeRatioStaticDictionaryOrStoredAlloc(allocator: std.mem.Allocator, input: []const u8, window_bits: u5, metadata: []const u8) Error![]u8 {
    const plan = try command_plan.buildStaticDictionaryAlloc(allocator, input);
    defer plan.deinit(allocator);
    const stream_options = StoredStreamOptions{ .window_bits = window_bits, .metadata = metadata };
    if (plan.match_count == 0) return encodeStoredStreamWithOptionsAlloc(allocator, input, stream_options);
    if (metadata.len != 0) {
        var stats: encoder_stats.PlannedEncodeStats = .{};
        const candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, plan.commands, null, &stats, .{ .window_bits = window_bits, .metadata = metadata });
        return chooseStoredIfSmallerWithOptions(allocator, input, candidate, stream_options);
    }

    const stored_len = try encodedStoredStreamBoundWithOptions(input.len, stream_options);
    var candidate_storage: [ratio_static_dictionary_candidate_capacity]u8 = undefined;
    var stats: encoder_stats.PlannedEncodeStats = .{};
    const candidate_len = encodeCommandPlanWithOptionsInto(allocator, candidate_storage[0..stored_len], input, plan.commands, &stats, .{ .window_bits = window_bits, .metadata = metadata }) catch |err| switch (err) {
        error.OutOfMemory => return encodeStoredStreamWithOptionsAlloc(allocator, input, stream_options),
        else => return err,
    };
    if (candidate_len >= stored_len) return encodeStoredStreamWithOptionsAlloc(allocator, input, stream_options);
    return allocator.dupe(u8, candidate_storage[0..candidate_len]);
}

fn selectRatioStaticDictionaryAlloc(allocator: std.mem.Allocator, input: []const u8, lz_commands: []const command_plan.Command, baseline: []u8, window_bits: u5, metadata: []const u8) Error![]u8 {
    errdefer allocator.free(baseline);
    var best = baseline;
    var cached_matches: [ratio_static_dictionary_max_input_len]static_dictionary.Match = undefined;
    var cache_known: [ratio_static_dictionary_max_input_len]bool = undefined;
    var match_cache = command_plan.StaticDictionaryMatchCache.init(cached_matches[0..input.len], cache_known[0..input.len]);
    var candidate_storage: [ratio_static_dictionary_candidate_capacity]u8 = undefined;
    // Anything reaching the stored ceiling cannot beat final arbitration, so
    // the exact stored bound is also a complete candidate-search budget.
    const stream_options = StoredStreamOptions{ .window_bits = window_bits, .metadata = metadata };
    if (metadata.len != 0) {
        const mixed_plan = try command_plan.mixStaticDictionaryWithCacheAlloc(allocator, input, lz_commands, &match_cache);
        defer mixed_plan.deinit(allocator);
        if (mixed_plan.match_count != 0 and !allCopiesAreDictionary(mixed_plan.commands)) {
            var mixed_stats: encoder_stats.PlannedEncodeStats = .{};
            const mixed = try encodeCommandPlanWithOptionsAlloc(allocator, input, mixed_plan.commands, null, &mixed_stats, .{ .window_bits = window_bits, .metadata = metadata });
            if (mixed.len < best.len) {
                allocator.free(best);
                best = mixed;
            } else allocator.free(mixed);
        }
        const dictionary_plan = try command_plan.buildStaticDictionaryWithCacheAlloc(allocator, input, &match_cache);
        defer dictionary_plan.deinit(allocator);
        if (dictionary_plan.match_count != 0) {
            var dictionary_stats: encoder_stats.PlannedEncodeStats = .{};
            const candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, dictionary_plan.commands, null, &dictionary_stats, .{ .window_bits = window_bits, .metadata = metadata });
            if (candidate.len < best.len) {
                allocator.free(best);
                best = candidate;
            } else allocator.free(candidate);
        }
        return chooseStoredIfSmallerWithOptions(allocator, input, best, stream_options);
    }
    const candidate_limit = @min(best.len, try encodedStoredStreamBoundWithOptions(input.len, stream_options));
    // The mixed planner is useful only when a backward copy survives alongside
    // dictionary copies. Otherwise its command stream is equivalent in shape
    // to the dictionary-only candidate encoded below, so skip a redundant full
    // wire encode.
    const mixed_plan = try command_plan.mixStaticDictionaryWithCacheAlloc(allocator, input, lz_commands, &match_cache);
    defer mixed_plan.deinit(allocator);
    if (mixed_plan.match_count != 0 and !allCopiesAreDictionary(mixed_plan.commands)) {
        var stats: encoder_stats.PlannedEncodeStats = .{};
        const mixed_len = encodeCommandPlanWithOptionsInto(allocator, candidate_storage[0..candidate_limit], input, mixed_plan.commands, &stats, .{ .window_bits = window_bits, .metadata = metadata }) catch |err| switch (err) {
            // A candidate that exhausts the current winner's byte budget cannot
            // win the strict final-size comparison, so no retry is needed.
            error.OutOfMemory => null,
            else => return err,
        };
        if (mixed_len) |len| if (len < best.len) {
            const mixed = try allocator.dupe(u8, candidate_storage[0..len]);
            allocator.free(best);
            best = mixed;
        };
    }
    const dictionary_plan = try command_plan.buildStaticDictionaryWithCacheAlloc(allocator, input, &match_cache);
    defer dictionary_plan.deinit(allocator);
    if (dictionary_plan.match_count == 0) return chooseStoredIfSmallerWithOptions(allocator, input, best, stream_options);
    var stats: encoder_stats.PlannedEncodeStats = .{};
    const candidate_len = encodeCommandPlanWithOptionsInto(allocator, candidate_storage[0..@min(candidate_limit, best.len)], input, dictionary_plan.commands, &stats, .{ .window_bits = window_bits, .metadata = metadata }) catch |err| switch (err) {
        error.OutOfMemory => return chooseStoredIfSmallerWithOptions(allocator, input, best, stream_options),
        else => return err,
    };
    if (candidate_len < best.len) {
        const candidate = try allocator.dupe(u8, candidate_storage[0..candidate_len]);
        allocator.free(best);
        return chooseStoredIfSmallerWithOptions(allocator, input, candidate, stream_options);
    }
    return chooseStoredIfSmallerWithOptions(allocator, input, best, stream_options);
}

fn allCopiesAreDictionary(commands: []const command_plan.Command) bool {
    var has_copy = false;
    for (commands) |command| {
        if (!command.has_copy) continue;
        has_copy = true;
        if (command.dictionary_output_len == 0) return false;
    }
    return has_copy;
}

/// Experimental entry point for measuring lazy-parser search budgets without
/// duplicating the production Brotli wire path. Zero-sized budgets are rejected
/// rather than silently changing the caller's requested search semantics.
pub fn encodePlannedStreamLazyWithOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, options: PlannedParserOptions) Error![]u8 {
    return encodePlannedStreamLazyWithWireOptionsAlloc(allocator, input, options, .{});
}

const CommandPlanEncodeOptions = struct {
    use_recent_distances: bool = false,
    use_utf8_text_contexts: bool = false,
    literal_split: ?usize = null,
    command_split: ?command_block_split.Result = null,
    distance_split: ?usize = null,
    utf8_context_cutoff: u6 = 56,
    ndirect: u7 = 15,
    window_bits: u5 = default_window_bits,
    metadata: []const u8 = "",
    write_stream_prefix: bool = true,
    final_meta_block: bool = true,
    optimize_literal_tree_wire: bool = false,
    optimize_same_last_distance: bool = true,
};
const min_recent_distance_candidate_count: usize = 64;
const planned_command_symbol_cache_capacity: usize = 128;
const LazyWireOptions = struct {
    try_recent_distances: bool = false,
    try_literal_split: bool = false,
    try_command_split: bool = false,
    try_distance_split: bool = false,
    window_bits: u5 = default_window_bits,
    metadata: []const u8 = "",
};

fn encodePlannedStreamLazyWithWireOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, options: PlannedParserOptions, wire_options: LazyWireOptions) Error![]u8 {
    if (input.len < 5 or input.len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    if (options.window_len == 0 or options.window_len > lz77.max_window_len or options.max_chain == 0 or options.nice_len == 0 or options.lazy_min_gain == 0) return error.InvalidBlockPlan;
    const lz_plan = try lz77.lazyGreedyPlanAlloc(allocator, input, .{
        .window_len = @min(input.len, options.window_len),
        .max_chain = options.max_chain,
        .nice_len = options.nice_len,
        // The lazy parser chooses one best match per position; unlike the
        // optimal parser, it has no separate candidate-count budget.
        .max_candidates = 1,
        .lazy_min_gain = options.lazy_min_gain,
        .min_match = 3,
        .max_match = lz77.max_match_len,
    });
    defer lz_plan.deinit(allocator);
    if (lz_plan.stats.matches == 0) return error.InvalidBlockPlan;
    const plan = try command_plan.buildAlloc(allocator, input, lz_plan.tokens);
    defer plan.deinit(allocator);
    var stats: encoder_stats.PlannedEncodeStats = .{};
    return encodeLazyCommandPlanAlloc(allocator, input, plan.commands, &stats, wire_options);
}

fn encodeLazyCommandPlanAlloc(allocator: std.mem.Allocator, input: []const u8, commands: []const command_plan.Command, stats: *encoder_stats.PlannedEncodeStats, wire_options: LazyWireOptions) Error![]u8 {
    // A leading three-byte match followed by exactly one remaining command is
    // often a net loss after its unique command/distance symbols are included.
    // Evaluate the one exact alternative instead of relying on DEFLATE's local
    // fixed-bit profitability model, which cannot see Brotli tree overhead.
    if (commands.len == 2 and commands[0].has_copy and commands[0].dictionary_output_len == 0 and commands[0].copy_len == 3) {
        const baseline = try encodePreferredCommandPlanAlloc(allocator, input, commands, null, stats, wire_options);
        errdefer allocator.free(baseline.encoded);
        var candidate_storage: [2]command_plan.Command = undefined;
        const candidate_commands = try command_plan.withoutCopyInto(&candidate_storage, input.len, commands, 0);
        const candidate = try encodePreferredCommandPlanAlloc(allocator, input, candidate_commands, null, stats, wire_options);
        if (candidate.encoded.len < baseline.encoded.len) {
            const split_candidate = encodeEntropySplitCandidateAlloc(allocator, input, candidate_commands, stats, wire_options, candidate) catch |err| {
                allocator.free(candidate.encoded);
                return err;
            };
            const selected = split_candidate orelse candidate.encoded;
            if (split_candidate != null) allocator.free(candidate.encoded);
            allocator.free(baseline.encoded);
            return selected;
        }
        allocator.free(candidate.encoded);
        if (try encodeEntropySplitCandidateAlloc(allocator, input, commands, stats, wire_options, baseline)) |split_candidate| {
            allocator.free(baseline.encoded);
            return split_candidate;
        }
        return baseline.encoded;
    }
    const short_match_alternatives = short_match_candidates.collect(commands);
    if (short_match_alternatives.len != 0) {
        var baseline = try encodePreferredCommandPlanAlloc(allocator, input, commands, null, stats, wire_options);
        errdefer allocator.free(baseline.encoded);
        var best_commands = commands;
        var best_command_storage: [16]command_plan.Command = undefined;
        var drop_storage: [4]usize = undefined;
        var command_storage: [16]command_plan.Command = undefined;
        for (short_match_alternatives.slice()) |drop_mask| {
            var drop_count: usize = 0;
            for (commands, 0..) |_, command_index| {
                if (drop_mask & (@as(u16, 1) << @intCast(command_index)) == 0) continue;
                drop_storage[drop_count] = command_index;
                drop_count += 1;
            }
            const alternative = try command_plan.withoutCopiesInto(&command_storage, input.len, commands, drop_storage[0..drop_count]);
            const candidate = try encodePreferredCommandPlanAlloc(allocator, input, alternative, null, stats, wire_options);
            if (candidate.encoded.len < baseline.encoded.len) {
                allocator.free(baseline.encoded);
                baseline = candidate;
                @memcpy(best_command_storage[0..alternative.len], alternative);
                best_commands = best_command_storage[0..alternative.len];
            } else allocator.free(candidate.encoded);
        }
        if (try encodeEntropySplitCandidateAlloc(allocator, input, best_commands, stats, wire_options, baseline)) |split_candidate| {
            allocator.free(baseline.encoded);
            return split_candidate;
        }
        return baseline.encoded;
    }
    const baseline = try encodePreferredCommandPlanAlloc(allocator, input, commands, null, stats, wire_options);
    errdefer allocator.free(baseline.encoded);
    if (try encodeEntropySplitCandidateAlloc(allocator, input, commands, stats, wire_options, baseline)) |split_candidate| {
        allocator.free(baseline.encoded);
        return split_candidate;
    }
    return baseline.encoded;
}

/// Experimental planner-backed encoder for the built-in RFC 7932 static
/// dictionary. It establishes complete command/wire support with an exhaustive
/// reference matcher; stable compression levels remain on the faster LZ path.
pub fn encodePlannedStreamStaticDictionaryAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    return encodePlannedStreamStaticDictionaryWithCacheAlloc(allocator, input, null);
}

fn encodePlannedStreamStaticDictionaryWithCacheAlloc(allocator: std.mem.Allocator, input: []const u8, cache: ?*command_plan.StaticDictionaryMatchCache) Error![]u8 {
    const max_backward_distance = (@as(usize, 1) << default_window_bits) - 16;
    if (input.len < 5 or input.len > max_backward_distance) return error.InvalidBlockPlan;
    const plan = try command_plan.buildStaticDictionaryWithCacheAlloc(allocator, input, cache);
    defer plan.deinit(allocator);
    if (plan.match_count == 0) return error.InvalidBlockPlan;
    var stats: encoder_stats.PlannedEncodeStats = .{};
    return encodeCommandPlanAlloc(allocator, input, plan.commands, null, &stats);
}

pub fn plannedStaticDictionaryIndexBytes() usize {
    return command_plan.staticDictionaryIndexBytes();
}

pub fn encodePlannedStreamAllocWithStats(allocator: std.mem.Allocator, input: []const u8, stats: *encoder_stats.PlannedEncodeStats) Error![]u8 {
    return encodePlannedStreamAllocWithStatsTimed(allocator, input, null, stats);
}

pub fn encodePlannedStreamAllocWithStatsTimed(allocator: std.mem.Allocator, input: []const u8, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats) Error![]u8 {
    return encodePlannedStreamAllocWithStatsTimedForWindow(allocator, input, io, stats, default_window_bits, lz77.default_window_len, "");
}

fn encodePlannedStreamAllocWithStatsTimedForWindow(allocator: std.mem.Allocator, input: []const u8, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats, window_bits: u5, window_len: usize, metadata: []const u8) Error![]u8 {
    if (input.len < 5 or input.len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    const lz_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    const lz_plan = try lz77.hashGreedyPlanAutoTinyAlloc(allocator, input, .{
        .window_len = @min(input.len, window_len),
        .max_chain = 64,
        .nice_len = 64,
        .max_candidates = 8,
        .min_match = 3,
        .max_match = lz77.max_match_len,
    });
    defer lz_plan.deinit(allocator);
    if (io) |active| stats.lz77_ns = elapsedNs(lz_start.?, active);
    if (lz_plan.stats.matches == 0) return error.InvalidBlockPlan;
    const command_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    const plan = try command_plan.buildAlloc(allocator, input, lz_plan.tokens);
    defer plan.deinit(allocator);
    if (io) |active| stats.command_plan_ns = elapsedNs(command_start.?, active);
    const wire_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    const encoded = try encodeCommandPlanWithOptionsAlloc(allocator, input, plan.commands, io, stats, .{ .window_bits = window_bits, .metadata = metadata });
    if (io) |active| stats.wire_ns = elapsedNs(wire_start.?, active);
    stats.input_bytes = input.len;
    stats.token_count = lz_plan.tokens.len;
    stats.command_count = plan.commands.len;
    stats.literal_bytes = lz_plan.stats.literals;
    stats.matched_bytes = lz_plan.stats.matched_bytes;
    stats.encoded_bytes = encoded.len;
    return encoded;
}

fn elapsedNs(start: std.Io.Timestamp, io: std.Io) u64 {
    const ns = start.durationTo(std.Io.Clock.awake.now(io)).nanoseconds;
    return if (ns <= 0) 0 else @intCast(ns);
}

/// Same planner-backed encoder with a caller-owned scratch arena for all
/// intermediate LZ77 tokens, command plans, wire commands, and prefix RLE. The
/// returned stream is owned by `allocator`; `OutOfMemory` reports an undersized
/// scratch buffer without silently allocating temporary state elsewhere.
pub fn encodePlannedStreamWithScratchAlloc(allocator: std.mem.Allocator, scratch: []u8, input: []const u8) Error![]u8 {
    if (input.len < 5 or input.len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    var fixed = std.heap.FixedBufferAllocator.init(scratch);
    const scratch_allocator = fixed.allocator();
    const lz_plan = try lz77.hashGreedyPlanAutoTinyAlloc(scratch_allocator, input, .{
        .window_len = @min(input.len, 32 * 1024),
        .max_chain = 64,
        .nice_len = 64,
        .max_candidates = 8,
        .min_match = 3,
        .max_match = lz77.max_match_len,
    });
    defer lz_plan.deinit(scratch_allocator);
    if (lz_plan.stats.matches == 0) return error.InvalidBlockPlan;
    const plan = try command_plan.buildAlloc(scratch_allocator, input, lz_plan.tokens);
    defer plan.deinit(scratch_allocator);
    var stats: encoder_stats.PlannedEncodeStats = .{};
    const encoded = try encodeCommandPlanAlloc(scratch_allocator, input, plan.commands, null, &stats);
    defer scratch_allocator.free(encoded);
    return allocator.dupe(u8, encoded);
}

/// Reusable planner encoder retaining arena capacity across calls. The result is
/// owned by the allocator passed to `encodeAlloc`; encoder state itself is not
/// thread-safe and must outlive no returned borrow (results are independent).
pub const PlannedStreamEncoder = struct {
    allocator: std.mem.Allocator,
    tokens: std.ArrayList(lz77.Token) = .empty,
    commands: std.ArrayList(command_plan.Command) = .empty,
    output: std.ArrayList(u8) = .empty,
    greedy_scratch: lz77.TinyGreedyScratch = .{},

    pub fn init(allocator: std.mem.Allocator) PlannedStreamEncoder {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *PlannedStreamEncoder) void {
        self.greedy_scratch.deinit(self.allocator);
        self.tokens.deinit(self.allocator);
        self.commands.deinit(self.allocator);
        self.output.deinit(self.allocator);
        self.* = undefined;
    }

    pub fn encodeAlloc(self: *PlannedStreamEncoder, allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
        return self.encodeWithOptionsAlloc(allocator, input, .{});
    }

    pub fn encodeChunksAlloc(self: *PlannedStreamEncoder, allocator: std.mem.Allocator, chunks: []const []const u8) Error![]u8 {
        return self.encodeChunksWithOptionsAlloc(allocator, chunks, .{});
    }

    pub fn encodeChunksWithOptionsAlloc(self: *PlannedStreamEncoder, allocator: std.mem.Allocator, chunks: []const []const u8, options: PlannedStreamChunksOptions) Error![]u8 {
        return allocator.dupe(u8, try self.encodeChunksScratchWithOptions(chunks, options));
    }

    pub fn encodeChunksInto(self: *PlannedStreamEncoder, chunks: []const []const u8, output: []u8) Error!usize {
        return self.encodeChunksWithOptionsInto(chunks, output, .{});
    }

    pub fn encodeChunksWithOptionsInto(self: *PlannedStreamEncoder, chunks: []const []const u8, output: []u8, options: PlannedStreamChunksOptions) Error!usize {
        const needed = try encodedPlannedStreamChunksBoundWithOptions(chunks, options);
        if (output.len < needed) return error.OutOfMemory;
        const encoded = try self.encodeChunksScratchWithOptions(chunks, options);
        @memcpy(output[0..encoded.len], encoded);
        return encoded.len;
    }

    pub fn encodeChunksAppend(self: *PlannedStreamEncoder, out: *std.ArrayList(u8), chunks: []const []const u8) Error!void {
        return self.encodeChunksWithOptionsAppend(out, chunks, .{});
    }

    pub fn encodeChunksWithOptionsAppend(self: *PlannedStreamEncoder, out: *std.ArrayList(u8), chunks: []const []const u8, options: PlannedStreamChunksOptions) Error!void {
        try out.appendSlice(self.allocator, try self.encodeChunksScratchWithOptions(chunks, options));
    }

    /// Encode through the stable level API while retaining token and command
    /// capacity for the fast and balanced small-block planners. Ratio and large
    /// inputs retain their one-shot paths because they need wider search state.
    pub fn encodeWithOptionsAlloc(self: *PlannedStreamEncoder, allocator: std.mem.Allocator, input: []const u8, options: PlannedEncodeOptions) Error![]u8 {
        try validatePlannedEncodeOptions(input.len, options);
        if (options.window_bits != null or options.metadata.len != 0)
            return encodePlannedStreamWithOptionsAlloc(allocator, input, options);
        if (options.level == .fast and input.len <= 32 * 1024)
            return allocator.dupe(u8, try self.encodeScratchWithOptions(input, options));
        if (options.level == .ratio or input.len > 32 * 1024) {
            return encodePlannedStreamWithOptionsAlloc(allocator, input, options);
        }
        if (input.len < 5) return encodeStoredStreamAlloc(allocator, input);
        const stats = switch (options.level) {
            .fast => try lz77.hashGreedyPlanAutoTinyScratchReuse(&self.tokens, &self.greedy_scratch, self.allocator, input, .{
                .window_len = input.len,
                .max_chain = 64,
                .nice_len = 64,
                .max_candidates = 8,
                .min_match = 3,
                .max_match = lz77.max_match_len,
            }),
            .balanced => try lz77.lazyGreedyPlanTinyReuse(&self.tokens, self.allocator, input, .{
                .window_len = input.len,
                .max_chain = 64,
                .nice_len = 64,
                .max_candidates = 1,
                .lazy_min_gain = 1,
                .min_match = 3,
                .max_match = lz77.max_match_len,
            }),
            .ratio => unreachable,
        };
        if (stats.matches == 0) return encodeStoredStreamAlloc(allocator, input);
        _ = try command_plan.buildTrustedReuse(&self.commands, self.allocator, input, self.tokens.items);
        var stats_out: encoder_stats.PlannedEncodeStats = .{};
        const compressed = if (options.level == .balanced)
            try encodeLazyCommandPlanAlloc(allocator, input, self.commands.items, &stats_out, .{})
        else
            try encodeCommandPlanAlloc(allocator, input, self.commands.items, null, &stats_out);
        return chooseStoredIfSmaller(allocator, input, compressed);
    }

    pub fn retainedCapacity(self: *const PlannedStreamEncoder) usize {
        return self.tokens.capacity * @sizeOf(lz77.Token) +
            self.commands.capacity * @sizeOf(command_plan.Command) +
            self.output.capacity +
            self.greedy_scratch.retainedCapacity();
    }

    /// Encode a fast-level stream into retained encoder-owned output. The
    /// returned slice is invalidated by the next call or by `deinit`. This path
    /// avoids allocating an owned result once input/output capacities stabilize.
    pub fn encodeScratch(self: *PlannedStreamEncoder, input: []const u8) Error![]const u8 {
        return self.encodeScratchWithOptions(input, .{});
    }

    /// Encode one Brotli stream containing multiple independently planned fast
    /// meta-blocks. Empty chunks are ignored, and chunks above 32 KiB are split
    /// to keep parser state bounded. The returned slice is invalidated by the
    /// next call or by `deinit`.
    pub fn encodeChunksScratch(self: *PlannedStreamEncoder, chunks: []const []const u8) Error![]const u8 {
        return self.encodeChunksScratchWithOptions(chunks, .{});
    }

    pub fn encodeChunksScratchWithOptions(self: *PlannedStreamEncoder, chunks: []const []const u8, options: PlannedStreamChunksOptions) Error![]const u8 {
        self.output.clearRetainingCapacity();
        var writer = BitWriter{ .out = &self.output };
        try writeWindowBits(self.allocator, &writer, options.window_bits);
        if (options.metadata.len != 0) try writeMetadataMetaBlock(self.allocator, &writer, options.metadata);
        const window_len = (@as(usize, 1) << options.window_bits) - 16;
        var stored_ceiling_bits = writer.bitPosition();
        for (chunks) |chunk| {
            var offset: usize = 0;
            while (offset < chunk.len) {
                const block_len = @min(chunk.len - offset, planned_chunk_max_input_len);
                stored_ceiling_bits = try addStoredUncompressedMetaBlockBitsLen(stored_ceiling_bits, block_len);
                try self.encodeFastMetaBlock(&writer, chunk[offset..][0..block_len], stored_ceiling_bits, window_len);
                offset += block_len;
            }
        }
        try writer.writeBits(self.allocator, 1, 1); // ISLAST.
        try writer.writeBits(self.allocator, 1, 1); // ISLASTEMPTY.
        return self.output.items;
    }

    fn encodeFastMetaBlock(self: *PlannedStreamEncoder, writer: *BitWriter, input: []const u8, stored_ceiling_bits: usize, window_len: usize) Error!void {
        std.debug.assert(input.len != 0 and input.len <= planned_chunk_max_input_len);
        const start_len = self.output.items.len;
        const start_bit_index = writer.bit_index;
        const start_byte = self.output.items[start_len - 1];
        const stats = try lz77.hashGreedyPlanAutoTinyScratchReuse(&self.tokens, &self.greedy_scratch, self.allocator, input, .{
            .window_len = @min(input.len, window_len),
            .max_chain = 64,
            .nice_len = 64,
            .max_candidates = 8,
            .min_match = 3,
            .max_match = lz77.max_match_len,
        });
        if (stats.matches == 0)
            return self.replacePlannedBlockWithStored(writer, input, start_len, start_bit_index, start_byte);
        _ = command_plan.buildTrustedReuse(&self.commands, self.allocator, input, self.tokens.items) catch |err| switch (err) {
            error.InvalidBlockPlan => return self.replacePlannedBlockWithStored(writer, input, start_len, start_bit_index, start_byte),
            else => return err,
        };
        var stats_out: encoder_stats.PlannedEncodeStats = .{};
        const compressed_ok = blk: {
            encodeCommandPlanWithOptionsWrite(self.allocator, writer, input, self.commands.items, null, &stats_out, .{
                .write_stream_prefix = false,
                .final_meta_block = false,
            }) catch |err| switch (err) {
                error.InvalidBlockPlan => break :blk false,
                else => return err,
            };
            break :blk true;
        };
        if (compressed_ok and writer.bitPosition() <= stored_ceiling_bits) return;
        try self.replacePlannedBlockWithStored(writer, input, start_len, start_bit_index, start_byte);
    }

    fn replacePlannedBlockWithStored(self: *PlannedStreamEncoder, writer: *BitWriter, input: []const u8, start_len: usize, start_bit_index: u3, start_byte: u8) Error!void {
        self.output.shrinkRetainingCapacity(start_len);
        self.output.items[start_len - 1] = start_byte;
        writer.bit_index = start_bit_index;
        try writeUncompressedMetaBlock(self.allocator, writer, input);
    }

    /// Encode into retained encoder-owned output. Fast and balanced reuse their
    /// parser, command, and output capacity for small blocks; ratio keeps the
    /// stable one-shot candidate selection and copies only its final winner.
    /// The returned slice is invalidated by the next call or by `deinit`.
    pub fn encodeScratchWithOptions(self: *PlannedStreamEncoder, input: []const u8, options: PlannedEncodeOptions) Error![]const u8 {
        try validatePlannedEncodeOptions(input.len, options);
        if (options.window_bits != null or options.metadata.len != 0 or options.level == .ratio or input.len > 32 * 1024) {
            const encoded = try encodePlannedStreamWithOptionsAlloc(self.allocator, input, options);
            defer self.allocator.free(encoded);
            self.output.clearRetainingCapacity();
            try self.output.appendSlice(self.allocator, encoded);
            return self.output.items;
        }
        self.output.clearRetainingCapacity();
        if (input.len < 5) {
            try encodeStoredStreamAppend(self.allocator, &self.output, input);
            return self.output.items;
        }
        const stats = switch (options.level) {
            .fast => try lz77.hashGreedyPlanAutoTinyScratchReuse(&self.tokens, &self.greedy_scratch, self.allocator, input, .{
                .window_len = input.len,
                .max_chain = 64,
                .nice_len = 64,
                .max_candidates = 8,
                .min_match = 3,
                .max_match = lz77.max_match_len,
            }),
            .balanced => try lz77.lazyGreedyPlanTinyReuse(&self.tokens, self.allocator, input, .{
                .window_len = input.len,
                .max_chain = 64,
                .nice_len = 64,
                .max_candidates = 1,
                .lazy_min_gain = 1,
                .min_match = 3,
                .max_match = lz77.max_match_len,
            }),
            .ratio => unreachable,
        };
        if (stats.matches == 0) {
            try encodeStoredStreamAppend(self.allocator, &self.output, input);
            return self.output.items;
        }
        _ = try command_plan.buildTrustedReuse(&self.commands, self.allocator, input, self.tokens.items);
        var stats_out: encoder_stats.PlannedEncodeStats = .{};
        const balanced_alternatives = options.level == .balanced and
            ((self.commands.items.len == 2 and self.commands.items[0].has_copy and self.commands.items[0].dictionary_output_len == 0 and self.commands.items[0].copy_len == 3) or
                short_match_candidates.collect(self.commands.items).len != 0);
        if (balanced_alternatives) {
            const encoded = try encodeLazyCommandPlanAlloc(self.allocator, input, self.commands.items, &stats_out, .{});
            defer self.allocator.free(encoded);
            try self.output.appendSlice(self.allocator, encoded);
        } else {
            try encodeCommandPlanWithOptionsAppend(self.allocator, &self.output, input, self.commands.items, null, &stats_out, .{});
        }
        const stored_len = try encodedStoredStreamBound(input.len);
        if (self.output.items.len > stored_len) {
            self.output.clearRetainingCapacity();
            try encodeStoredStreamAppend(self.allocator, &self.output, input);
        }
        return self.output.items;
    }

    /// Encode fast-level output directly into caller-owned storage. The bound
    /// is the exact stored-stream size because stable fast encoding never
    /// returns a larger compressed candidate.
    pub fn encodeInto(self: *PlannedStreamEncoder, input: []const u8, output: []u8) Error!usize {
        return self.encodeIntoWithOptions(input, output, .{});
    }

    pub fn encodeIntoWithOptions(self: *PlannedStreamEncoder, input: []const u8, output: []u8, options: PlannedEncodeOptions) Error!usize {
        const needed = try encodedPlannedStreamBoundWithOptions(input.len, options);
        if (output.len < needed) return error.OutOfMemory;
        if (options.window_bits != null or options.metadata.len != 0 or options.level != .fast) {
            // Route balanced through this encoder's retained token/command
            // buffers; ratio still delegates inside encodeWithOptionsAlloc.
            const encoded = try self.encodeWithOptionsAlloc(self.allocator, input, options);
            defer self.allocator.free(encoded);
            @memcpy(output[0..encoded.len], encoded);
            return encoded.len;
        }
        if (input.len > 32 * 1024) {
            const encoded = try encodePlannedStreamWithOptionsAlloc(self.allocator, input, options);
            defer self.allocator.free(encoded);
            @memcpy(output[0..encoded.len], encoded);
            return encoded.len;
        }
        if (input.len < 5) return encodeStoredStreamInto(input, output);
        const stats = try lz77.hashGreedyPlanAutoTinyScratchReuse(&self.tokens, &self.greedy_scratch, self.allocator, input, .{
            .window_len = input.len,
            .max_chain = 64,
            .nice_len = 64,
            .max_candidates = 8,
            .min_match = 3,
            .max_match = lz77.max_match_len,
        });
        if (stats.matches == 0) return encodeStoredStreamInto(input, output);
        _ = try command_plan.buildTrustedReuse(&self.commands, self.allocator, input, self.tokens.items);
        var out: std.ArrayList(u8) = .{ .items = output[0..0], .capacity = output.len };
        var stats_out: encoder_stats.PlannedEncodeStats = .{};
        // Bounded mode maps any unexpected underestimation to OutOfMemory
        // rather than allowing the writer to allocate behind the caller's back.
        // A compressed candidate may legitimately exceed the stored ceiling;
        // in that case discard the partial candidate and emit stored instead.
        var writer = BitWriter{ .out = &out, .bounded = true };
        encodeCommandPlanWithOptionsWrite(self.allocator, &writer, input, self.commands.items, null, &stats_out, .{}) catch |err| switch (err) {
            error.OutOfMemory => return encodeStoredStreamInto(input, output),
            else => return err,
        };
        if (out.items.len > needed) return encodeStoredStreamInto(input, output);
        return out.items.len;
    }
};

pub fn encodeRleStreamAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8) Error!void {
    var writer = BitWriter{ .out = out };
    try encodeRleStreamWrite(allocator, &writer, input);
}

pub fn encodedRleStreamBound(input_len: usize) Error!usize {
    if (input_len < 5 or input_len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    // The narrow header and one command are bounded well below 64 bytes for
    // every legal meta-block length; callers may use this stable conservative
    // bound without running the encoder twice.
    return 64;
}

pub fn encodeRleStreamInto(input: []const u8, output: []u8) Error!usize {
    _ = try encodedRleStreamBound(input.len);
    var out: std.ArrayList(u8) = .{ .items = output[0..0], .capacity = output.len };
    var writer = BitWriter{ .out = &out, .bounded = true };
    try encodeRleStreamWrite(std.heap.smp_allocator, &writer, input);
    return out.items.len;
}

pub fn encodedSimpleStreamBound(input_len: usize) Error!usize {
    return encodedStoredStreamBound(input_len);
}

/// Dependency-free Brotli encoder entry point that selects the compressed RLE
/// slice for eligible runs and otherwise emits the fully general stored form.
pub fn encodeSimpleStreamAlloc(allocator: std.mem.Allocator, input: []const u8) Error![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try encodeSimpleStreamAppend(allocator, &out, input);
    return out.toOwnedSlice(allocator);
}

pub fn encodeSimpleStreamAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8) Error!void {
    if (isRleInput(input)) {
        try encodeRleStreamAppend(allocator, out, input);
    } else if (alternatingLength(input)) |len| {
        const encoded = try encodeAlternatingStreamAlloc(allocator, input[0], input[1], len);
        defer allocator.free(encoded);
        try out.appendSlice(allocator, encoded);
    } else if (pattern.repeatedDistinctPrefixLength(input)) |period| {
        const encoded = try encodeRepeatedPrefixStreamAlloc(allocator, input[0..period], input.len / period);
        defer allocator.free(encoded);
        try out.appendSlice(allocator, encoded);
    } else {
        if (encodePlannedStreamAlloc(allocator, input)) |encoded| {
            defer allocator.free(encoded);
            try out.appendSlice(allocator, encoded);
            return;
        } else |err| switch (err) {
            error.InvalidBlockPlan => {},
            else => return err,
        }
        try encodeStoredStreamAppend(allocator, out, input);
    }
}

pub fn encodeSimpleStreamInto(input: []const u8, output: []u8) Error!usize {
    if (isRleInput(input)) return encodeRleStreamInto(input, output);
    if (alternatingLength(input)) |len| {
        const encoded = try encodeAlternatingStreamAlloc(std.heap.smp_allocator, input[0], input[1], len);
        defer std.heap.smp_allocator.free(encoded);
        if (output.len < encoded.len) return error.OutOfMemory;
        @memcpy(output[0..encoded.len], encoded);
        return encoded.len;
    }
    if (pattern.repeatedDistinctPrefixLength(input)) |period| {
        const encoded = try encodeRepeatedPrefixStreamAlloc(std.heap.smp_allocator, input[0..period], input.len / period);
        defer std.heap.smp_allocator.free(encoded);
        if (output.len < encoded.len) return error.OutOfMemory;
        @memcpy(output[0..encoded.len], encoded);
        return encoded.len;
    }
    if (encodePlannedStreamAlloc(std.heap.smp_allocator, input)) |encoded| {
        defer std.heap.smp_allocator.free(encoded);
        if (output.len < encoded.len) return error.OutOfMemory;
        @memcpy(output[0..encoded.len], encoded);
        return encoded.len;
    } else |err| switch (err) {
        error.InvalidBlockPlan => {},
        else => return err,
    }
    return encodeStoredStreamInto(input, output);
}

fn isRleInput(input: []const u8) bool {
    if (input.len < 5 or input.len > max_uncompressed_meta_block_len) return false;
    for (input[1..]) |byte| if (byte != input[0]) return false;
    return true;
}

fn alternatingLength(input: []const u8) ?usize {
    if (input.len < 5 or input.len > max_uncompressed_meta_block_len or input[0] == input[1]) return null;
    for (input, 0..) |byte, i|
        if (byte != input[i & 1]) return null;
    return input.len;
}

const CommandEncoding = struct { symbol: u16, command: command_lut.Entry };

const explicit_command_symbol_index = blk: {
    @setEvalBranchQuota(100_000);
    var index: [24][24]u16 = @splat(@splat(std.math.maxInt(u16)));
    for (command_lut.entries, 0..) |entry, symbol| {
        if (entry.distance_code != -1) continue;
        const insert_code = lengthCodeForValue(entry.insert_base, true) orelse continue;
        const copy_code = lengthCodeForValue(entry.copy_base, false) orelse continue;
        if (index[insert_code][copy_code] == std.math.maxInt(u16)) index[insert_code][copy_code] = @intCast(symbol);
    }
    break :blk index;
};
const last_distance_command_symbol_index = blk: {
    @setEvalBranchQuota(100_000);
    var index: [24][24]u16 = @splat(@splat(std.math.maxInt(u16)));
    for (command_lut.entries, 0..) |entry, symbol| {
        if (entry.distance_code != 0) continue;
        const insert_code = lengthCodeForValue(entry.insert_base, true) orelse continue;
        const copy_code = lengthCodeForValue(entry.copy_base, false) orelse continue;
        if (index[insert_code][copy_code] == std.math.maxInt(u16)) index[insert_code][copy_code] = @intCast(symbol);
    }
    break :blk index;
};

fn commandEntryForLengths(insert_len: usize, copy_len: usize) ?CommandEncoding {
    return commandEntryForLengthsAndDistance(insert_len, copy_len, false);
}

fn commandEntryForLengthsAndDistance(insert_len: usize, copy_len: usize, use_last_distance: bool) ?CommandEncoding {
    const insert_code = lengthCodeForValue(insert_len, true) orelse return null;
    const copy_code = lengthCodeForValue(copy_len, false) orelse return null;
    return commandEntryForCodes(insert_code, copy_code, use_last_distance);
}

fn commandEntryForCodes(insert_code: u5, copy_code: u5, use_last_distance: bool) ?CommandEncoding {
    const index = if (use_last_distance) &last_distance_command_symbol_index else &explicit_command_symbol_index;
    const symbol = index[insert_code][copy_code];
    if (symbol == std.math.maxInt(u16)) return null;
    return .{ .symbol = symbol, .command = command_lut.entries[symbol] };
}

const SameLastDistancePlan = struct {
    enabled: bool = false,
    use_implicit: [24][24]bool = @splat(@splat(false)),
};

const SameLastDistanceShape = struct { insert_code: u5, copy_code: u5 };

fn sameLastDistanceShape(command: command_plan.Command, last_distance: usize) ?SameLastDistanceShape {
    if (!command.has_copy or command.dictionary_output_len != 0 or command.distance != last_distance) return null;
    const insert_code = lengthCodeForValue(command.insert_len, true) orelse return null;
    const copy_code = lengthCodeForValue(command.copy_len, false) orelse return null;
    if (commandEntryForCodes(insert_code, copy_code, true) == null) return null;
    return .{ .insert_code = insert_code, .copy_code = copy_code };
}

fn preferImplicitLastDistance(implicit_command_bits: u4, explicit_command_bits: u4, distance_zero_bits: u4) bool {
    return implicit_command_bits < @as(u8, explicit_command_bits) + distance_zero_bits;
}

fn estimatedPrefixBitLength(total: u32, frequency: u32) u4 {
    if (frequency == 0 or total <= frequency) return 0;
    const ratio = (total + frequency - 1) / frequency;
    return @intCast(@min(@as(u32, 15), std.math.log2_int_ceil(u32, ratio)));
}

fn prefixTreePlanBitCost(
    comptime capacity: usize,
    allocator: std.mem.Allocator,
    alphabet_size: usize,
    frequencies: *const [capacity]u32,
    alphabet: *const command_plan.PrefixAlphabetFor(capacity),
    lengths: *const [capacity]u4,
) Error!u64 {
    var payload_bits: u64 = 0;
    for (frequencies, lengths) |frequency, length|
        payload_bits += @as(u64, frequency) * length;
    const tree_bits: u64 = if (alphabet.len <= 4)
        4 + @as(u64, alphabet.len) * alphabetBitsRuntime(alphabet_size) + @intFromBool(alphabet.len == 4)
    else blk: {
        var highest: usize = 0;
        for (alphabet.symbols[0..alphabet.len]) |symbol| highest = @max(highest, symbol);
        break :blk try complex_prefix.bitCost(allocator, alphabet_size, lengths, highest + 1);
    };
    return tree_bits + payload_bits;
}

/// Recode only copies that reuse the newest distance. The existing stream is
/// the exact baseline; observed frequencies cheaply select implicit-command
/// vs explicit-command-plus-distance-zero per insert/copy shape, then complete
/// command and distance tree costs decide whether the plan is retained.
fn chooseSameLastDistancePlan(
    allocator: std.mem.Allocator,
    command_frequencies: *[704]u32,
    sparse_command_alphabet: *const command_plan.PrefixAlphabet,
    distance_frequencies: *[planned_distance_alphabet_size]u32,
    shape_counts: *const [24][24]u32,
    replaced_distance_frequencies: *const [planned_distance_alphabet_size]u32,
    replaced_distance_extra_bits: u64,
    distance_alphabet_size: usize,
    final_command_alphabet: *command_plan.PrefixAlphabet,
    final_command_lengths: *[704]u4,
    final_distance_alphabet: *command_plan.PrefixAlphabetFor(planned_distance_alphabet_size),
    final_distance_lengths: *[planned_distance_alphabet_size]u4,
) Error!SameLastDistancePlan {
    var candidate_count: u32 = 0;
    for (shape_counts) |row| {
        for (row) |count| candidate_count += count;
    }
    if (candidate_count == 0) return .{};

    var baseline_command_frequencies: [704]u32 = @splat(0);
    for (sparse_command_alphabet.symbols[0..sparse_command_alphabet.len]) |symbol|
        baseline_command_frequencies[symbol] = command_frequencies[symbol];
    var baseline_command_alphabet: command_plan.PrefixAlphabet = undefined;
    try command_plan.alphabetFromFrequenciesInto(704, &baseline_command_alphabet, &baseline_command_frequencies);
    const baseline_command_lengths = try baseline_command_alphabet.codeLengths(&baseline_command_frequencies);
    var baseline_distance_alphabet: command_plan.PrefixAlphabetFor(planned_distance_alphabet_size) = undefined;
    try command_plan.alphabetFromFrequenciesInto(planned_distance_alphabet_size, &baseline_distance_alphabet, distance_frequencies);
    const baseline_distance_lengths = try baseline_distance_alphabet.codeLengths(distance_frequencies);
    const baseline_bits = try prefixTreePlanBitCost(704, allocator, 704, &baseline_command_frequencies, &baseline_command_alphabet, &baseline_command_lengths) +
        try prefixTreePlanBitCost(planned_distance_alphabet_size, allocator, distance_alphabet_size, distance_frequencies, &baseline_distance_alphabet, &baseline_distance_lengths) +
        replaced_distance_extra_bits;

    // Model both command forms as available while choosing per-shape costs.
    var model_command_count: u32 = candidate_count;
    for (baseline_command_frequencies) |count| model_command_count += count;
    var distance_count: u32 = 0;
    for (distance_frequencies) |count| distance_count += count;

    var plan: SameLastDistancePlan = .{};
    var candidate_command_frequencies = baseline_command_frequencies;
    var candidate_distance_frequencies = distance_frequencies.*;
    for (replaced_distance_frequencies, 0..) |count, symbol| {
        if (count > candidate_distance_frequencies[symbol]) return error.InvalidBlockPlan;
        candidate_distance_frequencies[symbol] -= count;
    }
    for (shape_counts, 0..) |row, insert_code| {
        for (row, 0..) |count, copy_code| {
            if (count == 0) continue;
            const insert_len = insertLengthSpec(@intCast(insert_code)).base;
            const copy_len = copyLengthSpec(@intCast(copy_code)).base;
            const implicit = commandEntryForLengthsAndDistance(insert_len, copy_len, true) orelse return error.InvalidBlockPlan;
            const explicit = commandEntryForLengthsAndDistance(insert_len, copy_len, false) orelse return error.InvalidBlockPlan;
            const use_implicit = preferImplicitLastDistance(
                estimatedPrefixBitLength(model_command_count, baseline_command_frequencies[implicit.symbol] + count),
                estimatedPrefixBitLength(model_command_count, baseline_command_frequencies[explicit.symbol]),
                estimatedPrefixBitLength(distance_count, candidate_count),
            );
            plan.use_implicit[insert_code][copy_code] = use_implicit;
            if (use_implicit) {
                if (count > candidate_command_frequencies[explicit.symbol]) return error.InvalidBlockPlan;
                candidate_command_frequencies[explicit.symbol] -= count;
                candidate_command_frequencies[implicit.symbol] += count;
            } else candidate_distance_frequencies[0] += count;
        }
    }
    if (allZeroFrequencies(planned_distance_alphabet_size, &candidate_distance_frequencies))
        candidate_distance_frequencies[0] = 1;

    var candidate_command_alphabet: command_plan.PrefixAlphabet = undefined;
    try command_plan.alphabetFromFrequenciesInto(704, &candidate_command_alphabet, &candidate_command_frequencies);
    const candidate_command_lengths = try candidate_command_alphabet.codeLengths(&candidate_command_frequencies);
    var candidate_distance_alphabet: command_plan.PrefixAlphabetFor(planned_distance_alphabet_size) = undefined;
    try command_plan.alphabetFromFrequenciesInto(planned_distance_alphabet_size, &candidate_distance_alphabet, &candidate_distance_frequencies);
    const candidate_distance_lengths = try candidate_distance_alphabet.codeLengths(&candidate_distance_frequencies);
    const candidate_bits = try prefixTreePlanBitCost(704, allocator, 704, &candidate_command_frequencies, &candidate_command_alphabet, &candidate_command_lengths) +
        try prefixTreePlanBitCost(planned_distance_alphabet_size, allocator, distance_alphabet_size, &candidate_distance_frequencies, &candidate_distance_alphabet, &candidate_distance_lengths);
    // Eight bits guarantee at least one output byte saved regardless of the
    // surrounding bit offset and final byte alignment.
    if (candidate_bits > baseline_bits or baseline_bits - candidate_bits < 8) {
        final_command_alphabet.* = baseline_command_alphabet;
        final_command_lengths.* = baseline_command_lengths;
        final_distance_alphabet.* = baseline_distance_alphabet;
        final_distance_lengths.* = baseline_distance_lengths;
        return .{};
    }
    command_frequencies.* = candidate_command_frequencies;
    distance_frequencies.* = candidate_distance_frequencies;
    final_command_alphabet.* = candidate_command_alphabet;
    final_command_lengths.* = candidate_command_lengths;
    final_distance_alphabet.* = candidate_distance_alphabet;
    final_distance_lengths.* = candidate_distance_lengths;
    plan.enabled = true;
    return plan;
}

fn lengthCodeForValue(value: usize, comptime insert: bool) ?u5 {
    if (comptime insert) return switch (value) {
        0...5 => @intCast(value),
        6...9 => @intCast(6 + ((value - 6) >> 1)),
        10...17 => @intCast(8 + ((value - 10) >> 2)),
        18...33 => @intCast(10 + ((value - 18) >> 3)),
        34...65 => @intCast(12 + ((value - 34) >> 4)),
        66...129 => @intCast(14 + ((value - 66) >> 5)),
        130...193 => 16,
        194...321 => 17,
        322...577 => 18,
        578...1089 => 19,
        1090...2113 => 20,
        2114...6209 => 21,
        6210...22593 => 22,
        22594...16_799_809 => 23,
        else => null,
    };
    return switch (value) {
        2...9 => @intCast(value - 2),
        10...13 => @intCast(8 + ((value - 10) >> 1)),
        14...21 => @intCast(10 + ((value - 14) >> 2)),
        22...37 => @intCast(12 + ((value - 22) >> 3)),
        38...69 => @intCast(14 + ((value - 38) >> 4)),
        70...101 => 16,
        102...133 => 17,
        134...197 => 18,
        198...325 => 19,
        326...581 => 20,
        582...1093 => 21,
        1094...2117 => 22,
        2118...16_779_333 => 23,
        else => null,
    };
}

fn writeCommandLengthExtras(allocator: std.mem.Allocator, writer: *BitWriter, command: CommandEncoding, insert_len: usize, copy_len: usize) Error!void {
    if (command.command.insert_extra_bits != 0)
        try writer.writeBits(allocator, insert_len - command.command.insert_base, command.command.insert_extra_bits);
    if (command.command.copy_extra_bits != 0)
        try writer.writeBits(allocator, copy_len - command.command.copy_base, command.command.copy_extra_bits);
}

fn encodeCommandPlanAlloc(allocator: std.mem.Allocator, input: []const u8, commands: []const command_plan.Command, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats) Error![]u8 {
    return encodeCommandPlanWithOptionsAlloc(allocator, input, commands, io, stats, .{});
}

const PreferredCommandPlan = struct {
    encoded: []u8,
    use_recent_distances: bool,
};

/// Try Brotli's recent-distance symbols as a complete stream alternative. Tree
/// changes can occasionally outweigh saved distance bits, so ratio mode keeps
/// the candidate only when the final byte length is smaller.
fn encodePreferredCommandPlanAlloc(allocator: std.mem.Allocator, input: []const u8, commands: []const command_plan.Command, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats, options: LazyWireOptions) Error!PreferredCommandPlan {
    // A second full wire encode is worthwhile on ratio-sized plans with many
    // reusable distances, but would dominate latency for small inputs.
    const use_context = options.try_recent_distances and countReusableRecentDistances(commands) >= min_recent_distance_candidate_count;
    const primary_options = CommandPlanEncodeOptions{
        .use_recent_distances = use_context,
        .use_utf8_text_contexts = use_context,
        .window_bits = options.window_bits,
        .metadata = options.metadata,
    };
    if (!use_context) return .{
        .encoded = try encodeCommandPlanWithOptionsAlloc(allocator, input, commands, io, stats, primary_options),
        .use_recent_distances = false,
    };
    const context_candidate = try encodeCommandPlanWithOptionsAlloc(allocator, input, commands, io, stats, primary_options);
    // A result below this conservative ratio already wins by far more than the
    // few-byte regressions observed when switching command/literal alphabets.
    // Avoid materializing the explicit baseline in that common ratio-mode case.
    if (byteRatioAtMost(context_candidate.len, input.len, 80)) return .{
        .encoded = context_candidate,
        .use_recent_distances = true,
    };
    errdefer allocator.free(context_candidate);
    const baseline = try encodeCommandPlanWithOptionsAlloc(allocator, input, commands, io, stats, .{ .window_bits = options.window_bits, .metadata = options.metadata });
    errdefer allocator.free(baseline);
    if (context_candidate.len < baseline.len) {
        allocator.free(baseline);
        return .{ .encoded = context_candidate, .use_recent_distances = true };
    }
    allocator.free(context_candidate);
    return .{ .encoded = baseline, .use_recent_distances = false };
}

/// Evaluate literal, command, and distance entropy splits once, after the bounded
/// short-match alternatives have selected their exact-wire winner. This avoids
/// rescanning transient command plans. A conservative incremental estimate
/// chooses the two- or three-command-type proposal before one full-wire trial
/// and strict size arbitration against the chosen unsplit stream.
fn encodeEntropySplitCandidateAlloc(allocator: std.mem.Allocator, input: []const u8, commands: []const command_plan.Command, stats: *encoder_stats.PlannedEncodeStats, options: LazyWireOptions, baseline: PreferredCommandPlan) Error!?[]u8 {
    const literal_split = if (options.try_literal_split)
        literal_block_split.choose(input, commands, if (baseline.use_recent_distances) 56 else null)
    else
        null;
    const symbol_splits = try chooseCommandAndDistanceSplitsAlloc(allocator, commands, baseline.use_recent_distances, options.try_command_split, options.try_distance_split);
    const distance_split = symbol_splits.distance;
    const command_split = symbol_splits.command.three orelse symbol_splits.command.two;
    if (literal_split == null and command_split == null and distance_split == null) return null;
    const baseline_stats = stats.*;
    errdefer stats.* = baseline_stats;
    var candidate_stats = baseline_stats;
    const candidate = try encodeEntropySplitWireCandidateAlloc(allocator, input, commands, &candidate_stats, options, baseline.use_recent_distances, literal_split, command_split, distance_split);
    var best = candidate;
    var best_stats = candidate_stats;
    errdefer allocator.free(best);
    if (symbol_splits.command.clustered) |clustered| {
        var clustered_stats = baseline_stats;
        const clustered_candidate = try encodeEntropySplitWireCandidateAlloc(allocator, input, commands, &clustered_stats, options, baseline.use_recent_distances, literal_split, clustered, distance_split);
        if (clustered_candidate.len < best.len) {
            allocator.free(best);
            best = clustered_candidate;
            best_stats = clustered_stats;
        } else allocator.free(clustered_candidate);
    }
    if (symbol_splits.command.alternating_four) |alternating| {
        var alternating_stats = baseline_stats;
        const alternating_candidate = try encodeEntropySplitWireCandidateAlloc(allocator, input, commands, &alternating_stats, options, baseline.use_recent_distances, literal_split, alternating, distance_split);
        if (alternating_candidate.len < best.len) {
            allocator.free(best);
            best = alternating_candidate;
            best_stats = alternating_stats;
        } else allocator.free(alternating_candidate);
    }
    if (symbol_splits.command.reuse_first_four) |reused| {
        var reused_stats = baseline_stats;
        const reused_candidate = try encodeEntropySplitWireCandidateAlloc(allocator, input, commands, &reused_stats, options, baseline.use_recent_distances, literal_split, reused, distance_split);
        if (reused_candidate.len < best.len) {
            allocator.free(best);
            best = reused_candidate;
            best_stats = reused_stats;
        } else allocator.free(reused_candidate);
    }
    if (best.len < baseline.encoded.len) {
        stats.* = best_stats;
        return best;
    }
    allocator.free(best);
    return null;
}

fn encodeEntropySplitWireCandidateAlloc(allocator: std.mem.Allocator, input: []const u8, commands: []const command_plan.Command, stats: *encoder_stats.PlannedEncodeStats, options: LazyWireOptions, use_recent_distances: bool, literal_split: ?usize, command_split: ?command_block_split.Result, distance_split: ?distance_block_split.Result) Error![]u8 {
    return encodeCommandPlanWithOptionsAlloc(allocator, input, commands, null, stats, .{
        // The ordinary-vs-UTF8 decision is made first. A literal block split
        // then inherits that winner's distance coding instead of accidentally
        // enabling recent-distance symbols when the context candidate lost.
        .use_recent_distances = use_recent_distances,
        .use_utf8_text_contexts = use_recent_distances and literal_split == null,
        .literal_split = literal_split,
        .command_split = command_split,
        .distance_split = if (distance_split) |result| result.split else null,
        .window_bits = options.window_bits,
        .metadata = options.metadata,
    });
}

const EntropySymbolSplits = struct {
    command: command_block_split.Proposals = .{},
    distance: ?distance_block_split.Result = null,
};

/// Command and distance splitting consume the same derived command encoding
/// and recent-distance state. Collect both in one pass so ratio mode does not
/// allocate and parse the complete command stream twice.
fn chooseCommandAndDistanceSplitsAlloc(allocator: std.mem.Allocator, commands: []const command_plan.Command, use_recent_distances: bool, try_command_split: bool, try_distance_split: bool) Error!EntropySymbolSplits {
    var command_accumulator = if (try_command_split) command_block_split.Accumulator.init(commands.len) else null;
    // There cannot be more explicit distance symbols than commands, so short
    // plans cannot qualify. Keep candidate discovery bounded on large plans.
    const collect_distances = try_distance_split and distance_block_split.eligible(commands.len);
    if (command_accumulator == null and !collect_distances) return .{};
    const distance_symbols = if (collect_distances) try allocator.alloc(u16, commands.len) else null;
    defer if (distance_symbols) |symbols| allocator.free(symbols);
    var distance_symbol_count: usize = 0;
    var last_distances = initial_last_distances;
    for (commands) |command| {
        const recent_symbol = if (use_recent_distances and command.has_copy and command.dictionary_output_len == 0) recentDistanceSymbol(command.distance, &last_distances) else null;
        const encoding = commandEntryForLengthsAndDistance(command.insert_len, command.copy_len, recent_symbol == 0) orelse
            commandEntryForLengths(command.insert_len, command.copy_len) orelse return error.InvalidBlockPlan;
        if (command_accumulator) |*accumulator| if (!accumulator.add(encoding.symbol)) return error.InvalidBlockPlan;
        if (collect_distances and command.has_copy and encoding.command.distance_code == -1) {
            const distance = if (recent_symbol) |symbol| encoder_distance.Encoding{ .symbol = symbol } else encoder_distance.encode(commandWireDistance(command), 15) orelse return error.InvalidBlockPlan;
            distance_symbols.?[distance_symbol_count] = distance.symbol;
            distance_symbol_count += 1;
        }
        if (command.has_copy and command.dictionary_output_len == 0 and recent_symbol != 0) pushLastDistance(&last_distances, command.distance);
    }
    return .{
        .command = if (command_accumulator) |*accumulator| accumulator.finishProposals() else .{},
        .distance = if (distance_symbols) |symbols| distance_block_split.choose(symbols[0..distance_symbol_count]) else null,
    };
}

fn countReusableRecentDistances(commands: []const command_plan.Command) usize {
    var last_distances = initial_last_distances;
    var count: usize = 0;
    for (commands) |command| {
        if (!command.has_copy or command.dictionary_output_len != 0) continue;
        const symbol = recentDistanceSymbol(command.distance, &last_distances);
        if (symbol != null) count += 1;
        // Code zero reuses the newest distance without changing ring order;
        // every other short or regular distance becomes the new front.
        if (symbol != 0) pushLastDistance(&last_distances, command.distance);
    }
    return count;
}

const CommandShapeStats = struct {
    recent: usize = 0,
    last: usize = 0,
    explicit: usize = 0,
    insert_codes: [24]usize = @splat(0),
    copy_codes: [24]usize = @splat(0),
    recent_symbols: [16]usize = @splat(0),
    top_distances: [8]usize = @splat(0),
    top_distance_counts: [8]usize = @splat(0),
};
const RecentDistanceStats = struct { recent: usize = 0, last: usize = 0 };

fn commandShapeStats(allocator: std.mem.Allocator, commands: []const command_plan.Command) Error!CommandShapeStats {
    var last_distances = initial_last_distances;
    var stats: CommandShapeStats = .{};
    for (commands) |command| {
        const insert_code = lengthCodeForValue(command.insert_len, true) orelse continue;
        const copy_code = lengthCodeForValue(command.copy_len, false) orelse continue;
        stats.insert_codes[insert_code] += 1;
        stats.copy_codes[copy_code] += 1;
        if (!command.has_copy or command.dictionary_output_len != 0) continue;
        const symbol = recentDistanceSymbol(command.distance, &last_distances);
        if (symbol) |recent| {
            stats.recent += 1;
            stats.last += @intFromBool(recent == 0);
            stats.recent_symbols[recent] += 1;
        } else stats.explicit += 1;
        if (symbol != 0) pushLastDistance(&last_distances, command.distance);
    }
    const distance_counts = try allocator.alloc(u16, lz77.max_window_len + 1);
    defer allocator.free(distance_counts);
    @memset(distance_counts, 0);
    for (commands) |command| {
        if (!command.has_copy or command.dictionary_output_len != 0) continue;
        if (command.distance > lz77.max_window_len) return error.InvalidBlockPlan;
        distance_counts[command.distance] += 1;
    }
    for (distance_counts, 0..) |count, distance| {
        if (count == 0) continue;
        var slot: usize = 0;
        while (slot < stats.top_distance_counts.len and count <= stats.top_distance_counts[slot]) : (slot += 1) {}
        if (slot == stats.top_distance_counts.len) continue;
        var move = stats.top_distance_counts.len - 1;
        while (move > slot) : (move -= 1) {
            stats.top_distance_counts[move] = stats.top_distance_counts[move - 1];
            stats.top_distances[move] = stats.top_distances[move - 1];
        }
        stats.top_distance_counts[slot] = count;
        stats.top_distances[slot] = distance;
    }
    return stats;
}

fn recentDistanceStats(commands: []const command_plan.Command) RecentDistanceStats {
    var last_distances = initial_last_distances;
    var stats: RecentDistanceStats = .{};
    for (commands) |command| {
        if (!command.has_copy or command.dictionary_output_len != 0) continue;
        const symbol = recentDistanceSymbol(command.distance, &last_distances);
        if (symbol) |recent| {
            stats.recent += 1;
            stats.last += @intFromBool(recent == 0);
        }
        if (symbol != 0) pushLastDistance(&last_distances, command.distance);
    }
    return stats;
}

fn recentDistanceSymbol(distance: usize, last_distances: *const [4]usize) ?u4 {
    const deltas = [_]i8{ -1, 1, -2, 2, -3, 3 };
    if (distance == last_distances[3]) return 0;
    if (distance == last_distances[2]) return 1;
    if (distance == last_distances[1]) return 2;
    if (distance == last_distances[0]) return 3;
    for (deltas, 4..) |delta, symbol| {
        if (distanceWithDelta(last_distances[3], delta) catch null == distance) return @intCast(symbol);
    }
    for (deltas, 10..) |delta, symbol| {
        if (distanceWithDelta(last_distances[2], delta) catch null == distance) return @intCast(symbol);
    }
    return null;
}

fn encodeCommandPlanWithOptionsAlloc(allocator: std.mem.Allocator, input: []const u8, commands: []const command_plan.Command, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats, options: CommandPlanEncodeOptions) Error![]u8 {
    var out = try std.ArrayList(u8).initCapacity(allocator, commandPlanInitialCapacity(input.len));
    errdefer out.deinit(allocator);
    try encodeCommandPlanWithOptionsAppend(allocator, &out, input, commands, io, stats, options);
    return out.toOwnedSlice(allocator);
}

fn encodeCommandPlanWithOptionsInto(allocator: std.mem.Allocator, output: []u8, input: []const u8, commands: []const command_plan.Command, stats: *encoder_stats.PlannedEncodeStats, options: CommandPlanEncodeOptions) Error!usize {
    var out: std.ArrayList(u8) = .{ .items = output[0..0], .capacity = output.len };
    var writer = BitWriter{ .out = &out, .bounded = true };
    try encodeCommandPlanWithOptionsWrite(allocator, &writer, input, commands, null, stats, options);
    return out.items.len;
}

fn encodeCommandPlanWithOptionsAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), input: []const u8, commands: []const command_plan.Command, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats, options: CommandPlanEncodeOptions) Error!void {
    var writer = BitWriter{ .out = out };
    try encodeCommandPlanWithOptionsWrite(allocator, &writer, input, commands, io, stats, options);
}

fn initPlannedLiteralEncoder(lengths: *const [256]u4, alphabet: *const command_plan.PrefixAlphabetFor(256)) Error!huffman.HuffmanTable(256).Encoder {
    if (alphabet.len <= 1) return .{};
    if (alphabet.len <= 64) return huffman.HuffmanTable(256).Encoder.initSparseTrusted(lengths, alphabet.symbols[0..alphabet.len]);
    return huffman.HuffmanTable(256).Encoder.init(lengths);
}

fn encodeCommandPlanWithOptionsWrite(allocator: std.mem.Allocator, writer: *BitWriter, input: []const u8, commands: []const command_plan.Command, io: ?std.Io, stats: *encoder_stats.PlannedEncodeStats, options: CommandPlanEncodeOptions) Error!void {
    if (commands.len == 0) return error.InvalidBlockPlan;
    if (options.literal_split != null and options.use_utf8_text_contexts) return error.InvalidBlockPlan;
    // This writer currently fixes NPOSTFIX=0, whose four-bit NDIRECT field
    // directly represents values 0...15.
    if (options.ndirect > 15) return error.InvalidBlockPlan;
    if (options.command_split) |split| {
        if (split.split == 0 or commands.len <= split.split) return error.InvalidBlockPlan;
        if (split.second_split) |second| {
            if (second <= split.split or commands.len <= second) return error.InvalidBlockPlan;
            if (split.third_split) |third| {
                if (split.alternate_two_types == split.reuse_first_for_fourth or third <= second or commands.len <= third) return error.InvalidBlockPlan;
            }
        } else if (split.third_split != null or split.alternate_two_types or split.reuse_first_for_fourth) return error.InvalidBlockPlan;
    }
    var literal_frequencies: [256]u32 = if (options.optimize_literal_tree_wire) @splat(0) else undefined;
    var literal_seen: [4]u64 = @splat(0);
    var literal_alphabet: command_plan.PrefixAlphabetFor(256) = undefined;
    literal_alphabet.len = 0;
    var literal_context_frequencies: [2][256]u32 = undefined;
    // Fast and balanced encoding use one literal tree. Avoid clearing two
    // additional dense histograms unless a ratio candidate requests context
    // trees; the ordinary ratio path benefits too when it keeps one tree.
    if (options.use_utf8_text_contexts) @memset(&literal_context_frequencies, @splat(0));
    var literal_block_frequencies: [2][256]u32 = undefined;
    if (options.literal_split != null) @memset(&literal_block_frequencies, @splat(0));
    var command_frequencies: [704]u32 = undefined;
    var command_alphabet: command_plan.PrefixAlphabet = undefined;
    command_alphabet.len = 0;
    var command_block_frequencies: [3][704]u32 = undefined;
    if (options.command_split != null) @memset(&command_block_frequencies, @splat(0));
    var distance_frequencies: [planned_distance_alphabet_size]u32 = @splat(0);
    var distance_block_frequencies: [2][planned_distance_alphabet_size]u32 = undefined;
    if (options.distance_split != null) @memset(&distance_block_frequencies, @splat(0));
    const optimize_same_last_distance = options.optimize_same_last_distance and !options.use_recent_distances and options.command_split == null and options.distance_split == null;
    var same_last_shape_counts: [24][24]u32 = @splat(@splat(0));
    var same_last_distance_frequencies: [planned_distance_alphabet_size]u32 = @splat(0);
    var same_last_distance_extra_bits: u64 = 0;
    var has_same_last_candidate = false;
    var prepared_command_lengths: [704]u4 = undefined;
    var prepared_distance_alphabet: command_plan.PrefixAlphabetFor(planned_distance_alphabet_size) = undefined;
    var prepared_distance_lengths: [planned_distance_alphabet_size]u4 = undefined;
    // Frequency collection already resolves every command symbol. Retain the
    // common small-plan result so payload emission does not repeat both length
    // classifications and the 24x24 command-table lookup. Large plans keep the
    // prior recomputation path rather than scaling stack usage with input size.
    var command_symbols: [planned_command_symbol_cache_capacity]u16 = undefined;
    const cache_command_symbols = commands.len <= command_symbols.len;
    const frequency_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    var last_distances = initial_last_distances;
    var literal_index: usize = 0;
    var distance_index: usize = 0;
    for (commands, 0..) |command, command_index| {
        const recent_symbol = if (options.use_recent_distances and command.has_copy and command.dictionary_output_len == 0) recentDistanceSymbol(command.distance, &last_distances) else null;
        const use_last_distance = recent_symbol == 0;
        const encoding = commandEntryForLengthsAndDistance(command.insert_len, command.copy_len, use_last_distance) orelse
            commandEntryForLengths(command.insert_len, command.copy_len) orelse return error.InvalidBlockPlan;
        const same_last_shape = if (optimize_same_last_distance) sameLastDistanceShape(command, last_distances[3]) else null;
        if (same_last_shape) |shape| {
            has_same_last_candidate = true;
            same_last_shape_counts[shape.insert_code][shape.copy_code] += 1;
        }
        if (cache_command_symbols) command_symbols[command_index] = encoding.symbol;
        if (options.command_split) |split| {
            command_block_frequencies[split.blockIndex(command_index)][encoding.symbol] += 1;
        } else try command_alphabet.recordFrequency(&command_frequencies, encoding.symbol);
        for (input[command.insert_start..][0..command.insert_len], command.insert_start..) |literal, position| {
            if (options.literal_split) |split| {
                literal_block_frequencies[@intFromBool(literal_index >= split)][literal] += 1;
                literal_index += 1;
            } else {
                try literal_alphabet.recordByteFrequency(&literal_frequencies, &literal_seen, literal);
                if (options.use_utf8_text_contexts) {
                    const previous = if (position == 0) 0 else input[position - 1];
                    const second_previous = if (position < 2) 0 else input[position - 2];
                    const context = literal_context.value(literal_context.mode_utf8, previous, second_previous);
                    literal_context_frequencies[literal_context.utf8SuffixTree(context, options.utf8_context_cutoff)][literal] += 1;
                }
            }
        }
        if (!command.has_copy) continue;
        if (encoding.command.distance_code == -1) {
            const distance = if (recent_symbol) |symbol| encoder_distance.Encoding{ .symbol = symbol } else encoder_distance.encode(commandWireDistance(command), options.ndirect) orelse return error.InvalidBlockPlan;
            if (distance.symbol >= planned_distance_alphabet_size) return error.InvalidBlockPlan;
            if (same_last_shape != null) {
                same_last_distance_frequencies[distance.symbol] += 1;
                same_last_distance_extra_bits += distance.extra_bits;
            }
            if (options.distance_split) |split| {
                distance_block_frequencies[@intFromBool(distance_index >= split)][distance.symbol] += 1;
                distance_index += 1;
            } else distance_frequencies[distance.symbol] += 1;
        }
        if (command.dictionary_output_len == 0 and recent_symbol != 0) pushLastDistance(&last_distances, command.distance);
    }
    // Brotli still carries a literal tree when dictionary commands cover the
    // entire meta-block. A deterministic unused symbol keeps that tree legal
    // without adding payload bits.
    if (options.literal_split == null and literal_alphabet.len == 0)
        try literal_alphabet.recordByteFrequency(&literal_frequencies, &literal_seen, 0);
    if (options.literal_split) |split| if (split == 0 or literal_index <= split) return error.InvalidBlockPlan;
    const same_last_distance_plan = if (has_same_last_candidate)
        try chooseSameLastDistancePlan(
            allocator,
            &command_frequencies,
            &command_alphabet,
            &distance_frequencies,
            &same_last_shape_counts,
            &same_last_distance_frequencies,
            same_last_distance_extra_bits,
            16 + @as(usize, options.ndirect) + 48,
            &command_alphabet,
            &prepared_command_lengths,
            &prepared_distance_alphabet,
            &prepared_distance_lengths,
        )
    else
        SameLastDistancePlan{};
    if (options.distance_split) |split| {
        if (split == 0 or distance_index <= split) return error.InvalidBlockPlan;
    } else if (allZeroFrequencies(planned_distance_alphabet_size, &distance_frequencies)) distance_frequencies[0] = 1;
    if (io) |active| stats.frequency_ns = elapsedNs(frequency_start.?, active);
    const alphabet_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    var literal_context_alphabets: [2]command_plan.PrefixAlphabetFor(256) = undefined;
    var literal_block_alphabets: [2]command_plan.PrefixAlphabetFor(256) = undefined;
    var command_block_alphabets: [3]command_plan.PrefixAlphabet = undefined;
    var distance_block_alphabets: [2]command_plan.PrefixAlphabetFor(planned_distance_alphabet_size) = undefined;
    var distance_alphabet: command_plan.PrefixAlphabetFor(planned_distance_alphabet_size) = if (has_same_last_candidate) prepared_distance_alphabet else undefined;
    if (options.literal_split == null) try literal_alphabet.sortByFrequencies(&literal_frequencies);
    if (options.use_utf8_text_contexts) for (&literal_context_alphabets, &literal_context_frequencies) |*alphabet, *frequencies| {
        if (allZeroFrequencies(256, frequencies)) frequencies[0] = 1;
        try command_plan.alphabetFromFrequenciesInto(256, alphabet, frequencies);
    };
    if (options.literal_split != null) for (&literal_block_alphabets, &literal_block_frequencies) |*alphabet, *frequencies|
        try command_plan.alphabetFromFrequenciesInto(256, alphabet, frequencies);
    if (options.command_split != null) {
        for (command_block_alphabets[0..options.command_split.?.typeCount()], command_block_frequencies[0..options.command_split.?.typeCount()]) |*alphabet, *frequencies|
            try command_plan.alphabetFromFrequenciesInto(704, alphabet, frequencies);
    } else if (!has_same_last_candidate)
        try command_alphabet.sortByFrequencies(&command_frequencies);
    if (options.distance_split != null) {
        for (&distance_block_alphabets, &distance_block_frequencies) |*alphabet, *frequencies|
            try command_plan.alphabetFromFrequenciesInto(planned_distance_alphabet_size, alphabet, frequencies);
    } else if (!has_same_last_candidate)
        try command_plan.alphabetFromFrequenciesInto(planned_distance_alphabet_size, &distance_alphabet, &distance_frequencies);
    stats.literal_symbol_count = if (options.literal_split != null)
        literal_block_alphabets[0].len + literal_block_alphabets[1].len
    else
        literal_alphabet.len;
    stats.command_symbol_count = if (options.command_split != null) blk: {
        var symbol_count: usize = 0;
        for (command_block_alphabets[0..options.command_split.?.typeCount()]) |alphabet| symbol_count += alphabet.len;
        break :blk symbol_count;
    } else command_alphabet.len;
    stats.distance_symbol_count = if (options.distance_split != null)
        distance_block_alphabets[0].len + distance_block_alphabets[1].len
    else
        distance_alphabet.len;
    if (io) |active| stats.alphabet_ns = elapsedNs(alphabet_start.?, active);

    // Useful planner streams are usually a small fraction of input. Reserving
    // a capped fraction removes ArrayList's early growth ladder without scaling
    // scratch memory with multi-megabyte inputs.
    if (!writer.bounded) try writer.out.ensureUnusedCapacity(allocator, commandPlanInitialCapacity(input.len));
    if (options.write_stream_prefix) {
        try writeWindowBits(allocator, writer, options.window_bits);
        if (options.metadata.len != 0) try writeMetadataMetaBlock(allocator, writer, options.metadata);
    } else if (options.metadata.len != 0) return error.InvalidBlockPlan;
    try writeCompressedMetaBlockHeader(allocator, writer, input.len, options.final_meta_block);
    const distance_alphabet_size = 16 + @as(usize, options.ndirect) + 48;
    const lengths_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    const literal_lengths = if (options.literal_split == null)
        try chooseLiteralTreeLengths(allocator, &literal_frequencies, &literal_alphabet, options.optimize_literal_tree_wire)
    else
        undefined;
    const literal_context_lengths = if (options.use_utf8_text_contexts) blk: {
        var lengths: [2][256]u4 = undefined;
        for (&lengths, &literal_context_alphabets, &literal_context_frequencies) |*tree_lengths, *alphabet, *frequencies| tree_lengths.* = try alphabet.codeLengths(frequencies);
        break :blk lengths;
    } else undefined;
    const literal_block_lengths = if (options.literal_split != null) blk: {
        var lengths: [2][256]u4 = undefined;
        for (&lengths, &literal_block_alphabets, &literal_block_frequencies) |*tree_lengths, *alphabet, *frequencies|
            tree_lengths.* = try alphabet.codeLengths(frequencies);
        break :blk lengths;
    } else undefined;
    const command_lengths = if (options.command_split == null)
        if (has_same_last_candidate)
            prepared_command_lengths
        else if (command_alphabet.len <= 4)
            @as([704]u4, @splat(0))
        else
            try command_alphabet.codeLengths(&command_frequencies)
    else
        undefined;
    const command_block_lengths = if (options.command_split != null) blk: {
        var lengths: [3][704]u4 = undefined;
        for (lengths[0..options.command_split.?.typeCount()], command_block_alphabets[0..options.command_split.?.typeCount()], command_block_frequencies[0..options.command_split.?.typeCount()]) |*tree_lengths, *alphabet, *frequencies|
            tree_lengths.* = if (alphabet.len <= 4) @splat(0) else try alphabet.codeLengths(frequencies);
        break :blk lengths;
    } else undefined;
    const distance_lengths = if (options.distance_split == null)
        if (has_same_last_candidate)
            prepared_distance_lengths
        else if (distance_alphabet.len <= 4)
            @as([planned_distance_alphabet_size]u4, @splat(0))
        else
            try distance_alphabet.codeLengths(&distance_frequencies)
    else
        undefined;
    const distance_block_lengths = if (options.distance_split != null) blk: {
        var lengths: [2][planned_distance_alphabet_size]u4 = undefined;
        for (&lengths, &distance_block_alphabets, &distance_block_frequencies) |*tree_lengths, *alphabet, *frequencies|
            tree_lengths.* = if (alphabet.len <= 4) @splat(0) else try alphabet.codeLengths(frequencies);
        break :blk lengths;
    } else undefined;
    if (io) |active| stats.lengths_ns = elapsedNs(lengths_start.?, active);
    const header_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    const literal_split_code = if (options.literal_split) |split| try TwoBlockLengthCode.init(split, literal_index - split) else undefined;
    const command_split_code = if (options.command_split) |split| try CommandBlockLengthCode.init(split, commands.len) else undefined;
    const command_split_header: ?CommandBlockSplitHeader = if (options.command_split) |split| .{
        .block_count = split.typeCount(),
        .alphabets = &command_block_alphabets,
        .lengths = &command_block_lengths,
        .split_code = &command_split_code,
    } else null;
    const distance_split_code = if (options.distance_split) |split| try TwoBlockLengthCode.init(split, distance_index - split) else undefined;
    const distance_split_header: ?DistanceBlockSplitHeader = if (options.distance_split != null) .{
        .alphabets = &distance_block_alphabets,
        .lengths = &distance_block_lengths,
        .split_code = &distance_split_code,
    } else null;
    if (options.literal_split != null) {
        try writePlannedCompressedHeaderTwoLiteralBlocks(allocator, writer, &literal_block_alphabets, &literal_block_lengths, &literal_split_code, options.ndirect, &command_alphabet, command_split_header, &distance_alphabet, distance_split_header, distance_alphabet_size, &command_lengths, &distance_lengths);
    } else if (options.use_utf8_text_contexts) {
        try writePlannedCompressedHeaderTwoLiteralContexts(allocator, writer, &literal_context_alphabets, &literal_context_lengths, options.utf8_context_cutoff, options.ndirect, &command_alphabet, command_split_header, &distance_alphabet, distance_split_header, distance_alphabet_size, &command_lengths, &distance_lengths);
    } else try writePlannedCompressedHeader(allocator, writer, &literal_alphabet, &command_alphabet, command_split_header, &distance_alphabet, distance_split_header, options.ndirect, distance_alphabet_size, &literal_lengths, &command_lengths, &distance_lengths);
    if (io) |active| stats.header_ns = elapsedNs(header_start.?, active);

    const encoder_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    const literal_encoder = if (options.literal_split == null) try initPlannedLiteralEncoder(&literal_lengths, &literal_alphabet) else undefined;
    const literal_context_encoders = if (options.use_utf8_text_contexts) [2]huffman.HuffmanTable(256).Encoder{
        try initPlannedLiteralEncoder(&literal_context_lengths[0], &literal_context_alphabets[0]),
        try initPlannedLiteralEncoder(&literal_context_lengths[1], &literal_context_alphabets[1]),
    } else undefined;
    const literal_block_encoders = if (options.literal_split != null) [2]huffman.HuffmanTable(256).Encoder{
        try initPlannedLiteralEncoder(&literal_block_lengths[0], &literal_block_alphabets[0]),
        try initPlannedLiteralEncoder(&literal_block_lengths[1], &literal_block_alphabets[1]),
    } else undefined;
    const command_encoder = if (options.command_split != null or command_alphabet.len <= 4)
        huffman.HuffmanTable(704).Encoder{}
    else if (command_alphabet.len <= 64)
        try huffman.HuffmanTable(704).Encoder.initSparseTrusted(&command_lengths, command_alphabet.symbols[0..command_alphabet.len])
    else
        try huffman.HuffmanTable(704).Encoder.init(&command_lengths);
    const command_block_encoders = if (options.command_split != null) blk: {
        var encoders: [3]huffman.HuffmanTable(704).Encoder = undefined;
        for (encoders[0..options.command_split.?.typeCount()], command_block_alphabets[0..options.command_split.?.typeCount()], command_block_lengths[0..options.command_split.?.typeCount()]) |*encoder, *alphabet, *lengths|
            encoder.* = if (alphabet.len <= 4) .{} else if (alphabet.len <= 64)
                try huffman.HuffmanTable(704).Encoder.initSparseTrusted(lengths, alphabet.symbols[0..alphabet.len])
            else
                try huffman.HuffmanTable(704).Encoder.init(lengths);
        break :blk encoders;
    } else undefined;
    const distance_encoder = if (options.distance_split != null or distance_alphabet.len <= 4)
        huffman.HuffmanTable(planned_distance_alphabet_size).Encoder{}
    else if (distance_alphabet.len <= 64)
        try huffman.HuffmanTable(planned_distance_alphabet_size).Encoder.initSparseTrusted(&distance_lengths, distance_alphabet.symbols[0..distance_alphabet.len])
    else
        try huffman.HuffmanTable(planned_distance_alphabet_size).Encoder.init(&distance_lengths);
    const distance_block_encoders = if (options.distance_split != null) [2]huffman.HuffmanTable(planned_distance_alphabet_size).Encoder{
        if (distance_block_alphabets[0].len <= 4) .{} else if (distance_block_alphabets[0].len <= 64)
            try huffman.HuffmanTable(planned_distance_alphabet_size).Encoder.initSparseTrusted(&distance_block_lengths[0], distance_block_alphabets[0].symbols[0..distance_block_alphabets[0].len])
        else
            try huffman.HuffmanTable(planned_distance_alphabet_size).Encoder.init(&distance_block_lengths[0]),
        if (distance_block_alphabets[1].len <= 4) .{} else if (distance_block_alphabets[1].len <= 64)
            try huffman.HuffmanTable(planned_distance_alphabet_size).Encoder.initSparseTrusted(&distance_block_lengths[1], distance_block_alphabets[1].symbols[0..distance_block_alphabets[1].len])
        else
            try huffman.HuffmanTable(planned_distance_alphabet_size).Encoder.init(&distance_block_lengths[1]),
    } else undefined;
    if (io) |active| stats.encoder_ns = elapsedNs(encoder_start.?, active);
    const payload_start = if (io) |active| std.Io.Clock.awake.now(active) else null;
    last_distances = initial_last_distances;
    literal_index = 0;
    distance_index = 0;
    for (commands, 0..) |command, command_index| {
        const optimized_shape = if (same_last_distance_plan.enabled) sameLastDistanceShape(command, last_distances[3]) else null;
        const recent_symbol = if (optimized_shape != null)
            @as(?u4, 0)
        else if (options.use_recent_distances and command.has_copy and command.dictionary_output_len == 0)
            recentDistanceSymbol(command.distance, &last_distances)
        else
            null;
        const use_last_distance = if (optimized_shape) |shape|
            same_last_distance_plan.use_implicit[shape.insert_code][shape.copy_code]
        else
            recent_symbol == 0;
        const encoding = if (cache_command_symbols and !same_last_distance_plan.enabled) blk: {
            const symbol = command_symbols[command_index];
            break :blk CommandEncoding{ .symbol = symbol, .command = command_lut.entries[symbol] };
        } else if (optimized_shape) |shape| commandEntryForCodes(shape.insert_code, shape.copy_code, use_last_distance) orelse unreachable else commandEntryForLengthsAndDistance(command.insert_len, command.copy_len, use_last_distance) orelse
            commandEntryForLengths(command.insert_len, command.copy_len) orelse unreachable;
        const active_command_alphabet = if (options.command_split) |split| &command_block_alphabets[split.blockIndex(command_index)] else &command_alphabet;
        const active_command_encoder = if (options.command_split) |split| &command_block_encoders[split.blockIndex(command_index)] else &command_encoder;
        if (options.command_split) |split| {
            if (command_index == split.split) try command_split_code.writeLength(allocator, writer, 1);
            if (split.second_split) |second| if (command_index == second) {
                try command_split_code.writeLength(allocator, writer, 2);
            };
            if (split.third_split) |third| if (command_index == third) {
                try command_split_code.writeLength(allocator, writer, 3);
            };
        }
        if (active_command_alphabet.len > 1) {
            if (active_command_alphabet.len <= 4) {
                const code = active_command_alphabet.simpleCode(encoding.symbol).?;
                try writer.writeHuffmanBits(allocator, code.code, code.bits);
            } else try writer.writeHuffmanBits(allocator, active_command_encoder.codes[encoding.symbol], active_command_encoder.bits[encoding.symbol]);
        }
        try writeCommandLengthExtras(allocator, writer, encoding, command.insert_len, command.copy_len);
        for (input[command.insert_start..][0..command.insert_len], command.insert_start..) |literal, position| {
            if (options.literal_split) |split| {
                if (literal_index == split) try literal_split_code.writeLength(allocator, writer, 1);
                const block_index = @intFromBool(literal_index >= split);
                const encoder = &literal_block_encoders[block_index];
                if (encoder.bits[literal] != 0) try writer.writeHuffmanBits(allocator, encoder.codes[literal], encoder.bits[literal]);
                literal_index += 1;
            } else if (options.use_utf8_text_contexts) {
                const previous = if (position == 0) 0 else input[position - 1];
                const second_previous = if (position < 2) 0 else input[position - 2];
                const context = literal_context.value(literal_context.mode_utf8, previous, second_previous);
                const encoder = &literal_context_encoders[literal_context.utf8SuffixTree(context, options.utf8_context_cutoff)];
                if (encoder.bits[literal] != 0) try writer.writeHuffmanBits(allocator, encoder.codes[literal], encoder.bits[literal]);
            } else if (literal_alphabet.len > 1) try writer.writeHuffmanBits(allocator, literal_encoder.codes[literal], literal_encoder.bits[literal]);
        }
        if (command.has_copy and encoding.command.distance_code == -1) {
            const distance = if (recent_symbol) |symbol| encoder_distance.Encoding{ .symbol = symbol } else encoder_distance.encode(commandWireDistance(command), options.ndirect) orelse unreachable;
            const active_distance_alphabet = if (options.distance_split) |split| &distance_block_alphabets[@intFromBool(distance_index >= split)] else &distance_alphabet;
            const active_distance_encoder = if (options.distance_split) |split| &distance_block_encoders[@intFromBool(distance_index >= split)] else &distance_encoder;
            if (options.distance_split) |split| if (distance_index == split) try distance_split_code.writeLength(allocator, writer, 1);
            if (active_distance_alphabet.len > 1) {
                if (active_distance_alphabet.len <= 4) {
                    const code = active_distance_alphabet.simpleCode(distance.symbol).?;
                    try writer.writeHuffmanBits(allocator, code.code, code.bits);
                } else try writer.writeHuffmanBits(allocator, active_distance_encoder.codes[distance.symbol], active_distance_encoder.bits[distance.symbol]);
            }
            if (distance.extra_bits != 0)
                try writer.writeBits(allocator, distance.extra, distance.extra_bits);
            distance_index += 1;
        }
        if (command.has_copy and command.dictionary_output_len == 0 and recent_symbol != 0) pushLastDistance(&last_distances, command.distance);
    }
    if (io) |active| stats.payload_ns = elapsedNs(payload_start.?, active);
    if (options.final_meta_block and writer.bit_index != 0) writer.alignToByte();
}

fn commandPlanInitialCapacity(input_len: usize) usize {
    return @min(@max(input_len / 8, 64), 4096);
}

fn byteRatioAtMost(numerator: usize, denominator: usize, percent: usize) bool {
    const scaled_numerator = std.math.mul(usize, numerator, 100) catch return false;
    const scaled_denominator = std.math.mul(usize, denominator, percent) catch return false;
    return scaled_numerator <= scaled_denominator;
}

fn allZeroFrequencies(comptime len: usize, frequencies: *const [len]u32) bool {
    for (frequencies) |frequency| if (frequency != 0) return false;
    return true;
}

fn literalTreeWireBitCost(allocator: std.mem.Allocator, frequencies: *const [256]u32, alphabet: *const command_plan.PrefixAlphabetFor(256), lengths: *const [256]u4) Error!u64 {
    var payload: u64 = 0;
    for (frequencies, lengths) |frequency, length| payload += @as(u64, frequency) * length;
    var highest: usize = 0;
    for (alphabet.symbols[0..alphabet.len]) |symbol| highest = @max(highest, symbol);
    return payload + try complex_prefix.bitCost(allocator, 256, lengths, highest + 1);
}

fn chooseLiteralTreeLengths(allocator: std.mem.Allocator, frequencies: *const [256]u32, alphabet: *command_plan.PrefixAlphabetFor(256), optimize_wire: bool) Error![256]u4 {
    const baseline_lengths = try alphabet.codeLengths(frequencies);
    if (!optimize_wire or alphabet.len <= 4) return baseline_lengths;
    var candidate_frequencies = frequencies.*;
    huffman_rle_counts.optimize(&candidate_frequencies);
    var candidate_alphabet: command_plan.PrefixAlphabetFor(256) = undefined;
    try command_plan.alphabetFromFrequenciesInto(256, &candidate_alphabet, &candidate_frequencies);
    const candidate_lengths = try candidate_alphabet.codeLengths(&candidate_frequencies);
    const baseline_cost = try literalTreeWireBitCost(allocator, frequencies, alphabet, &baseline_lengths);
    const candidate_cost = try literalTreeWireBitCost(allocator, frequencies, &candidate_alphabet, &candidate_lengths);
    if (candidate_cost >= baseline_cost) return baseline_lengths;
    alphabet.* = candidate_alphabet;
    return candidate_lengths;
}

fn commandWireDistance(command: command_plan.Command) usize {
    if (command.dictionary_output_len == 0) return command.distance;
    // A dictionary copy is legal only when its distance exceeds the bytes
    // already produced. This one-meta-block planner is capped below the 16-bit
    // Brotli window, so the current output position is the active backward
    // limit used by both Vort and conforming external decoders.
    return command.insert_start + command.insert_len + 1 + command.dictionary_address;
}

fn encodeRleStreamWrite(allocator: std.mem.Allocator, writer: *BitWriter, input: []const u8) Error!void {
    if (input.len < 5 or input.len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    for (input[1..]) |byte| if (byte != input[0]) return error.InvalidBlockPlan;
    try writeWindowBits(allocator, writer, default_window_bits);
    try writeLastCompressedMetaBlockHeader(allocator, writer, input.len);
    try writeMinimalCompressedHeaderForRun(allocator, writer, input[0], input.len);
}

/// Emit the shared header used by the narrow one-meta-block compressed
/// encoders. Choosing the shortest legal length field keeps small streams
/// compact while still covering Brotli's full 24-bit meta-block limit.
fn writeLastCompressedMetaBlockHeader(allocator: std.mem.Allocator, writer: *BitWriter, len: usize) Error!void {
    try writeCompressedMetaBlockHeader(allocator, writer, len, true);
}

fn writeCompressedMetaBlockHeader(allocator: std.mem.Allocator, writer: *BitWriter, len: usize, final: bool) Error!void {
    if (len == 0 or len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    try writer.writeBits(allocator, @intFromBool(final), 1);
    if (final) try writer.writeBits(allocator, 0, 1);
    const len_minus_one = len - 1;
    const mnibbles: usize = if (len_minus_one <= 0xffff) 4 else if (len_minus_one <= 0xfffff) 5 else 6;
    try writer.writeBits(allocator, @intCast(mnibbles - 4), 2);
    try writer.writeBits(allocator, len_minus_one, @intCast(mnibbles * 4));
    if (!final) try writer.writeBits(allocator, 0, 1); // ISUNCOMPRESSED = false.
}

fn writeMinimalCompressedHeaderForRun(allocator: std.mem.Allocator, writer: *BitWriter, byte: u8, run_len: usize) Error!void {
    const copy_len = run_len - 1;
    const command = commandEntryForLengths(1, copy_len) orelse return error.InvalidBlockPlan;
    try writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 1);
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 1, 4); // NDIRECT = 1
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 1);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 256, byte);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, command.symbol);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 65, 16);
    if (command.command.copy_extra_bits != 0)
        try writer.writeBits(allocator, copy_len - command.command.copy_base, command.command.copy_extra_bits);
    // RFC Brotli streams may end mid-byte, but the trailing unused bits must be
    // zero. Materialize the final partial byte for external decoders.
    if (writer.bit_index != 0) writer.alignToByte();
}

pub fn encodeStoredStreamInto(input: []const u8, output: []u8) Error!usize {
    return try encodeStoredStreamWithOptionsInto(input, output, .{});
}

pub fn encodeStoredStreamWithOptionsInto(input: []const u8, output: []u8, options: StoredStreamOptions) Error!usize {
    const needed = try encodedStoredStreamBoundWithOptions(input.len, options);
    if (output.len < needed) return error.OutOfMemory;
    if (options.window_bits == default_window_bits and options.metadata.len == 0 and input.len <= direct_stored_stream_max_input_len)
        return encodeDefaultStoredStreamInto(input, output[0..needed]);
    var out: std.ArrayList(u8) = .{
        .items = output[0..0],
        .capacity = output.len,
    };
    var writer = BitWriter{ .out = &out, .bounded = true };
    try encodeStoredStreamWithOptionsWrite(std.heap.smp_allocator, &writer, input, options);
    if (out.items.len != needed) return error.SizeMismatch;
    return out.items.len;
}

/// Emit the common WBITS=16, metadata-free stored stream directly. The exact
/// bound has already been checked by the caller. Its single uncompressed block
/// is byte-aligned, so the fixed three-byte header, payload, and final marker
/// can all be written directly.
fn encodeDefaultStoredStreamInto(input: []const u8, output: []u8) usize {
    if (input.len == 0) {
        output[0] = 0b110; // WBITS=16, ISLAST, ISLASTEMPTY.
        return 1;
    }

    // This path is intentionally capped below 64 KiB by its caller, so the
    // shortest four-nibble MLEN form is always sufficient. With WBITS=16 its
    // fields occupy exactly three bytes before byte-aligned payload data.
    std.debug.assert(input.len <= direct_stored_stream_max_input_len);
    std.debug.assert(output.len == input.len + 4);
    const written = writeDefaultStoredBlockInto(input, output, true);
    output[written] = 0b11; // ISLAST + ISLASTEMPTY.
    return written + 1;
}

pub fn encodeStoredStreamChunksInto(chunks: []const []const u8, output: []u8) Error!usize {
    return try encodeStoredStreamChunksWithOptionsInto(chunks, output, .{});
}

pub fn encodeStoredStreamChunksWithOptionsInto(chunks: []const []const u8, output: []u8, options: StoredStreamOptions) Error!usize {
    const needed = try encodedStoredStreamChunksBoundWithOptions(chunks, options);
    if (output.len < needed) return error.OutOfMemory;
    if (options.window_bits == default_window_bits and options.metadata.len == 0 and storedChunksInputLenAtMost(chunks, direct_stored_stream_max_input_len))
        return encodeDefaultStoredStreamChunksInto(chunks, output[0..needed]);
    var out: std.ArrayList(u8) = .{
        .items = output[0..0],
        .capacity = output.len,
    };
    var writer = BitWriter{ .out = &out, .bounded = true };
    try encodeStoredStreamChunksWithOptionsWrite(std.heap.smp_allocator, &writer, chunks, options);
    if (out.items.len != needed) return error.SizeMismatch;
    return out.items.len;
}

fn storedChunksInputLenAtMost(chunks: []const []const u8, limit: usize) bool {
    var total: usize = 0;
    for (chunks) |chunk| {
        if (chunk.len > limit - total) return false;
        total += chunk.len;
    }
    return true;
}

fn encodeDefaultStoredStreamChunksInto(chunks: []const []const u8, output: []u8) usize {
    var output_offset: usize = 0;
    var first_block = true;
    for (chunks) |chunk| {
        if (chunk.len == 0) continue;
        std.debug.assert(chunk.len <= direct_stored_stream_max_input_len);
        output_offset += writeDefaultStoredBlockInto(chunk, output[output_offset..], first_block);
        first_block = false;
    }
    if (first_block) {
        output[0] = 0b110;
        return 1;
    }
    output[output_offset] = 0b11;
    return output_offset + 1;
}

fn writeDefaultStoredBlockInto(block: []const u8, output: []u8, first_block: bool) usize {
    std.debug.assert(block.len != 0 and block.len <= direct_stored_stream_max_input_len);
    std.debug.assert(output.len >= block.len + 3);
    const start_bit: u5 = if (first_block) 1 else 0;
    const header = (@as(u24, @intCast(block.len - 1)) << @intCast(start_bit + 3)) |
        (@as(u24, 1) << @intCast(start_bit + 19));
    output[0] = @truncate(header);
    output[1] = @truncate(header >> 8);
    output[2] = @truncate(header >> 16);
    @memcpy(output[3..][0..block.len], block);
    return block.len + 3;
}

fn encodeStoredStreamWithOptionsWrite(allocator: std.mem.Allocator, writer: *BitWriter, input: []const u8, options: StoredStreamOptions) Error!void {
    try writeWindowBits(allocator, writer, options.window_bits);
    if (options.metadata.len != 0) try writeMetadataMetaBlock(allocator, writer, options.metadata);

    var offset: usize = 0;
    while (offset < input.len) {
        const block_len = @min(input.len - offset, max_uncompressed_meta_block_len);
        try writeUncompressedMetaBlock(allocator, writer, input[offset..][0..block_len]);
        offset += block_len;
    }

    // End with an empty final meta-block. Brotli forbids marking an
    // uncompressed meta-block as the last one, so even non-empty stored streams
    // need this explicit terminator.
    try writer.writeBits(allocator, 1, 1); // ISLAST
    try writer.writeBits(allocator, 1, 1); // ISLASTEMPTY
}

fn encodeStoredStreamChunksWithOptionsWrite(allocator: std.mem.Allocator, writer: *BitWriter, chunks: []const []const u8, options: StoredStreamOptions) Error!void {
    try writeWindowBits(allocator, writer, options.window_bits);
    if (options.metadata.len != 0) try writeMetadataMetaBlock(allocator, writer, options.metadata);

    var chunk_index: usize = 0;
    var chunk_offset: usize = 0;
    while (chunk_index < chunks.len) {
        while (chunk_index < chunks.len and chunk_offset == chunks[chunk_index].len) {
            chunk_index += 1;
            chunk_offset = 0;
        }
        if (chunk_index >= chunks.len) break;
        const chunk = chunks[chunk_index];
        const block_len = @min(chunk.len - chunk_offset, max_uncompressed_meta_block_len);
        try writeUncompressedMetaBlock(allocator, writer, chunk[chunk_offset..][0..block_len]);
        chunk_offset += block_len;
    }

    try writer.writeBits(allocator, 1, 1); // ISLAST
    try writer.writeBits(allocator, 1, 1); // ISLASTEMPTY
}

fn writeUncompressedMetaBlock(allocator: std.mem.Allocator, writer: *BitWriter, block: []const u8) Error!void {
    if (block.len == 0 or block.len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    const len_minus_one = block.len - 1;
    const mnibbles: usize = if (len_minus_one <= 0xffff)
        4
    else if (len_minus_one <= 0xfffff)
        5
    else
        6;
    const mnibbles_code: u2 = switch (mnibbles) {
        4 => 0b00,
        5 => 0b01,
        6 => 0b10,
        else => unreachable,
    };

    try writer.writeBits(allocator, 0, 1); // ISLAST = false.
    try writer.writeBits(allocator, mnibbles_code, 2);
    try writer.writeBits(allocator, @intCast(len_minus_one), @intCast(mnibbles * 4));
    try writer.writeBits(allocator, 1, 1); // ISUNCOMPRESSED.
    writer.alignToByte();
    try writer.writeAlignedBytes(allocator, block);
}

fn addStoredUncompressedMetaBlockBitsLen(bit_count: usize, block_len: usize) Error!usize {
    if (block_len == 0 or block_len > max_uncompressed_meta_block_len) return error.InvalidBlockPlan;
    const len_minus_one = block_len - 1;
    const mnibbles: usize = if (len_minus_one <= 0xffff)
        4
    else if (len_minus_one <= 0xfffff)
        5
    else
        6;
    var bits = bit_count;
    bits = std.math.add(usize, bits, 1 + 2) catch return error.IntegerOverflow; // ISLAST + MNIBBLES.
    bits = std.math.add(usize, bits, mnibbles * 4) catch return error.IntegerOverflow;
    bits = std.math.add(usize, bits, 1) catch return error.IntegerOverflow; // ISUNCOMPRESSED.
    bits = alignBitCountToByte(bits);
    const payload_bits = std.math.mul(usize, block_len, 8) catch return error.IntegerOverflow;
    return std.math.add(usize, bits, payload_bits) catch return error.IntegerOverflow;
}

fn writeMetadataMetaBlock(allocator: std.mem.Allocator, writer: *BitWriter, metadata: []const u8) Error!void {
    if (metadata.len > 0x1_0000) return error.InvalidBlockPlan;
    try writer.writeBits(allocator, 0, 1); // ISLAST = false.
    try writer.writeBits(allocator, 0b11, 2); // MNIBBLES = 0.
    try writer.writeBits(allocator, 0, 1); // reserved.
    if (metadata.len == 0) {
        try writer.writeBits(allocator, 0, 2); // MSKIPBYTES = 0.
    } else {
        const len_minus_one = metadata.len - 1;
        const mskipbytes: usize = if (len_minus_one <= 0xff) 1 else 2;
        try writer.writeBits(allocator, @intCast(mskipbytes), 2);
        try writer.writeBits(allocator, @intCast(len_minus_one), @intCast(mskipbytes * 8));
    }
    writer.alignToByte();
    try writer.writeAlignedBytes(allocator, metadata);
}

fn addStoredMetadataMetaBlockBitsLen(bit_count: usize, metadata_len: usize) Error!usize {
    if (metadata_len > 0x1_0000) return error.InvalidBlockPlan;
    var bits = bit_count;
    bits = std.math.add(usize, bits, 1 + 2 + 1) catch return error.IntegerOverflow; // ISLAST + MNIBBLES + reserved.
    if (metadata_len == 0) {
        bits = std.math.add(usize, bits, 2) catch return error.IntegerOverflow;
    } else {
        const len_minus_one = metadata_len - 1;
        const mskipbytes: usize = if (len_minus_one <= 0xff) 1 else 2;
        bits = std.math.add(usize, bits, 2) catch return error.IntegerOverflow; // MSKIPBYTES.
        bits = std.math.add(usize, bits, mskipbytes * 8) catch return error.IntegerOverflow;
    }
    bits = alignBitCountToByte(bits);
    const payload_bits = std.math.mul(usize, metadata_len, 8) catch return error.IntegerOverflow;
    return std.math.add(usize, bits, payload_bits) catch return error.IntegerOverflow;
}

pub fn decodeStreamAlloc(allocator: std.mem.Allocator, stream: []const u8) Error![]u8 {
    return try decodeStreamAllocLimited(allocator, stream, std.math.maxInt(usize));
}

pub fn decodeStreamAllocLimited(allocator: std.mem.Allocator, stream: []const u8, max_output_len: usize) Error![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);

    var reader = bitstream.BitReader.init(stream);
    const window_bits = try readWindowBitsValue(&reader);
    var written: usize = 0;
    var last_distances = initial_last_distances;
    while (true) {
        switch (try readStreamMetaBlockHeader(&reader)) {
            .end => {
                try ensureZeroPaddingAndEnd(reader);
                std.debug.assert(written == out.items.len);
                return out.toOwnedSlice(allocator);
            },
            .metadata => try skipMetadataMetaBlock(&reader),
            .compressed => |header| {
                const meta_block_end = try checkedDecodedEnd(written, header.decoded_len, max_output_len);
                try out.resize(allocator, meta_block_end);
                if (stream.len >= large_stream_decode_threshold)
                    try processLargeCompressedMetaBlock(&reader, out.items, &written, header.decoded_len, &last_distances, window_bits)
                else
                    try processMinimalCompressedMetaBlock(&reader, out.items, &written, header.decoded_len, &last_distances, window_bits);
                if (written != meta_block_end) return error.SizeMismatch;
                if (header.final) {
                    try ensureZeroPaddingAndEnd(reader);
                    return out.toOwnedSlice(allocator);
                }
            },
            .uncompressed => |meta_block_len| {
                const meta_block_end = try checkedDecodedEnd(written, meta_block_len, max_output_len);
                try out.resize(allocator, meta_block_end);
                try consumeZeroPaddingToByte(&reader);
                try reader.readAlignedBytes(out.items[written..meta_block_end]);
                written = meta_block_end;
            },
        }
    }
}

pub fn decodeStreamAllocWithOptions(allocator: std.mem.Allocator, stream: []const u8, options: DecodeOptions) Error![]u8 {
    if (!options.allow_large_window) return decodeStreamAlloc(allocator, stream);
    return try decodeStreamAllocLimitedWithOptions(allocator, stream, std.math.maxInt(usize), options);
}

pub fn decodeStreamAllocLimitedWithOptions(allocator: std.mem.Allocator, stream: []const u8, max_output_len: usize, options: DecodeOptions) Error![]u8 {
    if (!options.allow_large_window) return decodeStreamAllocLimited(allocator, stream, max_output_len);
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);

    // Every non-metadata Brotli meta-block declares its exact decoded length
    // before the payload. Grow the owned result at that boundary and decode it
    // immediately, avoiding the former full summary pass plus second decode.
    // Append APIs deliberately retain preflight because they promise not to
    // change caller-owned output when validation fails.
    var reader = bitstream.BitReader.init(stream);
    const window = try readWindowInfo(&reader, options);
    var written: usize = 0;
    var last_distances = initial_last_distances;
    while (true) {
        switch (try readStreamMetaBlockHeader(&reader)) {
            .end => {
                try ensureZeroPaddingAndEnd(reader);
                std.debug.assert(written == out.items.len);
                return out.toOwnedSlice(allocator);
            },
            .metadata => try skipMetadataMetaBlock(&reader),
            .compressed => |header| {
                const meta_block_end = try checkedDecodedEnd(written, header.decoded_len, max_output_len);
                try out.resize(allocator, meta_block_end);
                if (stream.len >= large_stream_decode_threshold)
                    try processLargeCompressedMetaBlockWithOptions(&reader, out.items, &written, header.decoded_len, &last_distances, window)
                else
                    try processMinimalCompressedMetaBlockWithOptions(&reader, out.items, &written, header.decoded_len, &last_distances, window);
                if (written != meta_block_end) return error.SizeMismatch;
                if (header.final) {
                    try ensureZeroPaddingAndEnd(reader);
                    return out.toOwnedSlice(allocator);
                }
            },
            .uncompressed => |meta_block_len| {
                const meta_block_end = try checkedDecodedEnd(written, meta_block_len, max_output_len);
                try out.resize(allocator, meta_block_end);
                try consumeZeroPaddingToByte(&reader);
                try reader.readAlignedBytes(out.items[written..meta_block_end]);
                written = meta_block_end;
            },
        }
    }
}

pub fn decodeStreamAllocExactSize(allocator: std.mem.Allocator, stream: []const u8, expected_output_len: usize) Error![]u8 {
    const out = try allocator.alloc(u8, expected_output_len);
    errdefer allocator.free(out);
    const written = try decodeStreamIntoExactSize(stream, out, expected_output_len);
    if (written != expected_output_len) return error.SizeMismatch;
    return out;
}

pub fn decodeStreamAllocExactSizeWithOptions(allocator: std.mem.Allocator, stream: []const u8, expected_output_len: usize, options: DecodeOptions) Error![]u8 {
    if (!options.allow_large_window) return decodeStreamAllocExactSize(allocator, stream, expected_output_len);
    const out = try allocator.alloc(u8, expected_output_len);
    errdefer allocator.free(out);
    const written = try decodeStreamIntoExactSizeWithOptions(stream, out, expected_output_len, options);
    if (written != expected_output_len) return error.SizeMismatch;
    return out;
}

pub fn decodeStreamAppend(allocator: std.mem.Allocator, out: *std.ArrayList(u8), stream: []const u8) Error!usize {
    return try decodeStreamAppendLimited(allocator, out, stream, std.math.maxInt(usize));
}

pub fn decodeStreamAppendLimited(allocator: std.mem.Allocator, out: *std.ArrayList(u8), stream: []const u8, max_output_len: usize) Error!usize {
    const decoded_len = try decodedStreamSizeAllocLimited(allocator, stream, max_output_len);
    try out.ensureUnusedCapacity(allocator, decoded_len);
    const start = out.items.len;
    const slot = out.addManyAsSliceAssumeCapacity(decoded_len);
    const written = decodeStreamInto(stream, slot) catch |err| {
        out.items.len = start;
        return err;
    };
    if (written != decoded_len) {
        out.items.len = start;
        return error.SizeMismatch;
    }
    return written;
}

pub fn decodeStreamAppendWithOptions(allocator: std.mem.Allocator, out: *std.ArrayList(u8), stream: []const u8, options: DecodeOptions) Error!usize {
    if (!options.allow_large_window) return decodeStreamAppend(allocator, out, stream);
    return try decodeStreamAppendLimitedWithOptions(allocator, out, stream, std.math.maxInt(usize), options);
}

pub fn decodeStreamAppendLimitedWithOptions(allocator: std.mem.Allocator, out: *std.ArrayList(u8), stream: []const u8, max_output_len: usize, options: DecodeOptions) Error!usize {
    if (!options.allow_large_window) return decodeStreamAppendLimited(allocator, out, stream, max_output_len);
    const decoded_len = try decodedStreamSizeAllocLimitedWithOptions(allocator, stream, max_output_len, options);
    try out.ensureUnusedCapacity(allocator, decoded_len);
    const start = out.items.len;
    const slot = out.addManyAsSliceAssumeCapacity(decoded_len);
    const written = decodeStreamIntoWithOptions(stream, slot, options) catch |err| {
        out.items.len = start;
        return err;
    };
    if (written != decoded_len) {
        out.items.len = start;
        return error.SizeMismatch;
    }
    return written;
}

pub fn decodeStreamAppendExactSize(allocator: std.mem.Allocator, out: *std.ArrayList(u8), stream: []const u8, expected_output_len: usize) Error!usize {
    try out.ensureUnusedCapacity(allocator, expected_output_len);
    const start = out.items.len;
    const slot = out.addManyAsSliceAssumeCapacity(expected_output_len);
    const written = decodeStreamIntoExactSize(stream, slot, expected_output_len) catch |err| {
        out.items.len = start;
        return err;
    };
    if (written != expected_output_len) {
        out.items.len = start;
        return error.SizeMismatch;
    }
