    var diagnostics: StreamSummaryDiagnostics = .{};
    const summary = summarizeStreamLimitedWithOptionsAndDiagnostics(stream, std.math.maxInt(usize), options, &diagnostics) catch |err| {
        return .{
            .ok = false,
            .diagnostics = diagnostics,
            .error_name = @errorName(err),
        };
    };
    if (summary.decoded_bytes != expected_output_len) {
        return .{
            .ok = false,
            .summary = summary,
            .diagnostics = .{ .phase = .output_size },
            .error_name = @errorName(error.SizeMismatch),
        };
    }
    return .{
        .ok = true,
        .summary = summary,
        .diagnostics = diagnostics,
    };
}

