fn applySummaryMetaBlockStats(summary: *StreamSummary, stats: StreamSummaryMetaBlockStats) Error!void {
    if (stats.static_dictionary_copy_count != 0) {
        summary.uses_static_dictionary = true;
        summary.static_dictionary_copy_count = std.math.add(usize, summary.static_dictionary_copy_count, stats.static_dictionary_copy_count) catch return error.IntegerOverflow;
        summary.static_dictionary_bytes = std.math.add(usize, summary.static_dictionary_bytes, stats.static_dictionary_bytes) catch return error.IntegerOverflow;
    }
    summary.command_count = std.math.add(usize, summary.command_count, stats.command_count) catch return error.IntegerOverflow;
    summary.zero_insert_command_count = std.math.add(usize, summary.zero_insert_command_count, stats.zero_insert_command_count) catch return error.IntegerOverflow;
    summary.single_literal_insert_command_count = std.math.add(usize, summary.single_literal_insert_command_count, stats.single_literal_insert_command_count) catch return error.IntegerOverflow;
    summary.implicit_distance_command_count = std.math.add(usize, summary.implicit_distance_command_count, stats.implicit_distance_command_count) catch return error.IntegerOverflow;
    summary.implicit_distance_copy_count = std.math.add(usize, summary.implicit_distance_copy_count, stats.implicit_distance_copy_count) catch return error.IntegerOverflow;
    summary.short_distance_copy_count = std.math.add(usize, summary.short_distance_copy_count, stats.short_distance_copy_count) catch return error.IntegerOverflow;
    summary.direct_distance_copy_count = std.math.add(usize, summary.direct_distance_copy_count, stats.direct_distance_copy_count) catch return error.IntegerOverflow;
    summary.regular_distance_copy_count = std.math.add(usize, summary.regular_distance_copy_count, stats.regular_distance_copy_count) catch return error.IntegerOverflow;
    for (&summary.copy_length_log2_histogram, stats.copy_length_log2_histogram) |*total, count|
        total.* = std.math.add(usize, total.*, count) catch return error.IntegerOverflow;
    summary.lz77_copy_count = std.math.add(usize, summary.lz77_copy_count, stats.lz77_copy_count) catch return error.IntegerOverflow;
    summary.lz77_copy_bytes = std.math.add(usize, summary.lz77_copy_bytes, stats.lz77_copy_bytes) catch return error.IntegerOverflow;
    summary.max_lz77_distance = @max(summary.max_lz77_distance, stats.max_lz77_distance);
    summary.non_overlapping_lz77_copy_count = std.math.add(usize, summary.non_overlapping_lz77_copy_count, stats.non_overlapping_lz77_copy_count) catch return error.IntegerOverflow;
    summary.non_overlapping_lz77_copy_bytes = std.math.add(usize, summary.non_overlapping_lz77_copy_bytes, stats.non_overlapping_lz77_copy_bytes) catch return error.IntegerOverflow;
    summary.short_non_overlapping_lz77_copy_count = std.math.add(usize, summary.short_non_overlapping_lz77_copy_count, stats.short_non_overlapping_lz77_copy_count) catch return error.IntegerOverflow;
    summary.short_non_overlapping_lz77_copy_bytes = std.math.add(usize, summary.short_non_overlapping_lz77_copy_bytes, stats.short_non_overlapping_lz77_copy_bytes) catch return error.IntegerOverflow;
    for (&summary.literal_context_mode_bytes, stats.literal_context_mode_bytes) |*total, count|
        total.* = std.math.add(usize, total.*, count) catch return error.IntegerOverflow;
    summary.max_literal_block_types = @max(summary.max_literal_block_types, stats.max_literal_block_types);
    summary.max_literal_context_trees = @max(summary.max_literal_context_trees, stats.max_literal_context_trees);
    summary.max_command_block_types = @max(summary.max_command_block_types, stats.max_command_block_types);
    summary.max_distance_block_types = @max(summary.max_distance_block_types, stats.max_distance_block_types);
    summary.max_distance_context_trees = @max(summary.max_distance_context_trees, stats.max_distance_context_trees);
    summary.max_distance_postfix_bits = @max(summary.max_distance_postfix_bits, stats.max_distance_postfix_bits);
    summary.max_direct_distance_codes = @max(summary.max_direct_distance_codes, stats.max_direct_distance_codes);
}

test "br stream summary aggregates command and LZ77 copy shapes" {
    var summary = StreamSummary{
        .window_bits = 16,
        .input_bytes = 17,
        .command_count = 1,
        .zero_insert_command_count = 1,
        .implicit_distance_command_count = 1,
        .copy_length_log2_histogram = .{ 0, 1, 0, 0, 0, 0, 0, 0, 0 },
    };
    try applySummaryMetaBlockStats(&summary, .{
        .command_count = 9,
        .zero_insert_command_count = 6,
        .single_literal_insert_command_count = 2,
        .implicit_distance_command_count = 4,
        .implicit_distance_copy_count = 3,
        .short_distance_copy_count = 2,
        .direct_distance_copy_count = 1,
        .regular_distance_copy_count = 1,
        .copy_length_log2_histogram = .{ 0, 2, 3, 1, 0, 1, 1, 0, 1 },
        .lz77_copy_count = 7,
        .lz77_copy_bytes = 91,
        .max_lz77_distance = 4097,
        .non_overlapping_lz77_copy_count = 5,
        .non_overlapping_lz77_copy_bytes = 63,
        .short_non_overlapping_lz77_copy_count = 3,
        .short_non_overlapping_lz77_copy_bytes = 27,
        .literal_context_mode_bytes = .{ 4, 3, 2, 1 },
        .max_distance_postfix_bits = 2,
        .max_direct_distance_codes = 12,
    });
    try std.testing.expectEqual(@as(usize, 10), summary.command_count);
    try std.testing.expectEqual(@as(usize, 7), summary.zero_insert_command_count);
    try std.testing.expectEqual(@as(usize, 2), summary.single_literal_insert_command_count);
    try std.testing.expectEqual(@as(usize, 5), summary.implicit_distance_command_count);
    try std.testing.expectEqual(@as(usize, 3), summary.implicit_distance_copy_count);
    try std.testing.expectEqual(@as(usize, 2), summary.short_distance_copy_count);
    try std.testing.expectEqual(@as(usize, 1), summary.direct_distance_copy_count);
    try std.testing.expectEqual(@as(usize, 1), summary.regular_distance_copy_count);
    try std.testing.expectEqual([_]usize{ 0, 3, 3, 1, 0, 1, 1, 0, 1 }, summary.copy_length_log2_histogram);
    try std.testing.expectEqual(@as(usize, 7), summary.lz77_copy_count);
    try std.testing.expectEqual(@as(usize, 91), summary.lz77_copy_bytes);
    try std.testing.expectEqual(@as(usize, 4097), summary.max_lz77_distance);
    try std.testing.expectEqual(@as(usize, 5), summary.non_overlapping_lz77_copy_count);
    try std.testing.expectEqual(@as(usize, 63), summary.non_overlapping_lz77_copy_bytes);
    try std.testing.expectEqual(@as(usize, 3), summary.short_non_overlapping_lz77_copy_count);
    try std.testing.expectEqual(@as(usize, 27), summary.short_non_overlapping_lz77_copy_bytes);
    try std.testing.expectEqual([_]usize{ 4, 3, 2, 1 }, summary.literal_context_mode_bytes);
    try std.testing.expectEqual(@as(u2, 2), summary.max_distance_postfix_bits);
    try std.testing.expectEqual(@as(u16, 12), summary.max_direct_distance_codes);
}

test "br stream summary classifies distance coding paths" {
    var stats: StreamSummaryMetaBlockStats = .{};
    try recordSummaryDistanceCode(&stats, true, 0, 4);
    try recordSummaryDistanceCode(&stats, false, 0, 4);
    try recordSummaryDistanceCode(&stats, false, 15, 4);
    try recordSummaryDistanceCode(&stats, false, 16, 4);
    try recordSummaryDistanceCode(&stats, false, 19, 4);
    try recordSummaryDistanceCode(&stats, false, 20, 4);
    try std.testing.expectEqual(@as(usize, 1), stats.implicit_distance_copy_count);
    try std.testing.expectEqual(@as(usize, 2), stats.short_distance_copy_count);
    try std.testing.expectEqual(@as(usize, 2), stats.direct_distance_copy_count);
    try std.testing.expectEqual(@as(usize, 1), stats.regular_distance_copy_count);
}

fn recordSummaryCommand(stats: ?*StreamSummaryMetaBlockStats, lengths: InsertCopyLengths) SummaryError!void {
    const s = stats orelse return;
    if (lengths.copy_len == 0) return error.CorruptFrame;
    s.command_count = std.math.add(usize, s.command_count, 1) catch return error.IntegerOverflow;
    if (lengths.insert_len == 0)
        s.zero_insert_command_count = std.math.add(usize, s.zero_insert_command_count, 1) catch return error.IntegerOverflow;
    if (lengths.insert_len == 1)
        s.single_literal_insert_command_count = std.math.add(usize, s.single_literal_insert_command_count, 1) catch return error.IntegerOverflow;
    if (lengths.distance_symbol_zero)
        s.implicit_distance_command_count = std.math.add(usize, s.implicit_distance_command_count, 1) catch return error.IntegerOverflow;
    const copy_length_bucket = @min(
        s.copy_length_log2_histogram.len - 1,
        @as(usize, std.math.log2_int(usize, lengths.copy_len)),
    );
    s.copy_length_log2_histogram[copy_length_bucket] = std.math.add(usize, s.copy_length_log2_histogram[copy_length_bucket], 1) catch return error.IntegerOverflow;
}

pub const StoredStreamEncoder = struct {
    allocator: std.mem.Allocator,
    scratch: std.ArrayList(u8) = .empty,

    pub fn init(allocator: std.mem.Allocator) StoredStreamEncoder {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *StoredStreamEncoder) void {
        self.scratch.deinit(self.allocator);
        self.* = undefined;
    }

    pub fn encodeAlloc(self: *StoredStreamEncoder, input: []const u8) Error![]u8 {
        return try self.encodeWithOptionsAlloc(input, .{});
    }

    pub fn encodeWithOptionsAlloc(self: *StoredStreamEncoder, input: []const u8, options: StoredStreamOptions) Error![]u8 {
        return encodeStoredStreamWithOptionsAlloc(self.allocator, input, options);
    }

    pub fn encodeChunksAlloc(self: *StoredStreamEncoder, chunks: []const []const u8) Error![]u8 {
        return try self.encodeChunksWithOptionsAlloc(chunks, .{});
    }

    pub fn encodeChunksWithOptionsAlloc(self: *StoredStreamEncoder, chunks: []const []const u8, options: StoredStreamOptions) Error![]u8 {
        return encodeStoredStreamChunksWithOptionsAlloc(self.allocator, chunks, options);
    }

    pub fn encodeScratch(self: *StoredStreamEncoder, input: []const u8) Error![]const u8 {
        return try self.encodeScratchWithOptions(input, .{});
    }

    pub fn encodeScratchWithOptions(self: *StoredStreamEncoder, input: []const u8, options: StoredStreamOptions) Error![]const u8 {
        self.scratch.clearRetainingCapacity();
        const needed = try encodedStoredStreamBoundWithOptions(input.len, options);
        try self.scratch.ensureTotalCapacity(self.allocator, needed);
        const written = try encodeStoredStreamWithOptionsInto(input, self.scratch.allocatedSlice()[0..needed], options);
        self.scratch.items.len = written;
        return self.scratch.items;
    }

    pub fn encodeChunksScratch(self: *StoredStreamEncoder, chunks: []const []const u8) Error![]const u8 {
        return try self.encodeChunksScratchWithOptions(chunks, .{});
    }

    pub fn encodeChunksScratchWithOptions(self: *StoredStreamEncoder, chunks: []const []const u8, options: StoredStreamOptions) Error![]const u8 {
        self.scratch.clearRetainingCapacity();
        const needed = try encodedStoredStreamChunksBoundWithOptions(chunks, options);
        try self.scratch.ensureTotalCapacity(self.allocator, needed);
        const written = try encodeStoredStreamChunksWithOptionsInto(chunks, self.scratch.allocatedSlice()[0..needed], options);
        self.scratch.items.len = written;
        return self.scratch.items;
    }

    pub fn encodeAppend(self: *StoredStreamEncoder, out: *std.ArrayList(u8), input: []const u8) Error!void {
        try self.encodeWithOptionsAppend(out, input, .{});
    }

    pub fn encodeWithOptionsAppend(self: *StoredStreamEncoder, out: *std.ArrayList(u8), input: []const u8, options: StoredStreamOptions) Error!void {
        try encodeStoredStreamWithOptionsAppend(self.allocator, out, input, options);
    }

    pub fn encodeChunksAppend(self: *StoredStreamEncoder, out: *std.ArrayList(u8), chunks: []const []const u8) Error!void {
        try self.encodeChunksWithOptionsAppend(out, chunks, .{});
    }

    pub fn encodeChunksWithOptionsAppend(self: *StoredStreamEncoder, out: *std.ArrayList(u8), chunks: []const []const u8, options: StoredStreamOptions) Error!void {
        try encodeStoredStreamChunksWithOptionsAppend(self.allocator, out, chunks, options);
    }

    pub fn encodeIntoSlice(self: *StoredStreamEncoder, input: []const u8, output: []u8) Error!usize {
        _ = self;
        return try encodeStoredStreamInto(input, output);
    }

    pub fn encodeWithOptionsIntoSlice(self: *StoredStreamEncoder, input: []const u8, options: StoredStreamOptions, output: []u8) Error!usize {
        _ = self;
        return try encodeStoredStreamWithOptionsInto(input, output, options);
    }

    pub fn encodeChunksIntoSlice(self: *StoredStreamEncoder, chunks: []const []const u8, output: []u8) Error!usize {
        _ = self;
        return try encodeStoredStreamChunksInto(chunks, output);
    }

    pub fn encodeChunksWithOptionsIntoSlice(self: *StoredStreamEncoder, chunks: []const []const u8, options: StoredStreamOptions, output: []u8) Error!usize {
        _ = self;
        return try encodeStoredStreamChunksWithOptionsInto(chunks, output, options);
    }
};

/// Reusable, caller-owned Brotli stream decoder facade.
///
/// The current Brotli codec still validates and decodes a complete supported
/// stream into caller-provided scratch during `reset*`; `step` then drains that
/// decoded scratch through bounded output buffers. This mirrors the early
/// zlib/gzip decoder facade shape without adding hidden allocations, and keeps a
/// stable library API ready for a future byte-progressive Brotli state machine.
pub const StreamDecoder = struct {
    decoded: []const u8 = &.{},
    stream_len: usize = 0,
    offset: usize = 0,
    done: bool = false,
    last_error_name: []const u8 = "",
    last_recoverability_hint: RecoverabilityHint = .none,

    pub const RecoverabilityHint = enum {
        none,
        truncated_input,
        unsupported_feature,
        payload_corrupt,
    };

    pub const Snapshot = struct {
        output_written: usize,
        expected_output_len: usize,
        payload_remaining: usize,
        done: bool,
        last_error_name: []const u8,
        recoverability_hint: RecoverabilityHint,
    };

    pub fn init(stream: []const u8, output_scratch: []u8) Error!StreamDecoder {
        return initWithOptions(stream, output_scratch, .{});
    }

    pub fn initWithOptions(stream: []const u8, output_scratch: []u8, options: DecodeOptions) Error!StreamDecoder {
        var self = StreamDecoder{};
        try self.resetWithOptions(stream, output_scratch, options);
        return self;
    }

    pub fn initExactSize(stream: []const u8, output_scratch: []u8, expected_output_len: usize) Error!StreamDecoder {
        return initExactSizeWithOptions(stream, output_scratch, expected_output_len, .{});
    }

    pub fn initExactSizeWithOptions(stream: []const u8, output_scratch: []u8, expected_output_len: usize, options: DecodeOptions) Error!StreamDecoder {
        var self = StreamDecoder{};
        try self.resetExactSizeWithOptions(stream, output_scratch, expected_output_len, options);
        return self;
    }

    pub fn initLimited(stream: []const u8, output_scratch: []u8, max_output_len: usize) Error!StreamDecoder {
        return initLimitedWithOptions(stream, output_scratch, max_output_len, .{});
    }

    pub fn initLimitedWithOptions(stream: []const u8, output_scratch: []u8, max_output_len: usize, options: DecodeOptions) Error!StreamDecoder {
        var self = StreamDecoder{};
        try self.resetLimitedWithOptions(stream, output_scratch, max_output_len, options);
        return self;
    }

    pub fn initFromChunks(chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8) Error!StreamDecoder {
        return initFromChunksWithOptions(chunks, compressed_scratch, output_scratch, .{});
    }

    pub fn initFromChunksWithOptions(chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, options: DecodeOptions) Error!StreamDecoder {
        var self = StreamDecoder{};
        try self.resetFromChunksWithOptions(chunks, compressed_scratch, output_scratch, options);
        return self;
    }

    pub fn initFromChunksExactSize(chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, expected_output_len: usize) Error!StreamDecoder {
        return initFromChunksExactSizeWithOptions(chunks, compressed_scratch, output_scratch, expected_output_len, .{});
    }

    pub fn initFromChunksExactSizeWithOptions(chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, expected_output_len: usize, options: DecodeOptions) Error!StreamDecoder {
        var self = StreamDecoder{};
        try self.resetFromChunksExactSizeWithOptions(chunks, compressed_scratch, output_scratch, expected_output_len, options);
        return self;
    }

    pub fn initFromChunksLimited(chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, max_output_len: usize) Error!StreamDecoder {
        return initFromChunksLimitedWithOptions(chunks, compressed_scratch, output_scratch, max_output_len, .{});
    }

    pub fn initFromChunksLimitedWithOptions(chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, max_output_len: usize, options: DecodeOptions) Error!StreamDecoder {
        var self = StreamDecoder{};
        try self.resetFromChunksLimitedWithOptions(chunks, compressed_scratch, output_scratch, max_output_len, options);
        return self;
    }

    pub fn reset(self: *StreamDecoder, stream: []const u8, output_scratch: []u8) Error!void {
        return self.resetWithOptions(stream, output_scratch, .{});
    }

    pub fn resetWithOptions(self: *StreamDecoder, stream: []const u8, output_scratch: []u8, options: DecodeOptions) Error!void {
        return self.resetLimitedWithOptions(stream, output_scratch, std.math.maxInt(usize), options);
    }

    pub fn resetExactSize(self: *StreamDecoder, stream: []const u8, output_scratch: []u8, expected_output_len: usize) Error!void {
        return self.resetExactSizeWithOptions(stream, output_scratch, expected_output_len, .{});
    }

    pub fn resetExactSizeWithOptions(self: *StreamDecoder, stream: []const u8, output_scratch: []u8, expected_output_len: usize, options: DecodeOptions) Error!void {
        const decoded_len = decodedStreamSizeWithOptions(stream, options) catch |err| {
            self.recordError(err);
            return err;
        };
        if (decoded_len != expected_output_len) {
            self.recordError(error.SizeMismatch);
            return error.SizeMismatch;
        }
        if (output_scratch.len < expected_output_len) {
            self.recordError(error.OutputTooSmall);
            return error.OutputTooSmall;
        }
        const written = decodeStreamIntoExactSizeWithOptions(stream, output_scratch[0..expected_output_len], expected_output_len, options) catch |err| {
            self.recordError(err);
            return err;
        };
        self.installDecoded(stream.len, output_scratch, written);
    }

    pub fn resetLimited(self: *StreamDecoder, stream: []const u8, output_scratch: []u8, max_output_len: usize) Error!void {
        return self.resetLimitedWithOptions(stream, output_scratch, max_output_len, .{});
    }

    pub fn resetLimitedWithOptions(self: *StreamDecoder, stream: []const u8, output_scratch: []u8, max_output_len: usize, options: DecodeOptions) Error!void {
        const decoded_len = decodedStreamSizeLimitedWithOptions(stream, max_output_len, options) catch |err| {
            self.recordError(err);
            return err;
        };
        if (output_scratch.len < decoded_len) {
            self.recordError(error.OutputTooSmall);
            return error.OutputTooSmall;
        }
        const written = decodeStreamIntoWithOptions(stream, output_scratch[0..decoded_len], options) catch |err| {
            self.recordError(err);
            return err;
        };
        if (written != decoded_len) {
            self.recordError(error.SizeMismatch);
            return error.SizeMismatch;
        }
        self.installDecoded(stream.len, output_scratch, written);
    }

    pub fn resetFromChunks(self: *StreamDecoder, chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8) Error!void {
        return self.resetFromChunksWithOptions(chunks, compressed_scratch, output_scratch, .{});
    }

    pub fn resetFromChunksWithOptions(self: *StreamDecoder, chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, options: DecodeOptions) Error!void {
        const joined = joinChunks(chunks, compressed_scratch) catch |err| {
            self.recordError(err);
            return err;
        };
        return self.resetWithOptions(joined, output_scratch, options);
    }

    pub fn resetFromChunksExactSize(self: *StreamDecoder, chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, expected_output_len: usize) Error!void {
        return self.resetFromChunksExactSizeWithOptions(chunks, compressed_scratch, output_scratch, expected_output_len, .{});
    }

    pub fn resetFromChunksExactSizeWithOptions(self: *StreamDecoder, chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, expected_output_len: usize, options: DecodeOptions) Error!void {
        const joined = joinChunks(chunks, compressed_scratch) catch |err| {
            self.recordError(err);
            return err;
        };
        return self.resetExactSizeWithOptions(joined, output_scratch, expected_output_len, options);
    }

    pub fn resetFromChunksLimited(self: *StreamDecoder, chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, max_output_len: usize) Error!void {
        return self.resetFromChunksLimitedWithOptions(chunks, compressed_scratch, output_scratch, max_output_len, .{});
    }

    pub fn resetFromChunksLimitedWithOptions(self: *StreamDecoder, chunks: []const []const u8, compressed_scratch: []u8, output_scratch: []u8, max_output_len: usize, options: DecodeOptions) Error!void {
        const joined = joinChunks(chunks, compressed_scratch) catch |err| {
            self.recordError(err);
            return err;
        };
        return self.resetLimitedWithOptions(joined, output_scratch, max_output_len, options);
    }

    pub fn snapshot(self: *const StreamDecoder) Snapshot {
        return .{
            .output_written = self.offset,
            .expected_output_len = self.decoded.len,
            .payload_remaining = self.decoded.len - self.offset,
            .done = self.done,
            .last_error_name = self.last_error_name,
            .recoverability_hint = self.last_recoverability_hint,
        };
    }

    pub fn diagnostics(self: *const StreamDecoder) core.StreamingDiagnostics {
        const snap = self.snapshot();
        return .{
            .phase_name = if (snap.done) "done" else "payload",
            .frame_input_read = if (snap.done) self.stream_len else null,
            .output_written = snap.output_written,
            .expected_output_len = snap.expected_output_len,
            .payload_remaining = snap.payload_remaining,
            .last_error_name = snap.last_error_name,
            .last_error_phase_name = if (snap.last_error_name.len == 0) "" else "payload",
            .recoverability_hint_name = hintName(snap.recoverability_hint),
        };
    }

    pub fn step(self: *StreamDecoder, output: []u8) Error!core.StepResult {
        if (self.done) return .{ .status = .done };
        if (output.len == 0) return .{ .status = .need_output };
        const remaining = self.decoded[self.offset..];
        const n = @min(output.len, remaining.len);
        @memcpy(output[0..n], remaining[0..n]);
        self.offset += n;
        if (self.offset == self.decoded.len) self.done = true;
        return .{
            .progress = .{ .input_read = if (self.done) self.stream_len else 0, .output_written = n },
            .status = if (self.done) .done else .need_output,
        };
    }

    fn installDecoded(self: *StreamDecoder, stream_len: usize, output_scratch: []u8, written: usize) void {
        self.* = .{
            .decoded = output_scratch[0..written],
            .stream_len = stream_len,
        };
    }

    fn recordError(self: *StreamDecoder, err: Error) void {
        self.last_error_name = @errorName(err);
        self.last_recoverability_hint = switch (err) {
            error.TruncatedFrame => .truncated_input,
            error.UnsupportedBrotliFeature => .unsupported_feature,
            else => .payload_corrupt,
        };
    }

    fn hintName(hint: RecoverabilityHint) []const u8 {
        return switch (hint) {
            .none => "none",
            .truncated_input => "truncated_input",
            .unsupported_feature => "unsupported_feature",
            .payload_corrupt => "payload_corrupt",
        };
    }
};

fn joinChunks(chunks: []const []const u8, compressed_scratch: []u8) Error![]const u8 {
    var total: usize = 0;
    for (chunks) |chunk| total = std.math.add(usize, total, chunk.len) catch return error.IntegerOverflow;
    if (compressed_scratch.len < total) return error.OutputTooSmall;
    var offset: usize = 0;
    for (chunks) |chunk| {
        @memcpy(compressed_scratch[offset..][0..chunk.len], chunk);
        offset += chunk.len;
    }
    return compressed_scratch[0..total];
}

fn readWindowBits(reader: *bitstream.BitReader) Error!void {
    _ = try readWindowBitsValue(reader);
}

fn readBlockTypeCount(reader: *bitstream.BitReader) Error!u16 {
    const first = try reader.readBits(u1, 1);
    if (first == 0) return 1;

    const selector = try reader.readBits(u3, 3);
    if (selector == 0) return 2;

    const extra = try reader.readBits(u16, selector);
    return (@as(u16, 1) << selector) + 1 + extra;
}

fn readMinimalCompressedHeader(reader: *bitstream.BitReader) Error!MinimalCompressedHeader {
    var header: MinimalCompressedHeader = undefined;
    try readMinimalCompressedHeaderInto(reader, &header);
    return header;
}

fn readMinimalCompressedHeaderWithOptions(reader: *bitstream.BitReader, large_window: bool) Error!LargeWindowCompressedHeader {
    var header: LargeWindowCompressedHeader = undefined;
    try readMinimalCompressedHeaderIntoWithOptions(reader, &header, large_window);
    return header;
}

fn readMinimalCompressedHeaderInto(reader: *bitstream.BitReader, header: *MinimalCompressedHeader) Error!void {
    const shape = try readCompressedHeaderBlockSwitches(reader, header);
    const tree_counts = try readCompressedHeaderContextMaps(reader, header, shape);
    try readCompressedHeaderLiteralTrees(reader, header, tree_counts.literal);
    try readCompressedHeaderCommandTrees(reader, header, shape.command_block_types);
    try readCompressedHeaderDistanceTrees(reader, header, tree_counts.distance, shape.distance_alphabet_size);
    finishCompressedHeader(header, shape, tree_counts);
}

noinline fn readMinimalCompressedHeaderIntoWithOptions(reader: *bitstream.BitReader, header: *LargeWindowCompressedHeader, large_window: bool) linksection(large_window_text_section) Error!void {
    const shape = try readLargeCompressedHeaderBlockSwitches(reader, header, large_window);
    const tree_counts = try readLargeCompressedHeaderContextMaps(reader, header, shape);
    try readLargeCompressedHeaderLiteralTrees(reader, header, tree_counts.literal);
    try readLargeCompressedHeaderCommandTrees(reader, header, shape.command_block_types);
    try readLargeCompressedHeaderDistanceTrees(
        large_max_distance_alphabet_size,
        reader,
        header,
        tree_counts.distance,
        shape.distance_alphabet_size_max,
        shape.distance_alphabet_size,
    );
    finishLargeCompressedHeader(header, shape, tree_counts);
}

const CompressedHeaderShape = struct {
    literal_block_types: u16,
    command_block_types: u16,
    distance_block_types: u16,
    distance_alphabet_size: usize,
    npostfix: u2,
    ndirect: u16,
};

const CompressedHeaderTreeCounts = struct {
    literal: u16,
    distance: u16,
};

const PrefixCodeProfile = header_profile.PrefixCodeProfile;
const PrefixCodeFamily = header_profile.Family;

inline fn readCompressedHeaderBlockSwitches(reader: *bitstream.BitReader, header: *MinimalCompressedHeader) Error!CompressedHeaderShape {
    const nbltypes_l = try readBlockTypeCount(reader);
    if (nbltypes_l > max_literal_block_types) return error.UnsupportedBrotliFeature;
    header.literal_block = .{ .block_type_count = nbltypes_l };
    if (nbltypes_l >= 2) {
        header.literal_block.type_tree = try readPrefixCodeRuntime(max_literal_block_types + 2, @as(usize, nbltypes_l) + 2, reader);
        header.literal_block.length_tree = try readPrefixCode(26, reader);
        header.literal_block.remaining = try readBlockLength(&header.literal_block.length_tree, reader);
    }
    const nbltypes_i = try readBlockTypeCount(reader);
    if (nbltypes_i > max_command_block_types) return error.UnsupportedBrotliFeature;
    header.command_block = .{ .block_type_count = nbltypes_i };
    if (nbltypes_i >= 2) {
        header.command_block.type_tree = try readPrefixCodeRuntime(max_command_block_types + 2, @as(usize, nbltypes_i) + 2, reader);
        header.command_block.length_tree = try readPrefixCode(26, reader);
        header.command_block.remaining = try readBlockLength(&header.command_block.length_tree, reader);
    }
    const nbltypes_d = try readBlockTypeCount(reader);
    if (nbltypes_d > max_distance_block_types) return error.UnsupportedBrotliFeature;
    header.distance_block = .{ .block_type_count = nbltypes_d };
    if (nbltypes_d >= 2) {
        header.distance_block.type_tree = try readPrefixCodeRuntime(max_distance_block_types + 2, @as(usize, nbltypes_d) + 2, reader);
        header.distance_block.length_tree = try readPrefixCode(26, reader);
        header.distance_block.remaining = try readBlockLength(&header.distance_block.length_tree, reader);
    }
    const npostfix = try reader.readBits(u2, 2);
    const ndirect_high = try reader.readBits(u4, 4);
    const ndirect: u16 = @as(u16, ndirect_high) << npostfix;
    if (ndirect > 120) return error.CorruptFrame;
    const distance_alphabet_size: usize = 16 + @as(usize, ndirect) + (@as(usize, 48) << npostfix);
    for (0..nbltypes_l) |i| header.literal_context_modes[i] = try reader.readBits(u2, 2);
    return .{
        .literal_block_types = nbltypes_l,
        .command_block_types = nbltypes_i,
        .distance_block_types = nbltypes_d,
        .distance_alphabet_size = distance_alphabet_size,
        .npostfix = npostfix,
        .ndirect = ndirect,
    };
}

inline fn readCompressedHeaderContextMaps(reader: *bitstream.BitReader, header: *MinimalCompressedHeader, shape: CompressedHeaderShape) Error!CompressedHeaderTreeCounts {
    const ntrees_l = try readBlockTypeCount(reader);
    if (ntrees_l > max_literal_context_trees) return error.UnsupportedBrotliFeature;
    try readContextMap(reader, header.literal_context_map[0..(@as(usize, shape.literal_block_types) * 64)], ntrees_l);
    const ntrees_d = try readBlockTypeCount(reader);
    if (ntrees_d > max_distance_context_trees) return error.UnsupportedBrotliFeature;
    try readContextMap(reader, header.distance_context_map[0..(@as(usize, shape.distance_block_types) * 4)], ntrees_d);
    return .{ .literal = ntrees_l, .distance = ntrees_d };
}

inline fn readCompressedHeaderLiteralTrees(reader: *bitstream.BitReader, header: *MinimalCompressedHeader, tree_count: u16) Error!void {
    var literal_tree_index: u16 = 0;
    while (literal_tree_index < tree_count) : (literal_tree_index += 1) {
        if (literal_tree_index < inline_literal_tree_count) {
            try readPrefixCodeInto(256, reader, &header.literal_trees[literal_tree_index]);
        } else {
            const tree = try readPrefixCode(256, reader);
            header.packed_literal_trees[literal_tree_index - inline_literal_tree_count] = PackedPrefixCode(256).init(&tree);
        }
    }
    header.active_packed_literal_tree_index = std.math.maxInt(u16);
}

inline fn readCompressedHeaderCommandTrees(reader: *bitstream.BitReader, header: *MinimalCompressedHeader, tree_count: u16) Error!void {
    var command_tree_index: u16 = 0;
    while (command_tree_index < tree_count) : (command_tree_index += 1) {
        if (command_tree_index < inline_command_tree_count) {
            try readPrefixCodeInto(704, reader, &header.insert_copy_trees[command_tree_index]);
        } else {
            const tree = try readPrefixCode(704, reader);
            header.packed_insert_copy_trees[command_tree_index - inline_command_tree_count] = PackedPrefixCode(704).init(&tree);
        }
    }
    header.active_packed_insert_copy_tree_index = std.math.maxInt(u16);
}

inline fn readCompressedHeaderDistanceTrees(reader: *bitstream.BitReader, header: *MinimalCompressedHeader, tree_count: u16, alphabet_size: usize) Error!void {
    var distance_tree_index: u16 = 0;
    while (distance_tree_index < tree_count) : (distance_tree_index += 1) {
        if (distance_tree_index < inline_distance_tree_count) {
            try readPrefixCodeRuntimeInto(max_distance_alphabet_size, alphabet_size, reader, &header.distance_trees[distance_tree_index]);
        } else {
            const tree = try readPrefixCodeRuntime(max_distance_alphabet_size, alphabet_size, reader);
            header.packed_distance_trees[distance_tree_index - inline_distance_tree_count] = PackedPrefixCode(max_distance_alphabet_size).init(&tree);
        }
    }
    header.active_packed_distance_tree_index = std.math.maxInt(u16);
}

inline fn finishCompressedHeader(header: *MinimalCompressedHeader, shape: CompressedHeaderShape, tree_counts: CompressedHeaderTreeCounts) void {
    header.npostfix = shape.npostfix;
    header.ndirect = shape.ndirect;
    header.literal_tree_count = tree_counts.literal;
    header.distance_tree_count = tree_counts.distance;
    prepareDistanceLookup(header, shape.distance_alphabet_size);
}

/// Brotli's distance parameters are fixed for one meta-block. Mirror the
/// reference decoder's prepared `dist_extra_bits` / `dist_offset` tables so
/// the command loop does not rebuild the RFC distance formula per copy.
fn prepareDistanceLookup(header: *MinimalCompressedHeader, alphabet_size: usize) void {
    std.debug.assert(alphabet_size <= max_distance_alphabet_size);
    var symbol: usize = 16;
    while (symbol < 16 + @as(usize, header.ndirect)) : (symbol += 1) {
        header.distance_extra_bits[symbol] = 0;
        header.distance_offsets[symbol] = @intCast(symbol - 15);
    }
    while (symbol < alphabet_size) : (symbol += 1) {
        const xcode = symbol - @as(usize, header.ndirect) - 16;
        const npostfix: usize = header.npostfix;
        const extra_bits: u5 = @intCast(1 + (xcode >> @intCast(npostfix + 1)));
        header.distance_extra_bits[symbol] = extra_bits;
        header.distance_offsets[symbol] = @intCast(resolveRegularDistanceParts(
            header.npostfix,
            header.ndirect,
            xcode,
            extra_bits,
            0,
        ));
    }
}

const LargeCompressedHeaderShape = struct {
    literal_block_types: u16,
    command_block_types: u16,
    distance_block_types: u16,
    distance_alphabet_size_max: usize,
    distance_alphabet_size: usize,
    large_window: bool,
    npostfix: u2,
    ndirect: u16,
};

inline fn readLargeCompressedHeaderBlockSwitches(reader: *bitstream.BitReader, header: *LargeWindowCompressedHeader, large_window: bool) Error!LargeCompressedHeaderShape {
    const nbltypes_l = try readBlockTypeCount(reader);
    if (nbltypes_l > max_literal_block_types) return error.UnsupportedBrotliFeature;
    header.literal_block = .{ .block_type_count = nbltypes_l };
    if (nbltypes_l >= 2) {
        header.literal_block.type_tree = try readLargePrefixCodeRuntime(max_literal_block_types + 2, @as(usize, nbltypes_l) + 2, reader);
        header.literal_block.length_tree = try readLargePrefixCode(26, reader);
        header.literal_block.remaining = try readBlockLength(&header.literal_block.length_tree, reader);
    }
    const nbltypes_i = try readBlockTypeCount(reader);
    if (nbltypes_i > max_command_block_types) return error.UnsupportedBrotliFeature;
    header.command_block = .{ .block_type_count = nbltypes_i };
    if (nbltypes_i >= 2) {
        header.command_block.type_tree = try readLargePrefixCodeRuntime(max_command_block_types + 2, @as(usize, nbltypes_i) + 2, reader);
        header.command_block.length_tree = try readLargePrefixCode(26, reader);
        header.command_block.remaining = try readBlockLength(&header.command_block.length_tree, reader);
    }
    const nbltypes_d = try readBlockTypeCount(reader);
    if (nbltypes_d > max_distance_block_types) return error.UnsupportedBrotliFeature;
    header.distance_block = .{ .block_type_count = nbltypes_d };
    if (nbltypes_d >= 2) {
        header.distance_block.type_tree = try readLargePrefixCodeRuntime(max_distance_block_types + 2, @as(usize, nbltypes_d) + 2, reader);
        header.distance_block.length_tree = try readLargePrefixCode(26, reader);
        header.distance_block.remaining = try readBlockLength(&header.distance_block.length_tree, reader);
    }

    const npostfix = try reader.readBits(u2, 2);
    const ndirect_high = try reader.readBits(u4, 4);
    const ndirect: u16 = @as(u16, ndirect_high) << npostfix;
    if (ndirect > 120) return error.CorruptFrame;
    const distance_bits: usize = if (large_window) 62 else 24;
    const distance_alphabet_size_max: usize = 16 + @as(usize, ndirect) +
        (distance_bits << @intCast(@as(usize, npostfix) + 1));
    const distance_alphabet_size = if (large_window)
        largeWindowDistanceAlphabetLimit(npostfix, ndirect)
    else
        distance_alphabet_size_max;

    for (0..nbltypes_l) |i| header.literal_context_modes[i] = try reader.readBits(u2, 2);
    return .{
        .literal_block_types = nbltypes_l,
        .command_block_types = nbltypes_i,
        .distance_block_types = nbltypes_d,
        .distance_alphabet_size_max = distance_alphabet_size_max,
        .distance_alphabet_size = distance_alphabet_size,
        .large_window = large_window,
        .npostfix = npostfix,
        .ndirect = ndirect,
    };
}

inline fn readLargeCompressedHeaderContextMaps(reader: *bitstream.BitReader, header: *LargeWindowCompressedHeader, shape: LargeCompressedHeaderShape) Error!CompressedHeaderTreeCounts {
    const ntrees_l = try readBlockTypeCount(reader);
    if (ntrees_l > max_literal_context_trees) return error.UnsupportedBrotliFeature;
    try readContextMap(reader, header.literal_context_map[0..(@as(usize, shape.literal_block_types) * 64)], ntrees_l);
    const ntrees_d = try readBlockTypeCount(reader);
    if (ntrees_d > max_distance_context_trees) return error.UnsupportedBrotliFeature;
    try readContextMap(reader, header.distance_context_map[0..(@as(usize, shape.distance_block_types) * 4)], ntrees_d);
    return .{ .literal = ntrees_l, .distance = ntrees_d };
}

inline fn readLargeCompressedHeaderLiteralTrees(reader: *bitstream.BitReader, header: *LargeWindowCompressedHeader, tree_count: u16) Error!void {
    var literal_tree_index: u16 = 0;
    while (literal_tree_index < tree_count) : (literal_tree_index += 1) {
        const tree = try readLargePrefixCodeRuntime(large_literal_alphabet_capacity, 256, reader);
        if (literal_tree_index < inline_literal_tree_count) {
            header.literal_trees[literal_tree_index] = tree;
        } else {
            header.packed_literal_trees[literal_tree_index - inline_literal_tree_count] = PackedPrefixCode(large_literal_alphabet_capacity).init(&tree);
        }
    }
    header.active_packed_literal_tree_index = std.math.maxInt(u16);
}

inline fn readLargeCompressedHeaderCommandTrees(reader: *bitstream.BitReader, header: *LargeWindowCompressedHeader, tree_count: u16) Error!void {
    var command_tree_index: u16 = 0;
    while (command_tree_index < tree_count) : (command_tree_index += 1) {
        const tree = try readLargePrefixCodeRuntime(large_command_alphabet_capacity, 704, reader);
        if (command_tree_index < inline_command_tree_count) {
            header.insert_copy_trees[command_tree_index] = tree;
        } else {
            header.packed_insert_copy_trees[command_tree_index - inline_command_tree_count] = PackedPrefixCode(large_command_alphabet_capacity).init(&tree);
        }
    }
    header.active_packed_insert_copy_tree_index = std.math.maxInt(u16);
}

inline fn readLargeCompressedHeaderDistanceTrees(comptime distance_capacity: usize, reader: *bitstream.BitReader, header: *LargeWindowCompressedHeader, tree_count: u16, alphabet_size_max: usize, alphabet_size: usize) Error!void {
    var distance_tree_index: u16 = 0;
    while (distance_tree_index < tree_count) : (distance_tree_index += 1) {
        const tree = try readPrefixCodeRuntimeLimited(distance_capacity, alphabet_size_max, alphabet_size, reader);
        if (distance_tree_index < inline_distance_tree_count) {
            header.distance_trees[distance_tree_index] = tree;
        } else {
            header.packed_distance_trees[distance_tree_index - inline_distance_tree_count] = PackedPrefixCode(distance_capacity).init(&tree);
        }
    }
    header.active_packed_distance_tree_index = std.math.maxInt(u16);
}

inline fn finishLargeCompressedHeader(header: *LargeWindowCompressedHeader, shape: LargeCompressedHeaderShape, tree_counts: CompressedHeaderTreeCounts) void {
    header.npostfix = shape.npostfix;
    header.ndirect = shape.ndirect;
    header.literal_tree_count = tree_counts.literal;
    header.distance_tree_count = tree_counts.distance;
}

/// Attribute compressed-header parsing without adding clock reads to the
/// production decoder. The discovery pass uses normal decoding to locate every
/// header; timed iterations reconstruct only those headers from their bit
/// offsets, so payload cost cannot hide parser and table-builder differences.
pub fn profileCompressedHeaders(io: std.Io, allocator: std.mem.Allocator, stream: []const u8, iterations: usize) Error!CompressedHeaderProfile {
    if (iterations == 0) return error.InvalidBlockPlan;

    const starts = try collectCompressedHeaderStarts(allocator, stream);
    defer allocator.free(starts);
    if (starts.len == 0) return error.UnsupportedBrotliFeature;

    var total: CompressedHeaderProfile = .{};
    for (0..iterations) |_| {
        for (starts) |start| {
            var reader = bitstream.BitReader.init(stream);
            reader.byte_index = start / 8;
            reader.bit_index = @intCast(start % 8);
            var header: MinimalCompressedHeader = undefined;
            var literal_profile: PrefixCodeProfile = .{};
            var command_profile: PrefixCodeProfile = .{};
            var distance_profile: PrefixCodeProfile = .{};

            var stage_start = std.Io.Clock.awake.now(io);
            const shape = try readCompressedHeaderBlockSwitches(&reader, &header);
            total.block_switch_ns +%= elapsedNs(stage_start, io);

            stage_start = std.Io.Clock.awake.now(io);
            const tree_counts = try readCompressedHeaderContextMaps(&reader, &header, shape);
            total.context_map_ns +%= elapsedNs(stage_start, io);

            stage_start = std.Io.Clock.awake.now(io);
            try readCompressedHeaderLiteralTreesProfiled(io, &reader, &header, tree_counts.literal, &literal_profile);
            total.literal_tree_ns +%= elapsedNs(stage_start, io);

            stage_start = std.Io.Clock.awake.now(io);
            try readCompressedHeaderCommandTreesProfiled(io, &reader, &header, shape.command_block_types, &command_profile);
            total.command_tree_ns +%= elapsedNs(stage_start, io);

            stage_start = std.Io.Clock.awake.now(io);
            try readCompressedHeaderDistanceTreesProfiled(io, &reader, &header, tree_counts.distance, shape.distance_alphabet_size, &distance_profile);
            total.distance_tree_ns +%= elapsedNs(stage_start, io);
            finishCompressedHeader(&header, shape, tree_counts);

            total.compressed_meta_block_count += 1;
            total.input_bits +%= reader.bitPosition() - start;
            total.literal_block_types +%= shape.literal_block_types;
            total.command_block_types +%= shape.command_block_types;
            total.distance_block_types +%= shape.distance_block_types;
            total.literal_context_trees +%= tree_counts.literal;
            total.command_trees +%= shape.command_block_types;
            total.distance_context_trees +%= tree_counts.distance;
            literal_profile.addTo(&total, PrefixCodeFamily.literal);
            command_profile.addTo(&total, PrefixCodeFamily.command);
            distance_profile.addTo(&total, PrefixCodeFamily.distance);
            accumulateCompressedHeaderTableShape(&total, &header);
            std.mem.doNotOptimizeAway(&header);
        }
    }
    return total;
}

/// Run the same isolated header parse without nested stage clocks. Use this
/// total when comparing implementation candidates; the detailed profile above
/// is for attribution and necessarily includes timing-call overhead.
pub fn benchmarkCompressedHeaders(io: std.Io, allocator: std.mem.Allocator, stream: []const u8, iterations: usize) Error!struct { elapsed_ns: u64, checksum: usize } {
    if (iterations == 0) return error.InvalidBlockPlan;
    const starts = try collectCompressedHeaderStarts(allocator, stream);
    defer allocator.free(starts);
    if (starts.len == 0) return error.UnsupportedBrotliFeature;

    var checksum: usize = 0;
    const start_time = std.Io.Clock.awake.now(io);
    for (0..iterations) |_| {
        for (starts) |start| {
            var reader = bitstream.BitReader.init(stream);
            reader.byte_index = start / 8;
            reader.bit_index = @intCast(start % 8);
            var header: MinimalCompressedHeader = undefined;
            try readMinimalCompressedHeaderInto(&reader, &header);
            checksum +%= reader.bitPosition() + header.literal_tree_count + header.command_block.block_type_count + header.distance_tree_count;
            checksum +%= header.literal_trees[0].table.len + header.insert_copy_trees[0].table.len + header.distance_trees[0].table.len;
            std.mem.doNotOptimizeAway(&header);
        }
    }
    return .{ .elapsed_ns = elapsedNs(start_time, io), .checksum = checksum };
}

pub const ClusteredDecodeStageSample = struct {
    iterations: usize,
    header_ns: u64,
    literal_lookup_ns: u64,
    command_lookup_ns: u64,
    distance_lookup_ns: u64,
    payload_ns: u64,
    total_ns: u64,
    checksum: usize,

    pub fn lookupNs(self: ClusteredDecodeStageSample) u64 {
        return self.literal_lookup_ns + self.command_lookup_ns + self.distance_lookup_ns;
    }
};

/// Benchmark the three independently actionable stages of the standard
/// high-tree-count decoder. This diagnostic path requires the exact flat
/// multi-tree route used by `clustered_q8`; ordinary decode remains the
/// correctness and end-to-end performance authority.
pub fn benchmarkClusteredDecodeStages(
    io: std.Io,
    allocator: std.mem.Allocator,
    stream: []const u8,
    expected: []const u8,
    iterations: usize,
) Error!ClusteredDecodeStageSample {
    if (iterations == 0 or expected.len == 0) return error.InvalidBlockPlan;
    const output = try allocator.alloc(u8, expected.len);
    defer allocator.free(output);

    var header_ns: u64 = 0;
    var literal_lookup_ns: u64 = 0;
    var command_lookup_ns: u64 = 0;
    var distance_lookup_ns: u64 = 0;
    var payload_ns: u64 = 0;
    var checksum: usize = 0;
    const total_start = std.Io.Clock.awake.now(io);
    for (0..iterations) |_| {
        var reader = bitstream.BitReader.init(stream);
        const window_bits = try readWindowBitsValue(&reader);
        const meta = switch (try readStreamMetaBlockHeader(&reader)) {
            .compressed => |compressed| compressed,
            else => return error.UnsupportedBrotliFeature,
        };
        if (!meta.final or meta.decoded_len != expected.len) return error.UnsupportedBrotliFeature;

        var header: MinimalCompressedHeader = undefined;
        var stage_start = std.Io.Clock.awake.now(io);
        try readMinimalCompressedHeaderInto(&reader, &header);
        header_ns +%= elapsedNs(stage_start, io);
        if (header.literal_tree_count < clustered_literal_tree_threshold or
            header.literal_tree_count > inline_literal_tree_count or
            header.command_block.block_type_count == 0 or
            header.command_block.block_type_count > multi_tree_zero_insert_command_limit or
            header.distance_tree_count > inline_distance_tree_count) return error.UnsupportedBrotliFeature;

        stage_start = std.Io.Clock.awake.now(io);
        var literal_lookups: [inline_literal_tree_count]TailLiteralLookup = undefined;
        if (!try prepareFlatLiteralTailLookups(&header, &literal_lookups)) return error.UnsupportedBrotliFeature;
        literal_lookup_ns +%= elapsedNs(stage_start, io);

        stage_start = std.Io.Clock.awake.now(io);
        var command_lookups: [multi_tree_zero_insert_command_limit]single_command_lookup.Lookup = undefined;
        for (header.insert_copy_trees[0..header.command_block.block_type_count], 0..) |*tree, index| {
            command_lookups[index] = if (tree.single_symbol) |symbol|
                try single_command_lookup.Lookup.initSingle(symbol)
            else
                try single_command_lookup.Lookup.init(&tree.table);
        }
        command_lookup_ns +%= elapsedNs(stage_start, io);

        stage_start = std.Io.Clock.awake.now(io);
        var distance_lookups: [inline_distance_tree_count]ExternalDistanceLookup = undefined;
        for (header.distance_trees[0..header.distance_tree_count], 0..) |*tree, index| {
            distance_lookups[index] = if (tree.single_symbol) |symbol|
                try ExternalDistanceLookup.initSingle(symbol)
            else
                try ExternalDistanceLookup.init(&tree.table);
        }
        distance_lookup_ns +%= elapsedNs(stage_start, io);

        var fast_reader = fast_bit_reader.Reader.initFrom(reader);
        var written: usize = 0;
        var last_distances = initial_last_distances;
        stage_start = std.Io.Clock.awake.now(io);
        try processTailLookupCompressedPayload(
            true,
            true,
            true,
            &fast_reader,
            output,
            &written,
            expected.len,
            &last_distances,
            window_bits,
            &header,
            &literal_lookups,
            null,
            &command_lookups,
            &distance_lookups,
        );
        payload_ns +%= elapsedNs(stage_start, io);
        fast_reader.syncTo(&reader);
        if (written != expected.len) return error.SizeMismatch;
        try ensureZeroPaddingAndEnd(reader);
        checksum +%= written + reader.bitPosition() + output[0] + output[output.len - 1];
    }
    const total_ns = elapsedNs(total_start, io);
    if (!std.mem.eql(u8, output, expected)) return error.SizeMismatch;
    return .{
        .iterations = iterations,
        .header_ns = header_ns,
        .literal_lookup_ns = literal_lookup_ns,
        .command_lookup_ns = command_lookup_ns,
        .distance_lookup_ns = distance_lookup_ns,
        .payload_ns = payload_ns,
        .total_ns = total_ns,
        .checksum = checksum,
    };
}

fn readCompressedHeaderLiteralTreesProfiled(io: std.Io, reader: *bitstream.BitReader, header: *MinimalCompressedHeader, tree_count: u16, profile: *PrefixCodeProfile) Error!void {
    var tree_index: u16 = 0;
    while (tree_index < tree_count) : (tree_index += 1) {
        const tree = try readPrefixCodeRuntimeProfiled(256, 256, reader, io, profile);
        if (tree_index < inline_literal_tree_count) {
            header.literal_trees[tree_index] = tree;
        } else {
            header.packed_literal_trees[tree_index - inline_literal_tree_count] = PackedPrefixCode(256).init(&tree);
        }
    }
    header.active_packed_literal_tree_index = std.math.maxInt(u16);
}

fn readCompressedHeaderCommandTreesProfiled(io: std.Io, reader: *bitstream.BitReader, header: *MinimalCompressedHeader, tree_count: u16, profile: *PrefixCodeProfile) Error!void {
    var tree_index: u16 = 0;
    while (tree_index < tree_count) : (tree_index += 1) {
        const tree = try readPrefixCodeRuntimeProfiled(704, 704, reader, io, profile);
        if (tree_index < inline_command_tree_count) {
            header.insert_copy_trees[tree_index] = tree;
        } else {
            header.packed_insert_copy_trees[tree_index - inline_command_tree_count] = PackedPrefixCode(704).init(&tree);
        }
    }
    header.active_packed_insert_copy_tree_index = std.math.maxInt(u16);
}

fn readCompressedHeaderDistanceTreesProfiled(io: std.Io, reader: *bitstream.BitReader, header: *MinimalCompressedHeader, tree_count: u16, alphabet_size: usize, profile: *PrefixCodeProfile) Error!void {
    var tree_index: u16 = 0;
    while (tree_index < tree_count) : (tree_index += 1) {
        const tree = try readPrefixCodeRuntimeProfiled(max_distance_alphabet_size, alphabet_size, reader, io, profile);
        if (tree_index < inline_distance_tree_count) {
            header.distance_trees[tree_index] = tree;
        } else {
            header.packed_distance_trees[tree_index - inline_distance_tree_count] = PackedPrefixCode(max_distance_alphabet_size).init(&tree);
        }
    }
    header.active_packed_distance_tree_index = std.math.maxInt(u16);
}

fn collectCompressedHeaderStarts(allocator: std.mem.Allocator, stream: []const u8) Error![]usize {
    var starts: std.ArrayList(usize) = .empty;
    errdefer starts.deinit(allocator);

    var output: std.ArrayList(u8) = .empty;
    defer output.deinit(allocator);
    var reader = bitstream.BitReader.init(stream);
    const window_bits = try readWindowBitsValue(&reader);
    var written: usize = 0;
    var last_distances = initial_last_distances;
    while (true) {
        switch (try readStreamMetaBlockHeader(&reader)) {
            .end => {
                try ensureZeroPaddingAndEnd(reader);
                return starts.toOwnedSlice(allocator);
            },
            .metadata => try skipMetadataMetaBlock(&reader),
            .compressed => |meta| {
                try starts.append(allocator, reader.bitPosition());
                const end = std.math.add(usize, written, meta.decoded_len) catch return error.IntegerOverflow;
                try output.resize(allocator, end);
                try processMinimalCompressedMetaBlock(&reader, output.items, &written, meta.decoded_len, &last_distances, window_bits);
                if (written != end) return error.SizeMismatch;
                if (meta.final) {
                    try ensureZeroPaddingAndEnd(reader);
                    return starts.toOwnedSlice(allocator);
                }
            },
            .uncompressed => |len| {
                const end = std.math.add(usize, written, len) catch return error.IntegerOverflow;
                try output.resize(allocator, end);
                try consumeZeroPaddingToByte(&reader);
                try reader.readAlignedBytes(output.items[written..end]);
                written = end;
            },
        }
    }
}

fn accumulateCompressedHeaderTableShape(profile: *CompressedHeaderProfile, header: *const MinimalCompressedHeader) void {
    accumulatePrefixTableShape(max_literal_block_types + 2, profile, &header.literal_block.type_tree);
    accumulatePrefixTableShape(26, profile, &header.literal_block.length_tree);
    accumulatePrefixTableShape(max_command_block_types + 2, profile, &header.command_block.type_tree);
    accumulatePrefixTableShape(26, profile, &header.command_block.length_tree);
    accumulatePrefixTableShape(max_distance_block_types + 2, profile, &header.distance_block.type_tree);
    accumulatePrefixTableShape(26, profile, &header.distance_block.length_tree);
    const inline_literal_count = @min(@as(usize, header.literal_tree_count), inline_literal_tree_count);
    for (header.literal_trees[0..inline_literal_count]) |*tree| accumulatePrefixTableShape(256, profile, tree);
    if (header.literal_tree_count > inline_literal_tree_count) {
        const packed_count = @as(usize, header.literal_tree_count) - inline_literal_tree_count;
        for (header.packed_literal_trees[0..packed_count]) |*tree| accumulatePackedPrefixShape(profile, tree);
    }
    const inline_count = @min(@as(usize, header.command_block.block_type_count), inline_command_tree_count);
    for (header.insert_copy_trees[0..inline_count]) |*tree| accumulatePrefixTableShape(704, profile, tree);
    if (header.command_block.block_type_count > inline_command_tree_count) {
        const packed_count = @as(usize, header.command_block.block_type_count) - inline_command_tree_count;
        for (header.packed_insert_copy_trees[0..packed_count]) |*tree| {
            profile.tree_symbols +%= @intFromBool(tree.single_symbol_plus_one != 0);
            profile.tree_entries +%= tree.active_entries;
        }
    }
    const inline_distance_count = @min(@as(usize, header.distance_tree_count), inline_distance_tree_count);
    for (header.distance_trees[0..inline_distance_count]) |*tree| accumulatePrefixTableShape(max_distance_alphabet_size, profile, tree);
    if (header.distance_tree_count > inline_distance_tree_count) {
        const packed_count = @as(usize, header.distance_tree_count) - inline_distance_tree_count;
        for (header.packed_distance_trees[0..packed_count]) |*tree| accumulatePackedPrefixShape(profile, tree);
    }
}

fn accumulatePackedPrefixShape(profile: *CompressedHeaderProfile, tree: anytype) void {
    profile.tree_symbols +%= @intFromBool(tree.single_symbol_plus_one != 0);
    profile.tree_entries +%= tree.active_entries;
}

fn accumulatePrefixTableShape(comptime alphabet_size: usize, profile: *CompressedHeaderProfile, tree: *const PrefixCode(alphabet_size)) void {
    profile.tree_symbols +%= @intFromBool(tree.single_symbol != null);
    profile.tree_entries +%= tree.table.len;
}

fn readBlockLength(prefix: *const PrefixCode(26), reader: *bitstream.BitReader) Error!usize {
    return readBlockLengthAny(prefix, reader);
}

fn readBlockLengthAny(prefix: *const PrefixCode(26), reader: anytype) Error!usize {
    const symbol = try prefix.decode(reader);
    if (symbol >= block_length_specs.len) return error.InvalidHuffmanCode;
    const spec = block_length_specs[symbol];
    const extra = try reader.readBits(usize, spec.extra_bits);
    return spec.base + extra;
}

const block_length_specs = [_]LengthSpec{
    .{ .base = 1, .extra_bits = 2 },
    .{ .base = 5, .extra_bits = 2 },
    .{ .base = 9, .extra_bits = 2 },
    .{ .base = 13, .extra_bits = 2 },
    .{ .base = 17, .extra_bits = 3 },
    .{ .base = 25, .extra_bits = 3 },
    .{ .base = 33, .extra_bits = 3 },
    .{ .base = 41, .extra_bits = 3 },
    .{ .base = 49, .extra_bits = 4 },
    .{ .base = 65, .extra_bits = 4 },
    .{ .base = 81, .extra_bits = 4 },
    .{ .base = 97, .extra_bits = 4 },
    .{ .base = 113, .extra_bits = 5 },
    .{ .base = 145, .extra_bits = 5 },
    .{ .base = 177, .extra_bits = 5 },
    .{ .base = 209, .extra_bits = 5 },
    .{ .base = 241, .extra_bits = 6 },
    .{ .base = 305, .extra_bits = 6 },
    .{ .base = 369, .extra_bits = 7 },
    .{ .base = 497, .extra_bits = 8 },
    .{ .base = 753, .extra_bits = 9 },
    .{ .base = 1265, .extra_bits = 10 },
    .{ .base = 2289, .extra_bits = 11 },
    .{ .base = 4337, .extra_bits = 12 },
    .{ .base = 8433, .extra_bits = 13 },
    .{ .base = 16625, .extra_bits = 24 },
};

fn readZeroContextMap(reader: *bitstream.BitReader, context_map_size: usize, ntrees: u16) Error!void {
    var context_map: [64]u8 = undefined;
    if (context_map_size > context_map.len) return error.UnsupportedBrotliFeature;
    try readContextMap(reader, context_map[0..context_map_size], ntrees);
    for (context_map[0..context_map_size]) |tree_index| {
        if (tree_index != 0) return error.UnsupportedBrotliFeature;
    }
}

fn readContextMap(reader: *bitstream.BitReader, context_map: []u8, ntrees: u16) Error!void {
    if (ntrees == 0) return error.CorruptFrame;
    @memset(context_map, 0);
    if (ntrees == 1) return;

    const use_rle_for_zeros = try reader.readBits(u1, 1);
    const max_run_length_prefix: u5 = if (use_rle_for_zeros == 0) 0 else @as(u5, try reader.readBits(u4, 4)) + 1;
    const alphabet_size = @as(usize, ntrees) + max_run_length_prefix;
    const prefix = try readPrefixCodeRuntime(max_context_map_alphabet_size, alphabet_size, reader);

    var written: usize = 0;
    while (written < context_map.len) {
        const code = try prefix.decode(reader);
        if (code == 0) {
            context_map[written] = 0;
            written += 1;
            continue;
        }
        if (code <= max_run_length_prefix) {
            const run_extra = try reader.readBits(usize, @intCast(code));
            const run_len = (@as(usize, 1) << @intCast(code)) + run_extra;
            if (run_len > context_map.len - written) return error.CorruptFrame;
            @memset(context_map[written..][0..run_len], 0);
            written += run_len;
            continue;
        }
        const tree_index = code - max_run_length_prefix;
        if (tree_index >= ntrees) return error.CorruptFrame;
        context_map[written] = @intCast(tree_index);
        written += 1;
    }

    const imtf = try reader.readBits(u1, 1);
    if (imtf != 0) applyInverseMoveToFront(context_map);
}

fn applyInverseMoveToFront(context_map: []u8) void {
    var mtf: [256]u8 = undefined;
    for (&mtf, 0..) |*value, i| value.* = @intCast(i);

    for (context_map) |*entry| {
        const index = entry.*;
        const value = mtf[index];
        if (index != 0) {
            var i: usize = index;
            while (i > 0) : (i -= 1) {
                mtf[i] = mtf[i - 1];
            }
            mtf[0] = value;
        }
        entry.* = value;
    }
}

fn readInsertCopyLengths(symbol: u16, reader: anytype) Error!InsertCopyLengths {
    if (symbol >= 704) return error.InvalidHuffmanCode;
    const entry = command_lut.entries[symbol];
    const insert_extra = if (entry.insert_extra_bits == 0) 0 else try reader.readBits(u32, entry.insert_extra_bits);
    const copy_extra = if (entry.copy_extra_bits == 0) 0 else try reader.readBits(u32, entry.copy_extra_bits);
    return .{
        .insert_len = entry.insert_base + insert_extra,
        .copy_len = entry.copy_base + copy_extra,
        .distance_symbol_zero = entry.distance_code == 0,
    };
}

inline fn readInsertCopyLengthsStaged(symbol: u16, reader: anytype) Error!InsertCopyLengths {
    if (symbol >= 704) return error.InvalidHuffmanCode;
    const entry = command_lut.entries[symbol];
    const insert_extra = if (entry.insert_extra_bits == 0) 0 else try reader.readBits24StagedFirst(entry.insert_extra_bits);
    const copy_extra = if (entry.copy_extra_bits == 0) 0 else try reader.readBits24StagedFirst(entry.copy_extra_bits);
    return .{
        .insert_len = entry.insert_base + insert_extra,
        .copy_len = entry.copy_base + copy_extra,
        .distance_symbol_zero = entry.distance_code == 0,
    };
}

inline fn readInsertCopyLengthsStagedCompact(
    symbol: u16,
    reader: anytype,
) Error!InsertCopyLengths {
    if (symbol >= command_lut.entries.len) return error.InvalidHuffmanCode;
    const entry = command_lut.compact_entries[symbol];
    const insert_extra = if (entry.insert_extra_bits == 0) 0 else try reader.readBits24StagedFirst(entry.insert_extra_bits);
    const copy_extra = if (entry.copy_extra_bits == 0) 0 else try reader.readBits24StagedFirst(entry.copy_extra_bits);
    return .{
        .insert_len = entry.insert_base + insert_extra,
        .copy_len = entry.copy_base + copy_extra,
        .distance_symbol_zero = entry.distance_code == 0,
    };
}

fn processMinimalCompressedMetaBlock(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window_bits: u5,
) Error!void {
    const meta_block_end = std.math.add(usize, written.*, meta_block_len) catch return error.IntegerOverflow;
    if (meta_block_end > output.len) return error.OutputTooSmall;
    var header: MinimalCompressedHeader = undefined;
    try readMinimalCompressedHeaderInto(reader, &header);
    var transformed_dictionary_word: [64]u8 = undefined;
    while (written.* < meta_block_end) {
        const command_symbol = try readCommandSymbol(&header, reader);
        const lengths = try readInsertCopyLengths(command_symbol, reader);
        if (lengths.insert_len > meta_block_end - written.*) return error.CorruptFrame;
        var i: usize = 0;
        while (i < lengths.insert_len) : (i += 1) {
            try ensureLiteralBlock(&header, reader);
            const context = try literalContext(&header, output, written.*);
            const tree_index = header.literal_context_map[@as(usize, header.literal_block.current_type) * 64 + context];
            if (tree_index >= max_literal_context_trees) return error.UnsupportedBrotliFeature;
            const tree = try literalPrefixForDecode(&header, tree_index);
            const literal = try tree.decode(reader);
            if (literal > 0xff) return error.InvalidHuffmanCode;
            output[written.*] = @intCast(literal);
            written.* += 1;
            if (header.literal_block.remaining != 0) header.literal_block.remaining -= 1;
        }
        if (written.* == meta_block_end) return;
        const decoded_distance = try readMinimalDistance(&header, reader, lengths, last_distances);
        const distance = decoded_distance.distance;
        if (distance == 0) return error.InvalidMatch;
        const max_distance = maxBackwardDistanceForWindow(window_bits, written.*);
        if (distance > max_distance) {
            const word = try minimalStaticDictionaryWord(distance, lengths.copy_len, max_distance, &transformed_dictionary_word);
            if (word.len > meta_block_end - written.*) return error.CorruptFrame;
            @memcpy(output[written.*..][0..word.len], word);
            written.* += word.len;
            continue;
        }
        if (decoded_distance.update_ring) pushLastDistance(last_distances, distance);
        if (lengths.copy_len > meta_block_end - written.*) return error.CorruptFrame;
        match_copy.append(output, written, distance, lengths.copy_len, meta_block_end);
    }
}

fn processMinimalCompressedMetaBlockWithOptions(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window: WindowInfo,
) Error!void {
    if (window.large) {
        @branchHint(.unlikely);
        return processMinimalCompressedMetaBlockLargeWindow(reader, output, written, meta_block_len, last_distances, window.bits);
    }
    return processMinimalCompressedMetaBlock(reader, output, written, meta_block_len, last_distances, window.bits);
}

noinline fn processMinimalCompressedMetaBlockLargeWindow(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window_bits: u5,
) linksection(large_window_text_section) Error!void {
    return processMinimalCompressedMetaBlockLargeWindowImpl(reader, output, written, meta_block_len, last_distances, window_bits);
}

fn processMinimalCompressedMetaBlockLargeWindowImpl(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window_bits: u5,
) Error!void {
    const meta_block_end = std.math.add(usize, written.*, meta_block_len) catch return error.IntegerOverflow;
    if (meta_block_end > output.len) return error.OutputTooSmall;
    var header: LargeWindowCompressedHeader = undefined;
    try readMinimalCompressedHeaderIntoWithOptions(reader, &header, true);
    var transformed_dictionary_word: [64]u8 = undefined;
    while (written.* < meta_block_end) {
        const command_symbol = try readLargeCommandSymbol(&header, reader);
        const lengths = try readInsertCopyLengths(command_symbol, reader);
        if (lengths.insert_len > meta_block_end - written.*) return error.CorruptFrame;
        var i: usize = 0;
        while (i < lengths.insert_len) : (i += 1) {
            try ensureLargeLiteralBlock(&header, reader);
            const context = try largeLiteralContext(&header, output, written.*);
            const tree_index = header.literal_context_map[@as(usize, header.literal_block.current_type) * 64 + context];
            if (tree_index >= max_literal_context_trees) return error.UnsupportedBrotliFeature;
            const tree = try largeLiteralPrefixForDecode(&header, tree_index);
            const literal = try tree.decode(reader);
            if (literal > 0xff) return error.InvalidHuffmanCode;
            output[written.*] = @intCast(literal);
            written.* += 1;
            if (header.literal_block.remaining != 0) header.literal_block.remaining -= 1;
        }
        if (written.* == meta_block_end) return;
        const decoded_distance = try readMinimalDistanceLargeWindow(&header, reader, lengths, last_distances);
        const distance = decoded_distance.distance;
        if (distance == 0) return error.InvalidMatch;
        const max_distance = maxBackwardDistanceForWindow(window_bits, written.*);
        if (distance > max_distance) {
            const word = try minimalStaticDictionaryWord(distance, lengths.copy_len, max_distance, &transformed_dictionary_word);
            if (word.len > meta_block_end - written.*) return error.CorruptFrame;
            @memcpy(output[written.*..][0..word.len], word);
            written.* += word.len;
            continue;
        }
        if (decoded_distance.update_ring) pushLastDistance(last_distances, distance);
        if (lengths.copy_len > meta_block_end - written.*) return error.CorruptFrame;
        match_copy.append(output, written, distance, lengths.copy_len, meta_block_end);
    }
}

fn processLargeCompressedMetaBlockWithOptions(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window: WindowInfo,
) Error!void {
    if (window.large) {
        @branchHint(.unlikely);
        return processLargeCompressedMetaBlockLargeWindow(reader, output, written, meta_block_len, last_distances, window.bits);
    }
    return processLargeCompressedMetaBlock(reader, output, written, meta_block_len, last_distances, window.bits);
}

fn processLargeCompressedMetaBlock(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window_bits: u5,
) Error!void {
    const meta_block_end = std.math.add(usize, written.*, meta_block_len) catch return error.IntegerOverflow;
    if (meta_block_end > output.len) return error.OutputTooSmall;
    var header: MinimalCompressedHeader = undefined;
    try readMinimalCompressedHeaderInto(reader, &header);
    if (header.literal_tree_count >= clustered_literal_tree_threshold and
        header.literal_tree_count <= inline_literal_tree_count and
        try processFlatLiteralTailLookupMetaBlock(reader, output, written, meta_block_end, last_distances, window_bits, &header)) return;
    if (meta_block_len >= external_literal_lookup_meta_block_min and
        header.literal_tree_count <= external_literal_lookup_tree_limit)
    {
        var literal_lookups: [external_literal_lookup_tree_limit]ExternalLiteralLookup = undefined;
        try prepareExternalLiteralLookups(&header, &literal_lookups);
        if (builtin.is_test) test_external_literal_lookup_hits += 1;
        if (header.literal_tree_count == 1 and
            header.literal_block.block_type_count == 1 and
            header.command_block.block_type_count == 1 and
            header.distance_tree_count == 1 and
            header.distance_block.block_type_count == 1)
        {
            if (builtin.is_test) test_single_tree_external_lookup_hits += 1;
            var command_lookup = if (header.insert_copy_trees[0].single_symbol) |symbol|
                try single_command_lookup.Lookup.initSingle(symbol)
            else
                try single_command_lookup.Lookup.init(&header.insert_copy_trees[0].table);
            var distance_lookup = if (header.distance_trees[0].single_symbol) |symbol|
                try ExternalDistanceLookup.initSingle(symbol)
            else
                try ExternalDistanceLookup.init(&header.distance_trees[0].table);
            var fast_reader = fast_bit_reader.Reader.initFrom(reader.*);
            defer fast_reader.syncTo(reader);
            return processSingleTreeExternalLookupCompressedPayload(
                &fast_reader,
                output,
                written,
                meta_block_end,
                last_distances,
                window_bits,
                &header,
                &literal_lookups[0],
                &command_lookup,
                &distance_lookup,
            );
        }
        const auxiliary_tail_lookups = prepareAuxiliaryTailLookups(&header);
        var fast_reader = fast_bit_reader.Reader.initFrom(reader.*);
        defer fast_reader.syncTo(reader);
        if (auxiliary_tail_lookups)
            return processExternalLiteralLookupCompressedPayload(true, &fast_reader, output, written, meta_block_end, last_distances, window_bits, &header, &literal_lookups);
        return processExternalLiteralLookupCompressedPayload(false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, &header, &literal_lookups);
    }
    if (meta_block_len >= external_literal_lookup_meta_block_min) {
        if (header.literal_tree_count <= external_literal_lookup_middle_tree_limit) {
            return processWideExternalLiteralLookup9MetaBlock(external_literal_lookup_middle_tree_limit, reader, output, written, meta_block_end, last_distances, window_bits, &header);
        }
        if (prepareAuxiliaryTailLookups(&header))
            return processPairedWideLiteralMetaBlock(reader, output, written, meta_block_end, last_distances, window_bits, &header);
        return processWideExternalLiteralLookupMetaBlock(max_literal_context_trees, reader, output, written, meta_block_end, last_distances, window_bits, &header);
    }
    return processDecodedCompressedPayload(reader, output, written, meta_block_end, last_distances, window_bits, &header);
}

noinline fn processSingleTreeExternalLookupCompressedPayload(
    reader: anytype,
    output: []u8,
    written: *usize,
    meta_block_end: usize,
    last_distances: *[4]usize,
    window_bits: u5,
    header: *MinimalCompressedHeader,
    literal_lookup: *const ExternalLiteralLookup,
    command_lookup: *const single_command_lookup.Lookup,
    distance_lookup: *const ExternalDistanceLookup,
) Error!void {
    var transformed_dictionary_word: [64]u8 = undefined;
    var output_cursor = written.*;
    defer written.* = output_cursor;
    while (output_cursor < meta_block_end) {
        const lengths = try readInsertCopyLengthsSingleExternalLookup10(header, reader, command_lookup);
        if (lengths.insert_len > meta_block_end - output_cursor) return error.CorruptFrame;
        var index: usize = 0;
        while (index < lengths.insert_len) : (index += 1) {
            const literal = (try literal_lookup.decodeValueFast10(reader)) orelse
                try literal_lookup.decodeValueLong(&header.literal_trees[0].table, reader);
            if (literal > 0xff) return error.InvalidHuffmanCode;
            output[output_cursor] = @intCast(literal);
            output_cursor += 1;
        }
        if (output_cursor == meta_block_end) return;
        var decoded_distance: DecodedBrotliDistance = undefined;
        try readMinimalDistanceSingleExternalLookup9(header, reader, lengths, last_distances, &decoded_distance, distance_lookup);
        const distance = decoded_distance.distance;
        if (distance == 0) return error.InvalidMatch;
        const max_distance = maxBackwardDistanceForWindow(window_bits, output_cursor);
        if (distance > max_distance) {
            const word = try minimalStaticDictionaryWord(distance, lengths.copy_len, max_distance, &transformed_dictionary_word);
            if (word.len > meta_block_end - output_cursor) return error.CorruptFrame;
            dictionary_copy.append(output, &output_cursor, word);
            continue;
        }
        if (decoded_distance.update_ring) pushLastDistance(last_distances, distance);
        if (lengths.copy_len > meta_block_end - output_cursor) return error.CorruptFrame;
        match_copy.append(output, &output_cursor, distance, lengths.copy_len, meta_block_end);
    }
}

noinline fn processLargeCompressedMetaBlockLargeWindow(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_len: usize,
    last_distances: *[4]usize,
    window_bits: u5,
) linksection(large_window_text_section) Error!void {
    const meta_block_end = std.math.add(usize, written.*, meta_block_len) catch return error.IntegerOverflow;
    if (meta_block_end > output.len) return error.OutputTooSmall;
    var header: LargeWindowCompressedHeader = undefined;
    try readMinimalCompressedHeaderIntoWithOptions(reader, &header, true);
    if (header.literal_tree_count < clustered_literal_tree_threshold or !prepareLargeLiteralTailLookups(&header))
        return processDecodedCompressedPayloadLargeWindow(reader, output, written, meta_block_end, last_distances, window_bits, &header);
    const auxiliary_tail_lookups = prepareLargeAuxiliaryTailLookups(&header);
    var fast_reader = fast_bit_reader.Reader.initFrom(reader.*);
    defer fast_reader.syncTo(reader);
    if (auxiliary_tail_lookups)
        return processTailLookupCompressedPayloadLargeWindow(true, &fast_reader, output, written, meta_block_end, last_distances, window_bits, &header);
    return processTailLookupCompressedPayloadLargeWindow(false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, &header);
}

const clustered_literal_tree_threshold: u16 = 16;
const external_literal_lookup_tree_limit: usize = inline_literal_tree_count;
const external_literal_lookup_middle_tree_limit: usize = 128;
const external_literal_lookup_meta_block_min: usize = 64 * 1024;
const multi_tree_zero_insert_command_limit: usize = 4;
const wide_literal_lookup9_text_section = code_sections.wide_literal_lookup9;
const wide_literal_lookup10_auxiliary_text_section = code_sections.wide_literal_lookup10_auxiliary;
const paired_literal_text_section = paired_literal_lookup.text_section;
const ExternalLiteralLookup = huffman.PackedLookup(10);
const WideExternalLiteralLookup9 = huffman.PackedLookup(9);
const ExternalCommandLookup = huffman.PackedLookup(10);
const ExternalDistanceLookup = huffman.PackedLookup(9);
const TailLiteralLookup = huffman.PackedLookup(8);

comptime {
    std.debug.assert(external_literal_lookup_tree_limit <= inline_literal_tree_count);
    std.debug.assert(external_literal_lookup_tree_limit < external_literal_lookup_middle_tree_limit);
    std.debug.assert(external_literal_lookup_middle_tree_limit < max_literal_context_trees);
}

fn prepareLiteralTailLookups(header: *MinimalCompressedHeader) bool {
    if (header.literal_tree_count > inline_literal_tree_count) return false;
    for (header.literal_trees[0..header.literal_tree_count]) |*tree|
        if (!tree.canPrepareTailLookup()) return false;
    for (header.literal_trees[0..header.literal_tree_count]) |*tree|
        std.debug.assert(tree.prepareTailLookup());
    return true;
}

fn prepareFlatLiteralTailLookups(
    header: *const MinimalCompressedHeader,
    lookups: *[inline_literal_tree_count]TailLiteralLookup,
) Error!bool {
    if (header.literal_tree_count > lookups.len) return false;
    for (header.literal_trees[0..header.literal_tree_count]) |*tree|
        if (!tree.canPrepareTailLookup()) return false;
    for (header.literal_trees[0..header.literal_tree_count], 0..) |*tree, index| {
        lookups[index] = if (tree.single_symbol) |symbol|
            try TailLiteralLookup.initSingle(symbol)
        else
            try TailLiteralLookup.init(&tree.table);
    }
    return true;
}

noinline fn tryProcessMultiTreeZeroInsertMetaBlock(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_end: usize,
    last_distances: *[4]usize,
    window_bits: u5,
    header: *MinimalCompressedHeader,
    literal_lookups: *const [inline_literal_tree_count]TailLiteralLookup,
) Error!bool {
    const command_type_count = header.command_block.block_type_count;
    if (command_type_count == 0 or
        command_type_count > multi_tree_zero_insert_command_limit or
        header.distance_tree_count > inline_distance_tree_count) return false;

    var command_lookups: [multi_tree_zero_insert_command_limit]single_command_lookup.Lookup = undefined;
    for (header.insert_copy_trees[0..command_type_count], 0..) |*tree, index| {
        command_lookups[index] = if (tree.single_symbol) |symbol|
            try single_command_lookup.Lookup.initSingle(symbol)
        else
            try single_command_lookup.Lookup.init(&tree.table);
    }
    var distance_lookups: [inline_distance_tree_count]ExternalDistanceLookup = undefined;
    for (header.distance_trees[0..header.distance_tree_count], 0..) |*tree, index| {
        distance_lookups[index] = if (tree.single_symbol) |symbol|
            try ExternalDistanceLookup.initSingle(symbol)
        else
            try ExternalDistanceLookup.init(&tree.table);
    }

    var fast_reader = fast_bit_reader.Reader.initFrom(reader.*);
    defer fast_reader.syncTo(reader);
    try processTailLookupCompressedPayload(
        true,
        true,
        true,
        &fast_reader,
        output,
        written,
        meta_block_end,
        last_distances,
        window_bits,
        header,
        literal_lookups,
        null,
        &command_lookups,
        &distance_lookups,
    );
    return true;
}

noinline fn processFlatLiteralTailLookupMetaBlock(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_end: usize,
    last_distances: *[4]usize,
    window_bits: u5,
    header: *MinimalCompressedHeader,
) Error!bool {
    var literal_lookups: [inline_literal_tree_count]TailLiteralLookup = undefined;
    if (!try prepareFlatLiteralTailLookups(header, &literal_lookups)) return false;
    if (try tryProcessMultiTreeZeroInsertMetaBlock(
        reader,
        output,
        written,
        meta_block_end,
        last_distances,
        window_bits,
        header,
        &literal_lookups,
    )) return true;
    var command_lookups: [inline_command_tree_count]ExternalCommandLookup = undefined;
    var distance_lookups: [inline_distance_tree_count]ExternalDistanceLookup = undefined;
    var fast_reader = fast_bit_reader.Reader.initFrom(reader.*);
    defer fast_reader.syncTo(reader);
    if (try prepareExternalAuxiliaryLookups(header, &command_lookups, &distance_lookups)) {
        try processTailLookupCompressedPayload(true, true, false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, header, &literal_lookups, &command_lookups, null, &distance_lookups);
    } else if (prepareAuxiliaryTailLookups(header))
        try processTailLookupCompressedPayload(true, false, false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, header, &literal_lookups, null, null, null)
    else
        try processTailLookupCompressedPayload(false, false, false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, header, &literal_lookups, null, null, null);
    return true;
}

fn prepareExternalAuxiliaryLookups(
    header: *MinimalCompressedHeader,
    command_lookups: *[inline_command_tree_count]ExternalCommandLookup,
    distance_lookups: *[inline_distance_tree_count]ExternalDistanceLookup,
) Error!bool {
    if (header.command_block.block_type_count > inline_command_tree_count or
        header.distance_tree_count > inline_distance_tree_count) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup10()) return false;
    for (0..header.command_block.block_type_count) |index| {
        const tree = &header.insert_copy_trees[index];
        command_lookups[index] = if (tree.single_symbol) |symbol|
            try ExternalCommandLookup.initSingleMapped(symbol, command_lut.fuseLookupSlot)
        else
            try ExternalCommandLookup.initMapped(&tree.table, command_lut.fuseLookupSlot);
    }
    for (header.distance_trees[0..header.distance_tree_count], 0..) |*tree, index| {
        distance_lookups[index] = if (tree.single_symbol) |symbol|
            try ExternalDistanceLookup.initSingle(symbol)
        else
            try ExternalDistanceLookup.init(&tree.table);
    }
    return true;
}

fn prepareCommand10AuxiliaryTailLookups(header: *MinimalCompressedHeader) bool {
    // Check every table before writing any tail so a failed wider attempt can
    // fall back to the existing atomic nine-bit preparation unchanged.
    if (header.command_block.block_type_count > inline_command_tree_count or
        header.distance_tree_count > inline_distance_tree_count) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup10()) return false;
    for (header.distance_trees[0..header.distance_tree_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup9()) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree| {
        if (tree.single_symbol == null) {
            const built = tree.table.buildTailLookup10();
            std.debug.assert(built);
            for (tree.table.tailLookup10Slots()) |*slot|
                slot.* = command_lut.fuseLookupSlot(slot.*);
        }
    }
    for (header.distance_trees[0..header.distance_tree_count]) |*tree|
        std.debug.assert(tree.single_symbol != null or tree.table.buildTailLookup9());
    return true;
}

fn prepareAuxiliaryTailLookups(header: *MinimalCompressedHeader) bool {
    if (header.command_block.block_type_count > inline_command_tree_count or
        header.distance_tree_count > inline_distance_tree_count) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup9()) return false;
    for (header.distance_trees[0..header.distance_tree_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup9()) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree|
        std.debug.assert(tree.single_symbol != null or tree.table.buildTailLookup9());
    for (header.distance_trees[0..header.distance_tree_count]) |*tree|
        std.debug.assert(tree.single_symbol != null or tree.table.buildTailLookup9());
    return true;
}

fn prepareExternalLiteralLookups(
    header: *const MinimalCompressedHeader,
    lookups: *[external_literal_lookup_tree_limit]ExternalLiteralLookup,
) Error!void {
    if (header.literal_tree_count > lookups.len) return error.UnsupportedBrotliFeature;
    for (header.literal_trees[0..header.literal_tree_count], 0..) |*tree, index| {
        lookups[index] = if (tree.single_symbol) |symbol|
            try ExternalLiteralLookup.initSingle(symbol)
        else
            try ExternalLiteralLookup.init(&tree.table);
    }
}

fn prepareWideExternalLiteralLookups(
    comptime capacity: usize,
    header: *const MinimalCompressedHeader,
    lookups: *[capacity]ExternalLiteralLookup,
) Error!void {
    if (header.literal_tree_count <= inline_literal_tree_count or header.literal_tree_count > lookups.len)
        return error.UnsupportedBrotliFeature;
    for (0..header.literal_tree_count) |index| {
        if (index < inline_literal_tree_count) {
            const tree = &header.literal_trees[index];
            lookups[index] = if (tree.single_symbol) |symbol|
                try ExternalLiteralLookup.initSingle(symbol)
            else
                try ExternalLiteralLookup.init(&tree.table);
            continue;
        }
        const packed_tree = &header.packed_literal_trees[index - inline_literal_tree_count];
        if (packed_tree.single_symbol_plus_one != 0) {
            lookups[index] = try ExternalLiteralLookup.initSingle(packed_tree.single_symbol_plus_one - 1);
            continue;
        }
        const tree = try packed_tree.expand();
        lookups[index] = try ExternalLiteralLookup.init(&tree.table);
    }
}

fn prepareWideExternalLiteralLookups9(
    comptime capacity: usize,
    header: *const MinimalCompressedHeader,
    lookups: *[capacity]WideExternalLiteralLookup9,
) Error!void {
    if (header.literal_tree_count <= inline_literal_tree_count or header.literal_tree_count > lookups.len)
        return error.UnsupportedBrotliFeature;
    for (0..header.literal_tree_count) |index| {
        if (index < inline_literal_tree_count) {
