    }
    if (auxiliary_tail_lookups)
        return processWideExternalLiteralLookup9CompressedPayload(true, wideAuxiliaryUsesFixedNineBitPeek(capacity), false, false, false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, header, literal_lookups[0..header.literal_tree_count], null, null);
    return processWideExternalLiteralLookup9CompressedPayload(false, false, false, false, false, &fast_reader, output, written, meta_block_end, last_distances, window_bits, header, literal_lookups[0..header.literal_tree_count], null, null);
}

fn wideAuxiliaryUsesFixedNineBitPeek(comptime capacity: usize) bool {
    comptime std.debug.assert(capacity == external_literal_lookup_middle_tree_limit or capacity == max_literal_context_trees);
    return true;
}

test "br both wide literal tiers use fixed nine-bit auxiliary peeks" {
    try std.testing.expect(wideAuxiliaryUsesFixedNineBitPeek(external_literal_lookup_middle_tree_limit));
    try std.testing.expect(wideAuxiliaryUsesFixedNineBitPeek(max_literal_context_trees));
}

fn prepareLargeLiteralTailLookups(header: *LargeWindowCompressedHeader) bool {
    if (header.literal_tree_count > inline_literal_tree_count) return false;
    for (header.literal_trees[0..header.literal_tree_count]) |*tree|
        if (!tree.canPrepareTailLookup()) return false;
    for (header.literal_trees[0..header.literal_tree_count]) |*tree|
        std.debug.assert(tree.prepareTailLookup());
    return true;
}

fn prepareLargeAuxiliaryTailLookups(header: *LargeWindowCompressedHeader) bool {
    if (header.command_block.block_type_count > inline_command_tree_count or
        header.distance_tree_count > inline_distance_tree_count) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup9()) return false;
    for (header.distance_trees[0..header.distance_tree_count]) |*tree|
        if (tree.single_symbol == null and !tree.table.canBuildTailLookup9()) return false;
    for (header.insert_copy_trees[0..header.command_block.block_type_count]) |*tree|
        std.debug.assert(tree.single_symbol != null or tree.table.buildTailLookup9());
    for (header.distance_trees[0..header.distance_tree_count]) |*tree|
        std.debug.assert(tree.single_symbol != null or tree.table.buildTailLookup9());
    return true;
}

fn allLiteralContextModesAreUtf8(modes: []const u2) bool {
    for (modes) |mode|
        if (mode != literal_context.mode_utf8) return false;
    return true;
}

fn allLiteralContextMapsAreIndependent(header: *const MinimalCompressedHeader) bool {
    for (0..header.literal_block.block_type_count) |block_type| {
        const map_start = block_type * 64;
        const tree_index = header.literal_context_map[map_start];
        for (header.literal_context_map[map_start..][1..64]) |candidate|
            if (candidate != tree_index) return false;
    }
    return true;
}

test "br all-UTF8 literal context classifier covers mixed modes" {
    try std.testing.expect(allLiteralContextModesAreUtf8(&.{literal_context.mode_utf8}));
    try std.testing.expect(allLiteralContextModesAreUtf8(&.{ literal_context.mode_utf8, literal_context.mode_utf8, literal_context.mode_utf8 }));
    try std.testing.expect(!allLiteralContextModesAreUtf8(&.{ 0, literal_context.mode_utf8 }));
    try std.testing.expect(!allLiteralContextModesAreUtf8(&.{ literal_context.mode_utf8, 1 }));
    try std.testing.expect(!allLiteralContextModesAreUtf8(&.{ literal_context.mode_utf8, 3 }));
}

test "br context-independent literal maps require a uniform tree per block type" {
    var header: MinimalCompressedHeader = undefined;
    header.literal_block = .{ .block_type_count = 2 };
    header.literal_tree_count = 2;
    @memset(header.literal_context_map[0..64], 0);
    @memset(header.literal_context_map[64..128], 1);
    try std.testing.expect(allLiteralContextMapsAreIndependent(&header));
    header.literal_context_map[95] = 0;
    try std.testing.expect(!allLiteralContextMapsAreIndependent(&header));
}

noinline fn processDecodedCompressedPayload(
    reader: *bitstream.BitReader,
    output: []u8,
    written: *usize,
    meta_block_end: usize,
    last_distances: *[4]usize,
    window_bits: u5,
    header: *MinimalCompressedHeader,
) Error!void {
    var transformed_dictionary_word: [64]u8 = undefined;
    while (written.* < meta_block_end) {
        const command_symbol = try readCommandSymbol(header, reader);
        const lengths = try readInsertCopyLengths(command_symbol, reader);
        if (lengths.insert_len > meta_block_end - written.*) return error.CorruptFrame;
        var i: usize = 0;
        while (i < lengths.insert_len) : (i += 1) {
            try ensureLiteralBlock(header, reader);
            const context = try literalContext(header, output, written.*);
            const tree_index = header.literal_context_map[@as(usize, header.literal_block.current_type) * 64 + context];
            if (tree_index >= max_literal_context_trees) return error.UnsupportedBrotliFeature;
            const tree = try literalPrefixForDecode(header, tree_index);
            const literal = try tree.decode(reader);
            if (literal > 0xff) return error.InvalidHuffmanCode;
            output[written.*] = @intCast(literal);
            written.* += 1;
            if (header.literal_block.remaining != 0) header.literal_block.remaining -= 1;
        }
        if (written.* == meta_block_end) return;
        const decoded_distance = try readMinimalDistance(header, reader, lengths, last_distances);
        const distance = decoded_distance.distance;
        if (distance == 0) return error.InvalidMatch;
        const max_distance = maxBackwardDistanceForWindow(window_bits, written.*);
        if (distance > max_distance) {
            const word = try minimalStaticDictionaryWord(distance, lengths.copy_len, max_distance, &transformed_dictionary_word);
            if (word.len > meta_block_end - written.*) return error.CorruptFrame;
            @memcpy(output[written.*..][0..word.len], word);
            written.* += word.len;
            continue;
        }
        if (decoded_distance.update_ring) pushLastDistance(last_distances, distance);
        if (lengths.copy_len > meta_block_end - written.*) return error.CorruptFrame;
        match_copy.append(output, written, distance, lengths.copy_len, meta_block_end);
    }
}

