    }
    const lengths = [_]usize{ 0, 1, 2, 7, 8, 255, 256, 257, 4095, 4096, 8191, 8192, direct_stored_stream_max_input_len - 1, direct_stored_stream_max_input_len, direct_stored_stream_max_input_len + 1 };
