    inline for (.{ 5, 6, 23, 71, 327, 1095, 1096, 2119, 2120, 2121, 65_535, 65_536, 65_537, 1_048_575, 1_048_576, 1_048_577, max_uncompressed_meta_block_len }) |len| {
