    defer std.testing.allocator.free(decoded);
    try std.testing.expectEqualSlices(u8, &payload, decoded);
}

const three_command_region_count = 6144;
const three_command_region_block_count = three_command_region_count / 3;
const three_command_region_payload_len = three_command_region_block_count * (3 + 5 + 7);

fn fillThreeCommandRegionFixture(payload: []u8, commands: []command_plan.Command) void {
    std.debug.assert(payload.len == three_command_region_payload_len);
    std.debug.assert(commands.len == three_command_region_count);
    var position: usize = 0;
    for (commands, 0..) |*command, i| {
        const block_index = i / three_command_region_block_count;
        const insert_len: usize = block_index + 1;
        const copy_len: usize = block_index + 2;
        const byte: u8 = @intCast(block_index * 112 + (i & 15));
        @memset(payload[position..][0 .. insert_len + copy_len], byte);
        command.* = .{
            .insert_start = position,
            .insert_len = insert_len,
            .copy_len = copy_len,
            .distance = 1,
            .has_copy = true,
        };
        position += insert_len + copy_len;
    }
    std.debug.assert(payload.len == position);
}

const clustered_command_count = 6144;
const clustered_command_region_count = clustered_command_count / 3;
const clustered_outer_insert_lens = [8]usize{ 1, 2, 3, 4, 5, 6, 8, 10 };
const clustered_middle_insert_lens = [8]usize{ 34, 50, 66, 98, 130, 194, 322, 578 };
const clustered_outer_cycle_len = blk: {
    var total: usize = 0;
    for (clustered_outer_insert_lens) |len| total += len + 2;
    break :blk total;
};
const clustered_middle_cycle_len = blk: {
    var total: usize = 0;
    for (clustered_middle_insert_lens) |len| total += len + 40;
    break :blk total;
};
const clustered_command_payload_len = clustered_command_region_count / 8 * (2 * clustered_outer_cycle_len + clustered_middle_cycle_len);

fn fillClusteredCommandFixture(payload: []u8, commands: []command_plan.Command) void {
    std.debug.assert(payload.len == clustered_command_payload_len);
    std.debug.assert(commands.len == clustered_command_count);
    var position: usize = 0;
    for (commands, 0..) |*command, i| {
        const middle = i >= clustered_command_region_count and i < 2 * clustered_command_region_count;
        const insert_len = if (middle) clustered_middle_insert_lens[i & 7] else clustered_outer_insert_lens[i & 7];
        const copy_len: usize = if (middle) 40 else 2;
        const byte: u8 = if (middle) @intCast(240 + (i & 15)) else @intCast(i & 15);
        @memset(payload[position..][0 .. insert_len + copy_len], byte);
        command.* = .{ .insert_start = position, .insert_len = insert_len, .copy_len = copy_len, .distance = 1, .has_copy = true };
        position += insert_len + copy_len;
    }
    std.debug.assert(position == payload.len);
}

const alternating_command_count = 8192;
const alternating_command_first_split = alternating_command_count / 6;
const alternating_command_second_split = alternating_command_count * 2 / 6;
const alternating_command_third_split = alternating_command_count * 3 / 6;
const alternating_command_payload_len = 1_242_295;

fn fillAlternatingCommandFixture(payload: []u8, commands: []command_plan.Command) void {
    std.debug.assert(payload.len == alternating_command_payload_len);
    std.debug.assert(commands.len == alternating_command_count);
    var position: usize = 0;
    for (commands, 0..) |*command, i| {
        const region: usize = if (i < alternating_command_first_split) 0 else if (i < alternating_command_second_split) 1 else if (i < alternating_command_third_split) 2 else 3;
        const insert_len = if (region & 1 == 0) clustered_outer_insert_lens[i & 7] else clustered_middle_insert_lens[i & 7];
        const copy_len: usize = if (region & 1 == 0) 2 else 40;
        const byte: u8 = if (region & 1 == 0) @intCast(i & 15) else @intCast(240 + (i & 15));
        @memset(payload[position..][0 .. insert_len + copy_len], byte);
        command.* = .{ .insert_start = position, .insert_len = insert_len, .copy_len = copy_len, .distance = 1, .has_copy = true };
        position += insert_len + copy_len;
    }
    std.debug.assert(position == payload.len);
}

const reuse_first_four_command_count = 8192;
const reuse_first_four_first_split = reuse_first_four_command_count / 6;
const reuse_first_four_second_split = reuse_first_four_command_count * 2 / 6;
const reuse_first_four_third_split = reuse_first_four_command_count * 3 / 6;
const reuse_first_four_insert_lens = [3][8]usize{
    clustered_outer_insert_lens,
    .{ 34, 50, 66, 98, 130, 194, 322, 578 },
    .{ 18, 20, 22, 24, 26, 28, 30, 32 },
};
const reuse_first_four_copy_lens = [3]usize{ 2, 40, 6 };
const reuse_first_four_payload_len = 385_911;

fn fillReuseFirstFourFixture(payload: []u8, commands: []command_plan.Command) void {
    std.debug.assert(payload.len == reuse_first_four_payload_len);
    std.debug.assert(commands.len == reuse_first_four_command_count);
    var position: usize = 0;
    for (commands, 0..) |*command, i| {
        const region: usize = if (i < reuse_first_four_first_split) 0 else if (i < reuse_first_four_second_split) 1 else if (i < reuse_first_four_third_split) 2 else 3;
        const tree_index = if (region == 3) 0 else region;
        const insert_len = reuse_first_four_insert_lens[tree_index][i & 7];
        const copy_len = reuse_first_four_copy_lens[tree_index];
        const byte: u8 = @intCast(tree_index * 112 + (i & 15));
        @memset(payload[position..][0 .. insert_len + copy_len], byte);
        command.* = .{ .insert_start = position, .insert_len = insert_len, .copy_len = copy_len, .distance = 1, .has_copy = true };
        position += insert_len + copy_len;
    }
    std.debug.assert(position == payload.len);
}

fn encodeSelectedCommandSplitFixtureAlloc(allocator: std.mem.Allocator, payload: []const u8, commands: []const command_plan.Command) Error![]u8 {
    var stats: encoder_stats.PlannedEncodeStats = .{};
    const baseline = try encodeCommandPlanWithOptionsAlloc(allocator, payload, commands, null, &stats, .{});
    errdefer allocator.free(baseline);
    const selected = try encodeEntropySplitCandidateAlloc(allocator, payload, commands, &stats, .{ .try_command_split = true }, .{ .encoded = baseline, .use_recent_distances = false });
    if (selected) |encoded| {
        allocator.free(baseline);
        return encoded;
    }
    return baseline;
}

test "br planned wire combines literal command and distance entropy splits" {
    const payload = try std.testing.allocator.alloc(u8, three_command_region_payload_len);
    defer std.testing.allocator.free(payload);
    const commands = try std.testing.allocator.alloc(command_plan.Command, three_command_region_count);
    defer std.testing.allocator.free(commands);
    fillThreeCommandRegionFixture(payload, commands);
    var stats: encoder_stats.PlannedEncodeStats = .{};
    const two_command_blocks = try encodeCommandPlanWithOptionsAlloc(std.testing.allocator, payload, commands, null, &stats, .{
        .literal_split = three_command_region_block_count,
        .command_split = .{ .split = three_command_region_block_count, .savings_bits = 0 },
        .distance_split = three_command_region_count / 2,
    });
    defer std.testing.allocator.free(two_command_blocks);
    const encoded = try encodeCommandPlanWithOptionsAlloc(std.testing.allocator, payload, commands, null, &stats, .{
        .literal_split = three_command_region_block_count,
        .command_split = .{ .split = three_command_region_block_count, .second_split = 2 * three_command_region_block_count, .savings_bits = 0 },
        .distance_split = three_command_region_count / 2,
