test "br minimal static dictionary upstream8192 identity second window decodes Node frames" {
    // Second source-limit 8192 probe window. As in the first window, Node often
    // encodes transform-equivalent payloads through concrete identity source
    // addresses; this batch pins the observed failing frames from the original window and its reindexed tail.
    const cases = [_]struct {
        encoded: []const u8,
        expected: []const u8,
    }{
        .{ .encoded = &[_]u8{ 0xa1, 0x30, 0x00, 0x00, 0x20, 0x01, 0x10, 0x85, 0xc4, 0x06, 0x01 }, .expected = "setting" },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x52, 0x85, 0x28, 0x12, 0x1b, 0x28 }, .expected = "setting " },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x12, 0x8d, 0xc4, 0x16, 0x01 }, .expected = " setting" },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0xe1, 0x52, 0x85, 0x28, 0x12, 0x1b, 0x28 }, .expected = "setting." },
        .{ .encoded = &[_]u8{ 0xa1, 0x30, 0x00, 0x00, 0x20, 0x01, 0x10, 0x85, 0xc4, 0x16, 0x01 }, .expected = "disease" },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x52, 0x85, 0x28, 0x12, 0x9b, 0x28 }, .expected = "disease " },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x12, 0x8d, 0xc4, 0x26, 0x01 }, .expected = " disease" },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0xe1, 0x52, 0x85, 0x28, 0x12, 0x9b, 0x28 }, .expected = "disease." },
