test "br minimal static dictionary upstream8192 identity twelfth window decodes Node frames" {
    // Twelfth source-limit 8192 probe window. The cases are the unique failing
    // frames from the initial and reindexed probes; shared frames are pinned once.
    const cases = [_]struct {
        encoded: []const u8,
        expected: []const u8,
    }{
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x10, 0x86, 0x84, 0x14 }, .expected = "standard" },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0x01, 0x52, 0x86, 0x28, 0x12, 0x92, 0x02 }, .expected = "standard " },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0x01, 0x12, 0x8e, 0x84, 0x24 }, .expected = " standard" },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0xe1, 0x52, 0x86, 0x28, 0x12, 0x92, 0x02 }, .expected = "standard." },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x10, 0x86, 0x84, 0x24 }, .expected = "campaign" },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0x01, 0x52, 0x86, 0x28, 0x12, 0x12, 0x03 }, .expected = "campaign " },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0x01, 0x12, 0x8e, 0x84, 0x34 }, .expected = " campaign" },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0xe1, 0x52, 0x86, 0x28, 0x12, 0x12, 0x03 }, .expected = "campaign." },
        .{ .encoded = &[_]u8{ 0xa1, 0x38, 0x00, 0x00, 0x20, 0x01, 0x10, 0x86, 0x84, 0x34 }, .expected = "features" },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0x01, 0x52, 0x86, 0x28, 0x12, 0x92, 0x03 }, .expected = "features " },
        .{ .encoded = &[_]u8{ 0xa1, 0x40, 0x00, 0x00, 0x20, 0x01, 0x12, 0x8e, 0xc4, 0x04 }, .expected = " features" },
