test "br insert-copy length decoder covers basic and extra-bit ranges" {
    var empty_reader = bitstream.BitReader.init(&.{});
    const zero = try readInsertCopyLengths(0, &empty_reader);
    try std.testing.expectEqual(@as(usize, 0), zero.insert_len);
    try std.testing.expectEqual(@as(usize, 2), zero.copy_len);
    try std.testing.expect(zero.distance_symbol_zero);

    var insert_extra_reader = bitstream.BitReader.init(&.{0b0000_0001});
    const insert_extra = try readInsertCopyLengths(6 << 3, &insert_extra_reader);
    try std.testing.expectEqual(@as(usize, 7), insert_extra.insert_len);
    try std.testing.expectEqual(@as(usize, 2), insert_extra.copy_len);
    try std.testing.expect(insert_extra.distance_symbol_zero);

    var copy_extra_reader = bitstream.BitReader.init(&.{0b0000_0001});
    const copy_extra = try readInsertCopyLengths(64 + 0, &copy_extra_reader);
    try std.testing.expectEqual(@as(usize, 0), copy_extra.insert_len);
    try std.testing.expectEqual(@as(usize, 11), copy_extra.copy_len);
    try std.testing.expect(copy_extra.distance_symbol_zero);

    var explicit_distance_reader = bitstream.BitReader.init(&.{0});
    const explicit_distance = try readInsertCopyLengths(128, &explicit_distance_reader);
    try std.testing.expectEqual(@as(usize, 0), explicit_distance.insert_len);
    try std.testing.expectEqual(@as(usize, 2), explicit_distance.copy_len);
    try std.testing.expect(!explicit_distance.distance_symbol_zero);
}

test "br multi-tree zero-insert lookup preserves command progress" {
    const symbol: u16 = 64;
    const tree = PrefixCode(704){ .single_symbol = symbol };
    const lookup = try single_command_lookup.Lookup.initSingle(symbol);
    var header: MinimalCompressedHeader = undefined;
    header.command_block = .{};
    header.command_block.remaining = 1;
    var reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{0b0000_0001}));
    const lengths = try readInsertCopyLengthsMultiTreeZeroInsertCurrent(
        &header,
        &reader,
        &lookup,
        &tree,
    );
    try std.testing.expectEqual(@as(usize, 0), lengths.insert_len);
    try std.testing.expectEqual(@as(usize, 11), lengths.copy_len);
    try std.testing.expect(lengths.distance_symbol_zero);
    try std.testing.expectEqual(@as(usize, 0), header.command_block.remaining);

    const nonzero = commandEntryForLengths(1, 2).?;
    const nonzero_tree = PrefixCode(704){ .single_symbol = nonzero.symbol };
    const nonzero_lookup = try single_command_lookup.Lookup.initSingle(nonzero.symbol);
    header.command_block.remaining = 1;
    var nonzero_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
    const nonzero_lengths = try readInsertCopyLengthsMultiTreeZeroInsertCurrent(
        &header,
        &nonzero_reader,
        &nonzero_lookup,
        &nonzero_tree,
    );
    try std.testing.expectEqual(@as(usize, 1), nonzero_lengths.insert_len);
    try std.testing.expectEqual(@as(usize, 2), nonzero_lengths.copy_len);
    try std.testing.expect(!nonzero_lengths.distance_symbol_zero);
    try std.testing.expectEqual(@as(usize, 0), header.command_block.remaining);
}

test "br insert-copy length decoder handles high range extra bits" {
    var encoded: std.ArrayList(u8) = .empty;
    defer encoded.deinit(std.testing.allocator);
    var writer = BitWriter{ .out = &encoded };
    try writer.writeBits(std.testing.allocator, 3, 10); // insert code 20 extra => 1093.
    try writer.writeBits(std.testing.allocator, 17, 10); // copy code 22 extra => 1111.

    var reader = bitstream.BitReader.init(encoded.items);
    const lengths = try readInsertCopyLengths(640 + (4 << 3) + 6, &reader);
    try std.testing.expectEqual(@as(usize, 1093), lengths.insert_len);
    try std.testing.expectEqual(@as(usize, 1111), lengths.copy_len);
    try std.testing.expect(!lengths.distance_symbol_zero);

    var staged_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(encoded.items));
    const staged = try readInsertCopyLengthsStaged(640 + (4 << 3) + 6, &staged_reader);
    try std.testing.expectEqual(lengths, staged);
    try std.testing.expectEqual(reader.bitPosition(), staged_reader.bitPosition());

    var compact_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(encoded.items));
    const compact = try readInsertCopyLengthsStagedCompact(640 + (4 << 3) + 6, &compact_reader);
    try std.testing.expectEqual(lengths, compact);
    try std.testing.expectEqual(reader.bitPosition(), compact_reader.bitPosition());

    var invalid_reader = bitstream.BitReader.init(&.{});
    try std.testing.expectError(error.InvalidHuffmanCode, readInsertCopyLengths(704, &invalid_reader));
    var invalid_compact_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
    try std.testing.expectError(error.InvalidHuffmanCode, readInsertCopyLengthsStagedCompact(704, &invalid_compact_reader));
}

test "br short distance resolver covers RFC table" {
    const last_distances = [_]usize{ 16, 15, 11, 4 };
    const expected = [_]usize{ 4, 11, 15, 16, 3, 5, 2, 6, 1, 7, 10, 12, 9, 13, 8, 14 };
    for (expected, 0..) |distance, symbol| {
        try std.testing.expectEqual(distance, try resolveShortDistance(@intCast(symbol), &last_distances));
    }

    const small_last = [_]usize{ 16, 15, 2, 1 };
    try std.testing.expectError(error.InvalidMatch, resolveShortDistance(4, &small_last));
    try std.testing.expectError(error.InvalidMatch, resolveShortDistance(12, &small_last));
    try std.testing.expectError(error.InvalidHuffmanCode, resolveShortDistance(16, &small_last));
}

test "br tail distance decoder writes implicit short and regular results" {
    var last_distances = [_]usize{ 16, 15, 11, 4 };
    var header: MinimalCompressedHeader = undefined;
    header.npostfix = 0;
    header.ndirect = 0;
    prepareDistanceLookup(&header, 16 + 48);
    header.distance_block = .{};
    header.distance_context_map[2] = 0;
    var decoded: DecodedBrotliDistance = undefined;

    var implicit_reader = bitstream.BitReader.init(&.{});
    try readMinimalDistanceTailLookupInto(
        &header,
        &implicit_reader,
        .{ .insert_len = 0, .copy_len = 4, .distance_symbol_zero = true },
        &last_distances,
        &decoded,
    );
    try std.testing.expectEqual(@as(usize, 4), decoded.distance);
    try std.testing.expect(!decoded.update_ring);
    try std.testing.expectEqual(@as(usize, 0), implicit_reader.bitPosition());

    header.distance_trees[0] = .{ .single_symbol = 5 };
    var short_reader = bitstream.BitReader.init(&.{});
    try readMinimalDistanceTailLookupInto(
        &header,
        &short_reader,
        .{ .insert_len = 0, .copy_len = 4, .distance_symbol_zero = false },
        &last_distances,
        &decoded,
    );
    try std.testing.expectEqual(try resolveShortDistance(5, &last_distances), decoded.distance);
    try std.testing.expect(decoded.update_ring);
    try std.testing.expectEqual(@as(usize, 0), short_reader.bitPosition());

    header.distance_trees[0] = .{ .single_symbol = 20 };
    var regular_reader = bitstream.BitReader.init(&.{0b0000_0011});
    try readMinimalDistanceTailLookupInto(
        &header,
        &regular_reader,
        .{ .insert_len = 0, .copy_len = 4, .distance_symbol_zero = false },
        &last_distances,
        &decoded,
    );
    try std.testing.expectEqual(try resolveRegularDistance(0, 0, 20, 3), decoded.distance);
    try std.testing.expect(decoded.update_ring);
    try std.testing.expectEqual(@as(usize, 3), regular_reader.bitPosition());

    var staged_last_distances = [_]usize{ 16, 15, 11, 4 };
    var staged_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{0b0000_0011}));
    var staged_decoded: DecodedBrotliDistance = undefined;
    try readMinimalDistanceTailLookupIntoFixed9(
        &header,
        &staged_reader,
        .{ .insert_len = 0, .copy_len = 4, .distance_symbol_zero = false },
        &staged_last_distances,
        &staged_decoded,
    );
    try std.testing.expectEqual(decoded, staged_decoded);
    try std.testing.expectEqual(regular_reader.bitPosition(), staged_reader.bitPosition());
}

