    lookups[0] = try ExternalDistanceLookup.initSingle(5);
    lookups[1] = try ExternalDistanceLookup.initSingle(1);
    const context_map = [4]u8{ 0, 0, 0, 0 };
    inline for (.{ false, true }) |direct_context_three| {
        header.distance_block.remaining = 2;
        var last_distances = initial_last_distances;
        var decoded: DecodedBrotliDistance = undefined;

        var context_three_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
        try readMinimalDistanceExternalLookupIntoFixed9Current(
            true,
            direct_context_three,
            false,
            &header,
            &context_three_reader,
            .{ .insert_len = 0, .copy_len = 5, .distance_symbol_zero = false },
            &last_distances,
            &decoded,
            &lookups,
            &context_map,
            1,
        );
        try std.testing.expectEqual(@as(usize, 11), decoded.distance);

        var alternate_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
        try readMinimalDistanceExternalLookupIntoFixed9Current(
            true,
            direct_context_three,
            false,
            &header,
            &alternate_reader,
            .{ .insert_len = 0, .copy_len = 4, .distance_symbol_zero = false },
            &last_distances,
            &decoded,
            &lookups,
            &context_map,
            1,
        );
        try std.testing.expectEqual(@as(usize, 5), decoded.distance);
        try std.testing.expectEqual(@as(usize, 0), header.distance_block.remaining);
    }
}

test "br direct cached distance context matches canonical contexts" {
    var header: MinimalCompressedHeader = undefined;
    header.npostfix = 0;
    header.ndirect = 0;
    prepareDistanceLookup(&header, 16 + 48);
    header.distance_tree_count = 4;
    header.distance_block = .{ .block_type_count = 1, .remaining = 1 };

    var lookups: [inline_distance_tree_count]ExternalDistanceLookup = undefined;
    for (0..4) |index| {
        const symbol: u16 = @intCast(4 + index);
        header.distance_trees[index] = .{ .single_symbol = symbol };
        lookups[index] = try ExternalDistanceLookup.initSingle(symbol);
    }
    const context_map = [4]u8{ 0, 1, 2, 3 };

    for (2..10) |copy_len| {
        var canonical_last_distances = initial_last_distances;
        var canonical: DecodedBrotliDistance = undefined;
        var canonical_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
        header.distance_block.remaining = 1;
        try readMinimalDistanceExternalLookupIntoFixed9Current(
            true,
            false,
            false,
            &header,
            &canonical_reader,
            .{ .insert_len = 0, .copy_len = copy_len, .distance_symbol_zero = false },
            &canonical_last_distances,
            &canonical,
            &lookups,
            &context_map,
            3,
        );

        var direct_last_distances = initial_last_distances;
        var direct: DecodedBrotliDistance = undefined;
        var direct_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
        header.distance_block.remaining = 1;
        try readMinimalDistanceExternalLookupIntoFixed9Current(
            true,
            true,
            false,
            &header,
            &direct_reader,
            .{ .insert_len = 0, .copy_len = copy_len, .distance_symbol_zero = false },
            &direct_last_distances,
            &direct,
            &lookups,
            &context_map,
            3,
        );

        try std.testing.expectEqual(canonical, direct);
        try std.testing.expectEqual(canonical_last_distances, direct_last_distances);
        try std.testing.expectEqual(canonical_reader.bitPosition(), direct_reader.bitPosition());
        try std.testing.expectEqual(@as(usize, 0), header.distance_block.remaining);

        var committed_last_distances = initial_last_distances;
        var committed_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
        header.distance_block.remaining = 1;
        const committed_distance = try readSelectedFullDistanceCommitted(
            &header,
            &committed_reader,
            .{ .insert_len = 0, .copy_len = copy_len, .distance_symbol_zero = false },
            &committed_last_distances,
            std.math.maxInt(usize),
            &lookups,
            &context_map,
            3,
        );
        var expected_last_distances = canonical_last_distances;
        if (canonical.update_ring) pushLastDistance(&expected_last_distances, canonical.distance);
        try std.testing.expectEqual(canonical.distance, committed_distance);
        try std.testing.expectEqual(expected_last_distances, committed_last_distances);
        try std.testing.expectEqual(canonical_reader.bitPosition(), committed_reader.bitPosition());
        try std.testing.expectEqual(@as(usize, 0), header.distance_block.remaining);

        var dictionary_last_distances = initial_last_distances;
        var dictionary_reader = fast_bit_reader.Reader.initFrom(bitstream.BitReader.init(&.{}));
        header.distance_block.remaining = 1;
        _ = try readSelectedFullDistanceCommitted(
            &header,
            &dictionary_reader,
            .{ .insert_len = 0, .copy_len = copy_len, .distance_symbol_zero = false },
            &dictionary_last_distances,
            0,
            &lookups,
            &context_map,
            3,
        );
        try std.testing.expectEqual(initial_last_distances, dictionary_last_distances);
    }
}

test "br regular distance resolver covers postfix and extra bits" {
    try std.testing.expectEqual(@as(usize, 2), try resolveRegularDistance(1, 0, 17, 0));
    try std.testing.expectEqual(@as(usize, 3), try resolveRegularDistance(0, 1, 17, 1));
    try std.testing.expectEqual(@as(usize, 18), try resolveRegularDistance(2, 4, 25, 1));
    try std.testing.expectError(error.InvalidHuffmanCode, resolveRegularDistance(0, 4, 19, 0));
}

test "br prepared distance lookup matches RFC resolver" {
    var header: MinimalCompressedHeader = undefined;
    for (0..4) |npostfix_value| {
        header.npostfix = @intCast(npostfix_value);
        for (0..16) |ndirect_high| {
            header.ndirect = @intCast(ndirect_high << @intCast(header.npostfix));
            const alphabet_size = 16 + @as(usize, header.ndirect) + (@as(usize, 48) << header.npostfix);
            prepareDistanceLookup(&header, alphabet_size);
            for (16..alphabet_size) |symbol| {
                const extra_bits = header.distance_extra_bits[symbol];
                const max_extra = (@as(usize, 1) << extra_bits) - 1;
                const prepared = @as(usize, header.distance_offsets[symbol]) + (max_extra << header.npostfix);
                const expected = if (symbol < 16 + @as(usize, header.ndirect))
                    symbol - 15
                else
                    try resolveRegularDistance(header.npostfix, header.ndirect, @intCast(symbol), max_extra);
                try std.testing.expectEqual(expected, prepared);
                try std.testing.expect(prepared != 0);
            }
        }
    }
}

test "br prepared distance readers match RFC values and every truncated suffix" {
    var header: MinimalCompressedHeader = undefined;
    for (0..4) |npostfix| {
        header.npostfix = @intCast(npostfix);
        for (0..16) |ndirect_high| {
            header.ndirect = @intCast(ndirect_high << @intCast(npostfix));
            const regular_start = 16 + @as(usize, header.ndirect);
            const alphabet_size = regular_start + (@as(usize, 48) << header.npostfix);
            prepareDistanceLookup(&header, alphabet_size);
            for (16..alphabet_size) |symbol_value| {
                const symbol: u16 = @intCast(symbol_value);
                const extra_bits: u5 = if (symbol_value < regular_start) 0 else @intCast(1 + ((symbol_value - regular_start) >> @intCast(npostfix + 1)));
                const max_extra = (@as(u32, 1) << extra_bits) - 1;
                for ([_]u32{ 0, max_extra }) |extra| {
                    var input: [4]u8 = undefined;
                    std.mem.writeInt(u32, &input, extra, .little);
                    var scalar = bitstream.BitReader.initBitLength(&input, extra_bits);
                    var staged = fast_bit_reader.Reader.initFrom(scalar);
                    const expected = if (symbol_value < regular_start) symbol_value - 15 else try resolveRegularDistance(header.npostfix, header.ndirect, symbol, extra);
                    try std.testing.expectEqual(expected, try readPreparedDistance(&header, &scalar, symbol));
                    try std.testing.expectEqual(expected, try readPreparedDistanceStaged(&header, &staged, symbol));
                    try std.testing.expectEqual(@as(usize, extra_bits), scalar.bitPosition());
                    try std.testing.expectEqual(scalar.bitPosition(), staged.bitPosition());
                    if (header.npostfix == 0 and header.ndirect == 0) {
                        var zero_postfix_staged = fast_bit_reader.Reader.initFrom(bitstream.BitReader.initBitLength(&input, extra_bits));
                        try std.testing.expectEqual(
                            expected,
                            try readPreparedDistanceStagedWithOptions(true, &header, &zero_postfix_staged, symbol),
                        );
                        try std.testing.expectEqual(scalar.bitPosition(), zero_postfix_staged.bitPosition());
                    }
                    for (0..extra_bits) |available_bits| {
                        var short_scalar = bitstream.BitReader.initBitLength(&input, available_bits);
                        var short_staged = fast_bit_reader.Reader.initFrom(short_scalar);
                        try std.testing.expectError(error.TruncatedFrame, readPreparedDistance(&header, &short_scalar, symbol));
                        try std.testing.expectError(error.TruncatedFrame, readPreparedDistanceStaged(&header, &short_staged, symbol));
                        if (header.npostfix == 0 and header.ndirect == 0) {
                            var zero_postfix_short = fast_bit_reader.Reader.initFrom(short_scalar);
                            try std.testing.expectError(
                                error.TruncatedFrame,
                                readPreparedDistanceStagedWithOptions(true, &header, &zero_postfix_short, symbol),
                            );
                        }
                        try std.testing.expectEqual(@as(usize, 0), short_scalar.bitPosition());
                        try std.testing.expectEqual(short_scalar.bitPosition(), short_staged.bitPosition());
                    }
                }
            }
        }
    }
    var empty_scalar = bitstream.BitReader.init(&.{});
    var empty_staged = fast_bit_reader.Reader.initFrom(empty_scalar);
    try std.testing.expectError(error.InvalidHuffmanCode, readPreparedDistance(&header, &empty_scalar, max_distance_alphabet_size));
    try std.testing.expectError(error.InvalidHuffmanCode, readPreparedDistanceStaged(&header, &empty_staged, max_distance_alphabet_size));
}

test "br regular distance resolver remains bounded at RFC maxima" {
    const max_symbol: u16 = max_distance_alphabet_size - 1;
    const xcode = @as(usize, max_symbol) - 120 - 16;
    const extra_bits = 1 + (xcode >> 4);
    const extra = (@as(usize, 1) << @intCast(extra_bits)) - 1;
    const distance = try resolveRegularDistance(3, 120, max_symbol, extra);
    try std.testing.expect(distance < (@as(usize, 1) << 30));
    try std.testing.expectError(error.CorruptFrame, resolveRegularDistance(3, 120, max_symbol, extra + 1));
}

test "br large window distance alphabet matches upstream safe limits" {
    try std.testing.expectEqual(@as(usize, 1128), large_wire_max_distance_alphabet_size);
    try std.testing.expectEqual(@as(usize, 88), largeWindowDistanceAlphabetLimit(0, 15));
    try std.testing.expectEqual(@as(usize, 156), largeWindowDistanceAlphabetLimit(1, 30));
    try std.testing.expectEqual(@as(usize, 288), largeWindowDistanceAlphabetLimit(2, 60));
    try std.testing.expectEqual(@as(usize, 544), largeWindowDistanceAlphabetLimit(3, 120));

    const max_symbol: u16 = @intCast(largeWindowDistanceAlphabetLimit(3, 120) - 1);
    const xcode = @as(usize, max_symbol) - 120 - 16;
    const extra_bits = 1 + (xcode >> 4);
    const extra = (@as(usize, 1) << @intCast(extra_bits)) - 1;
    const distance = try resolveLargeWindowRegularDistanceParts(3, 120, xcode, extra_bits, extra);
    try std.testing.expect(distance <= max_allowed_large_window_distance);

    const first_rejected_symbol: u16 = max_symbol + 1;
    const rejected_xcode = @as(usize, first_rejected_symbol) - 120 - 16;
    const rejected_extra_bits = 1 + (rejected_xcode >> 4);
    const rejected_extra = (@as(usize, 1) << @intCast(rejected_extra_bits)) - 1;
    try std.testing.expectError(
        error.CorruptFrame,
        resolveLargeWindowRegularDistanceParts(3, 120, rejected_xcode, rejected_extra_bits, rejected_extra),
    );
}

