fn writeCodeLengthCodeLength(allocator: std.mem.Allocator, writer: *BitWriter, length: u4) Error!void {
    switch (length) {
        0 => try writer.writeBits(allocator, 0b00, 2),
        1 => try writer.writeBits(allocator, 0b0111, 4),
        2 => try writer.writeBits(allocator, 0b011, 3),
        3 => try writer.writeBits(allocator, 0b10, 2),
        4 => try writer.writeBits(allocator, 0b01, 2),
        5 => try writer.writeBits(allocator, 0b1111, 4),
        else => return error.InvalidHuffmanCode,
    }
}

fn writeMinimalCompressedHeaderForHello(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 0, 4); // NDIRECT
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 3, 2); // NSYM = 4
    try writer.writeBits(allocator, 'h', alphabetBits(256));
    try writer.writeBits(allocator, 'e', alphabetBits(256));
    try writer.writeBits(allocator, 'l', alphabetBits(256));
    try writer.writeBits(allocator, 'o', alphabetBits(256));
    try writer.writeBits(allocator, 0, 1); // tree-select

    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 40);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 64, 0);
}

fn writeMinimalCompressedHeaderForSingleLiteral(allocator: std.mem.Allocator, writer: *BitWriter, literal: u8) Error!void {
    try writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 1);
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 0, 4); // NDIRECT
    try writer.writeBits(allocator, 0, 2); // LSB6 literal context
    try writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 1);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 256, literal);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 8);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 64, 0);
}

fn writeMinimalCompressedHeaderForHelloWithContextMaps(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 0, 4); // NDIRECT
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 2); // NTREESL
    try writeZeroContextMapRle(allocator, writer, 64, 2, 6);
    try writeBlockTypeCount(allocator, writer, 2); // NTREESD
    try writeZeroContextMapRle(allocator, writer, 4, 2, 2);

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 3, 2); // NSYM = 4
    try writer.writeBits(allocator, 'h', alphabetBits(256));
    try writer.writeBits(allocator, 'e', alphabetBits(256));
    try writer.writeBits(allocator, 'l', alphabetBits(256));
    try writer.writeBits(allocator, 'o', alphabetBits(256));
    try writer.writeBits(allocator, 0, 1); // tree-select
    try writeSimpleSingleSymbolPrefix(allocator, writer, 256, 0); // unused literal tree

    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 40);

    try writeSimpleSingleSymbolPrefix(allocator, writer, 64, 0);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 64, 0); // unused distance tree
}

fn writeMinimalCompressedHeaderForCopy(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 1, 4); // NDIRECT = 1
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD
    try writeSimpleSingleSymbolPrefix(allocator, writer, 256, 'a');
    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 138);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 65, 16);
}

fn writeMinimalCompressedHeaderForLastDistance(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 1, 4); // NDIRECT = 1
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD
    try writeSimpleSingleSymbolPrefix(allocator, writer, 256, 'a');

    try writer.writeBits(allocator, 1, 2); // simple insert-copy prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 136, alphabetBits(704));
    try writer.writeBits(allocator, 0, alphabetBits(704));

    try writeSimpleSingleSymbolPrefix(allocator, writer, 65, 16);
}

fn writeMinimalCompressedHeaderForShortDistance(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 1, 4); // NDIRECT = 1
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD
    try writeSimpleSingleSymbolPrefix(allocator, writer, 256, 'a');

    try writer.writeBits(allocator, 1, 2); // simple insert-copy prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 136, alphabetBits(704));
    try writer.writeBits(allocator, 128, alphabetBits(704));

    try writer.writeBits(allocator, 1, 2); // simple distance prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 16, alphabetBits(65));
    try writer.writeBits(allocator, 5, alphabetBits(65));
}

fn writeMinimalCompressedHeaderForRegularDistance(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    return writeMinimalCompressedHeaderForRegularDistancePattern(allocator, writer, 'a', 'b');
}

fn writeMinimalCompressedHeaderForRegularDistancePattern(allocator: std.mem.Allocator, writer: *BitWriter, first: u8, second: u8) Error!void {
    return writeMinimalCompressedHeaderForAlternatingPattern(allocator, writer, first, second, 145);
}

fn writeMinimalCompressedHeaderForAlternatingPattern(allocator: std.mem.Allocator, writer: *BitWriter, first: u8, second: u8, command_symbol: u16) Error!void {
    if (first == second) return error.InvalidBlockPlan;
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 1, 2); // NPOSTFIX
    try writer.writeBits(allocator, 1, 4); // NDIRECT = 1
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, first, alphabetBits(256));
    try writer.writeBits(allocator, second, alphabetBits(256));

    try writer.writeBits(allocator, 1, 2); // simple insert-copy prefix
    try writer.writeBits(allocator, 0, 2); // NSYM = 1
    try writer.writeBits(allocator, command_symbol, alphabetBits(704));

    try writeSimpleSingleSymbolPrefix(allocator, writer, 112, 17);
}

fn writeRepeatedPrefixCompressedHeader(allocator: std.mem.Allocator, writer: *BitWriter, prefix: []const u8, seed_symbol: u16, copy_symbol: u16) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, @intCast(prefix.len), 4); // direct distances 1...prefix.len
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD
    try writeSimplePrefixRuntime(allocator, writer, 256, prefix, false);
    try writer.writeBits(allocator, 1, 2); // simple command prefix
    try writer.writeBits(allocator, 1, 2); // two symbols
    // The two-symbol simple tree assigns one-bit codes in listed order.
    try writer.writeBits(allocator, copy_symbol, alphabetBits(704));
    try writer.writeBits(allocator, seed_symbol, alphabetBits(704));
    try writeSimpleSingleSymbolPrefixRuntime(allocator, writer, 16 + prefix.len + 48, 15 + prefix.len);
}

const BlockLengthEncoding = struct {
    symbol: u5,
    extra: usize,
    extra_bits: u5,
};

const TwoBlockLengthCode = struct {
    alphabet: command_plan.PrefixAlphabetFor(26),
    lengths: [26]u4,
    block_lengths: [2]BlockLengthEncoding,

    fn init(first_len: usize, second_len: usize) Error!TwoBlockLengthCode {
        if (first_len == 0 or second_len == 0) return error.InvalidBlockPlan;
        const first = blockLengthEncoding(first_len) orelse return error.InvalidBlockPlan;
        const second = blockLengthEncoding(second_len) orelse return error.InvalidBlockPlan;
        var frequencies: [26]u32 = @splat(0);
        frequencies[first.symbol] += 1;
        frequencies[second.symbol] += 1;
        var alphabet: command_plan.PrefixAlphabetFor(26) = undefined;
        try command_plan.alphabetFromFrequenciesInto(26, &alphabet, &frequencies);
        return .{
            .alphabet = alphabet,
            .lengths = try alphabet.codeLengths(&frequencies),
            .block_lengths = .{ first, second },
        };
    }

    fn writeLength(self: *const TwoBlockLengthCode, allocator: std.mem.Allocator, writer: *BitWriter, index: usize) Error!void {
        if (index >= self.block_lengths.len) return error.InvalidBlockPlan;
        const encoding = self.block_lengths[index];
        if (self.alphabet.len > 1) {
            const code = self.alphabet.simpleCode(encoding.symbol) orelse return error.InvalidBlockPlan;
            try writer.writeHuffmanBits(allocator, code.code, code.bits);
        }
        try writer.writeBits(allocator, encoding.extra, encoding.extra_bits);
    }
};

const CommandBlockLengthCode = struct {
    alphabet: command_plan.PrefixAlphabetFor(26),
    lengths: [26]u4,
    block_lengths: [4]BlockLengthEncoding,
    block_count: usize,

    fn init(split: command_block_split.Result, command_count: usize) Error!CommandBlockLengthCode {
        const block_count = split.regionCount();
        if (split.split == 0 or split.split >= command_count) return error.InvalidBlockPlan;
        var block_lengths: [4]BlockLengthEncoding = undefined;
        block_lengths[0] = blockLengthEncoding(split.split) orelse return error.InvalidBlockPlan;
        if (split.second_split) |second| {
            if (second <= split.split or second >= command_count) return error.InvalidBlockPlan;
            block_lengths[1] = blockLengthEncoding(second - split.split) orelse return error.InvalidBlockPlan;
            if (split.third_split) |third| {
                if (third <= second or third >= command_count) return error.InvalidBlockPlan;
                block_lengths[2] = blockLengthEncoding(third - second) orelse return error.InvalidBlockPlan;
                block_lengths[3] = blockLengthEncoding(command_count - third) orelse return error.InvalidBlockPlan;
            } else block_lengths[2] = blockLengthEncoding(command_count - second) orelse return error.InvalidBlockPlan;
        } else {
            if (split.third_split != null) return error.InvalidBlockPlan;
            block_lengths[1] = blockLengthEncoding(command_count - split.split) orelse return error.InvalidBlockPlan;
        }
        var frequencies: [26]u32 = @splat(0);
        for (block_lengths[0..block_count]) |encoding| frequencies[encoding.symbol] += 1;
        var alphabet: command_plan.PrefixAlphabetFor(26) = undefined;
        try command_plan.alphabetFromFrequenciesInto(26, &alphabet, &frequencies);
        return .{
            .alphabet = alphabet,
            .lengths = try alphabet.codeLengths(&frequencies),
            .block_lengths = block_lengths,
            .block_count = block_count,
        };
    }

    fn writeLength(self: *const CommandBlockLengthCode, allocator: std.mem.Allocator, writer: *BitWriter, index: usize) Error!void {
        if (index >= self.block_count) return error.InvalidBlockPlan;
        const encoding = self.block_lengths[index];
        if (self.alphabet.len > 1) {
            const code = self.alphabet.simpleCode(encoding.symbol) orelse return error.InvalidBlockPlan;
            try writer.writeHuffmanBits(allocator, code.code, code.bits);
        }
        try writer.writeBits(allocator, encoding.extra, encoding.extra_bits);
    }
};

const CommandBlockSplitHeader = struct {
    block_count: usize,
    alphabets: *const [3]command_plan.PrefixAlphabet,
    lengths: *const [3][704]u4,
    split_code: *const CommandBlockLengthCode,
};

const DistanceBlockSplitHeader = struct {
    alphabets: *const [2]command_plan.PrefixAlphabetFor(planned_distance_alphabet_size),
    lengths: *const [2][planned_distance_alphabet_size]u4,
    split_code: *const TwoBlockLengthCode,
};

fn writeCommandBlockSwitchHeader(allocator: std.mem.Allocator, writer: *BitWriter, split: ?CommandBlockSplitHeader) Error!void {
    if (split) |header| {
        try writeBlockTypeCount(allocator, writer, @intCast(header.block_count));
        try writeSimpleSingleSymbolPrefixRuntime(allocator, writer, header.block_count + 2, 1);
        try writePrefixSymbolsWithLengths(allocator, writer, 26, &header.split_code.alphabet, &header.split_code.lengths);
        try header.split_code.writeLength(allocator, writer, 0);
    } else try writeBlockTypeCount(allocator, writer, 1);
}

fn writePlannedCommandTrees(allocator: std.mem.Allocator, writer: *BitWriter, alphabet: *const command_plan.PrefixAlphabet, lengths: *const [704]u4, split: ?CommandBlockSplitHeader) Error!void {
    if (split) |header| {
        for (0..header.block_count) |tree|
            try writePrefixSymbolsWithLengths(allocator, writer, 704, &header.alphabets[tree], &header.lengths[tree]);
    } else try writePrefixSymbolsWithLengths(allocator, writer, 704, alphabet, lengths);
}

fn writeDistanceBlockSwitchHeader(allocator: std.mem.Allocator, writer: *BitWriter, split: ?DistanceBlockSplitHeader) Error!void {
    if (split) |header| {
        try writeBlockTypeCount(allocator, writer, 2);
        try writeSimpleSingleSymbolPrefixRuntime(allocator, writer, 4, 1);
        try writePrefixSymbolsWithLengths(allocator, writer, 26, &header.split_code.alphabet, &header.split_code.lengths);
        try header.split_code.writeLength(allocator, writer, 0);
    } else try writeBlockTypeCount(allocator, writer, 1);
}

fn writeDistanceTreeContextMap(allocator: std.mem.Allocator, writer: *BitWriter, split: ?DistanceBlockSplitHeader) Error!void {
    if (split == null) return writeBlockTypeCount(allocator, writer, 1);
    try writeBlockTypeCount(allocator, writer, 2);
    // Eight entries: block type 0 uses tree 0 for all four contexts; block
    // type 1 uses tree 1. With IMTF the latter becomes [1,0,0,0].
    try writer.writeBits(allocator, 1, 1); // use RLE for zeros
    try writer.writeBits(allocator, 1, 4); // RLEMAX = 2
    try writer.writeBits(allocator, 1, 2); // simple context-map prefix
    try writer.writeBits(allocator, 2, 2); // NSYM = 3
    try writer.writeBits(allocator, 1, alphabetBits(4)); // zero run 2...3
    try writer.writeBits(allocator, 2, alphabetBits(4)); // zero run 4...7
    try writer.writeBits(allocator, 3, alphabetBits(4)); // tree 1
    try writeThreeSymbolContextMapCode(allocator, writer, 1);
    try writer.writeBits(allocator, 0, 2); // four zeros
    try writeThreeSymbolContextMapCode(allocator, writer, 2);
    try writeThreeSymbolContextMapCode(allocator, writer, 0);
    try writer.writeBits(allocator, 1, 1); // three zeros
    try writer.writeBits(allocator, 1, 1); // IMTF
}

fn writePlannedDistanceTrees(allocator: std.mem.Allocator, writer: *BitWriter, alphabet_size: usize, alphabet: *const command_plan.PrefixAlphabetFor(planned_distance_alphabet_size), lengths: *const [planned_distance_alphabet_size]u4, split: ?DistanceBlockSplitHeader) Error!void {
    if (split) |header| {
        inline for (0..2) |tree|
            try writePrefixSymbolsWithLengths(allocator, writer, alphabet_size, &header.alphabets[tree], &header.lengths[tree]);
    } else try writePrefixSymbolsWithLengths(allocator, writer, alphabet_size, alphabet, lengths);
}

fn blockLengthEncoding(len: usize) ?BlockLengthEncoding {
    if (len == 0 or len > max_uncompressed_meta_block_len) return null;
    for (block_length_specs, 0..) |spec, symbol| {
        const capacity = @as(usize, 1) << @intCast(spec.extra_bits);
        if (len < spec.base or len - spec.base >= capacity) continue;
        return .{ .symbol = @intCast(symbol), .extra = len - spec.base, .extra_bits = spec.extra_bits };
    }
    return null;
}

fn writePlannedCompressedHeaderTwoLiteralBlocks(
    allocator: std.mem.Allocator,
    writer: *BitWriter,
    literal_alphabets: *const [2]command_plan.PrefixAlphabetFor(256),
    literal_lengths: *const [2][256]u4,
    split_code: *const TwoBlockLengthCode,
    ndirect: u7,
    command_alphabet: *const command_plan.PrefixAlphabet,
    command_split: ?CommandBlockSplitHeader,
    distance_alphabet: *const command_plan.PrefixAlphabetFor(planned_distance_alphabet_size),
    distance_split: ?DistanceBlockSplitHeader,
    distance_alphabet_size: usize,
    command_lengths: *const [704]u4,
    distance_lengths: *const [planned_distance_alphabet_size]u4,
) Error!void {
    try writeBlockTypeCount(allocator, writer, 2);
    // Types are 0 then 1, so the implicit next-type code is the only symbol.
    try writeSimpleSingleSymbolPrefixRuntime(allocator, writer, 4, 1);
    try writePrefixSymbolsWithLengths(allocator, writer, 26, &split_code.alphabet, &split_code.lengths);
    try split_code.writeLength(allocator, writer, 0);
    try writeCommandBlockSwitchHeader(allocator, writer, command_split);
    try writeDistanceBlockSwitchHeader(allocator, writer, distance_split);
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, ndirect, 4);
    try writer.writeBits(allocator, 0, 2); // literal context mode, block 0
    try writer.writeBits(allocator, 0, 2); // literal context mode, block 1
    try writeBlockTypeCount(allocator, writer, 2);
    try writeTwoLiteralBlockContextMap(allocator, writer);
    try writeDistanceTreeContextMap(allocator, writer, distance_split);
    inline for (0..2) |tree|
        try writePrefixSymbolsWithLengths(allocator, writer, 256, &literal_alphabets[tree], &literal_lengths[tree]);
    try writePlannedCommandTrees(allocator, writer, command_alphabet, command_lengths, command_split);
    try writePlannedDistanceTrees(allocator, writer, distance_alphabet_size, distance_alphabet, distance_lengths, distance_split);
}

fn writeTwoLiteralBlockContextMap(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    // With inverse MTF, [0 x 64, 1 x 64] becomes [0 x 64, 1, 0 x 63].
    // Symbols 5 and 6 are zero runs of 32...63 and 64...127 entries; symbol
    // 7 selects literal tree 1 when RLEMAX is six.
    try writer.writeBits(allocator, 1, 1); // use RLE for zeros
    try writer.writeBits(allocator, 5, 4); // RLEMAX = 6
    try writer.writeBits(allocator, 1, 2); // simple context-map prefix
    try writer.writeBits(allocator, 2, 2); // NSYM = 3
    try writer.writeBits(allocator, 5, alphabetBits(8));
    try writer.writeBits(allocator, 6, alphabetBits(8));
    try writer.writeBits(allocator, 7, alphabetBits(8));
    try writeThreeSymbolContextMapCode(allocator, writer, 1); // symbol 6
    try writer.writeBits(allocator, 0, 6); // 64 zeros
    try writeThreeSymbolContextMapCode(allocator, writer, 2); // symbol 7 / tree 1
    try writeThreeSymbolContextMapCode(allocator, writer, 0); // symbol 5
    try writer.writeBits(allocator, 31, 5); // 63 zeros after inverse MTF
    try writer.writeBits(allocator, 1, 1); // IMTF
}

fn writePlannedCompressedHeader(
    allocator: std.mem.Allocator,
    writer: *BitWriter,
    literal_alphabet: *const command_plan.PrefixAlphabetFor(256),
    command_alphabet: *const command_plan.PrefixAlphabet,
    command_split: ?CommandBlockSplitHeader,
    distance_alphabet: *const command_plan.PrefixAlphabetFor(planned_distance_alphabet_size),
    distance_split: ?DistanceBlockSplitHeader,
    ndirect: u7,
    distance_alphabet_size: usize,
    literal_lengths: *const [256]u4,
    command_lengths: *const [704]u4,
    distance_lengths: *const [planned_distance_alphabet_size]u4,
) Error!void {
    try writeBlockTypeCount(allocator, writer, 1);
    try writeCommandBlockSwitchHeader(allocator, writer, command_split);
    try writeDistanceBlockSwitchHeader(allocator, writer, distance_split);
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, ndirect, 4);
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1);
    try writeDistanceTreeContextMap(allocator, writer, distance_split);
    try writePrefixSymbolsWithLengths(allocator, writer, 256, literal_alphabet, literal_lengths);
    try writePlannedCommandTrees(allocator, writer, command_alphabet, command_lengths, command_split);
    try writePlannedDistanceTrees(allocator, writer, distance_alphabet_size, distance_alphabet, distance_lengths, distance_split);
}

fn writePlannedCompressedHeaderTwoLiteralContexts(
    allocator: std.mem.Allocator,
    writer: *BitWriter,
    literal_alphabets: *const [2]command_plan.PrefixAlphabetFor(256),
    literal_lengths: *const [2][256]u4,
    context_cutoff: u6,
    ndirect: u7,
    command_alphabet: *const command_plan.PrefixAlphabet,
    command_split: ?CommandBlockSplitHeader,
    distance_alphabet: *const command_plan.PrefixAlphabetFor(planned_distance_alphabet_size),
    distance_split: ?DistanceBlockSplitHeader,
    distance_alphabet_size: usize,
    command_lengths: *const [704]u4,
    distance_lengths: *const [planned_distance_alphabet_size]u4,
) Error!void {
    try writeBlockTypeCount(allocator, writer, 1);
    try writeCommandBlockSwitchHeader(allocator, writer, command_split);
    try writeDistanceBlockSwitchHeader(allocator, writer, distance_split);
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, ndirect, 4);
    try writer.writeBits(allocator, literal_context.mode_utf8, 2);
    try writeBlockTypeCount(allocator, writer, 2);
    try writeUtf8SuffixContextMap(allocator, writer, context_cutoff);
    try writeDistanceTreeContextMap(allocator, writer, distance_split);
    inline for (0..2) |tree| try writePrefixSymbolsWithLengths(allocator, writer, 256, &literal_alphabets[tree], &literal_lengths[tree]);
    try writePlannedCommandTrees(allocator, writer, command_alphabet, command_lengths, command_split);
    try writePlannedDistanceTrees(allocator, writer, distance_alphabet_size, distance_alphabet, distance_lengths, distance_split);
}

fn writeUtf8TextContextMap(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    return writeUtf8SuffixContextMap(allocator, writer, 56);
}

fn writeUtf8SuffixContextMap(allocator: std.mem.Allocator, writer: *BitWriter, cutoff: u6) Error!void {
    if (cutoff < 32 or cutoff > 63) return error.InvalidBlockPlan;
    try writer.writeBits(allocator, 1, 1); // Use zero-run RLE.
    try writer.writeBits(allocator, 5, 4); // RLEMAX = 6.
    try writer.writeBits(allocator, 1, 2); // Simple prefix.
    try writer.writeBits(allocator, 1, 2); // NSYM = 2.
    // Symbol 5 encodes a 32...63 zero run; symbol 7 selects literal tree 1.
    try writer.writeBits(allocator, 5, alphabetBits(8));
    try writer.writeBits(allocator, 7, alphabetBits(8));
    try writer.writeBits(allocator, 0, 1); // Symbol 5.
    try writer.writeBits(allocator, cutoff - 32, 5);
    for (cutoff..64) |_| try writer.writeBits(allocator, 1, 1); // Symbol 7.
    try writer.writeBits(allocator, 0, 1); // IMTF = false.
}

fn writePrefixSymbolsWithLengths(allocator: std.mem.Allocator, writer: *BitWriter, alphabet_size: usize, alphabet: anytype, lengths: []const u4) Error!void {
    if (alphabet.len == 0) return error.InvalidBlockPlan;
    if (alphabet.len > 4) {
        var highest: usize = 0;
        for (alphabet.symbols[0..alphabet.len]) |symbol| highest = @max(highest, symbol);
        return complex_prefix.writeWithStopIndex(allocator, writer, alphabet_size, lengths, highest + 1);
    }
    try writer.writeBits(allocator, 1, 2);
    try writer.writeBits(allocator, alphabet.len - 1, 2);
    for (alphabet.symbols[0..alphabet.len]) |symbol| {
        if (symbol >= alphabet_size) return error.InvalidHuffmanCode;
        try writer.writeBits(allocator, symbol, alphabetBitsRuntime(alphabet_size));
    }
    if (alphabet.len == 4) try writer.writeBits(allocator, 0, 1); // balanced four-symbol tree
}

fn writeMinimalCompressedHeaderForDistanceContext(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 2, 4); // NDIRECT = 2
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 2); // NTREESD
    try writeDistanceContextMapForCopyLenThree(allocator, writer);

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 'a', alphabetBits(256));
    try writer.writeBits(allocator, 'b', alphabetBits(256));

    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 145);

    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 16);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 17);
}

fn writeMinimalCompressedHeaderForDistanceContextComplexMap(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 2, 4); // NDIRECT = 2
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 2); // NTREESD
    try writeDistanceContextMapForCopyLenThreeComplexPrefix(allocator, writer);

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 'a', alphabetBits(256));
    try writer.writeBits(allocator, 'b', alphabetBits(256));

    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 145);

    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 16);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 17);
}

fn writeMinimalCompressedHeaderForComplexDistancePrefix(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 2, 4); // NDIRECT = 2
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 1); // NTREESD

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 'a', alphabetBits(256));
    try writer.writeBits(allocator, 'b', alphabetBits(256));

    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 145);
    try writeComplexDistancePrefixForDistanceTwo(allocator, writer);
}

fn writeMinimalCompressedHeaderForFifthDistanceContext(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 2, 4); // NDIRECT = 2
    try writer.writeBits(allocator, 0, 2); // literal context mode
    try writeBlockTypeCount(allocator, writer, 1); // NTREESL
    try writeBlockTypeCount(allocator, writer, 5); // NTREESD
    try writeDistanceContextMapForCopyLenThreeFifthTree(allocator, writer);

    try writer.writeBits(allocator, 1, 2); // simple literal prefix
    try writer.writeBits(allocator, 1, 2); // NSYM = 2
    try writer.writeBits(allocator, 'a', alphabetBits(256));
    try writer.writeBits(allocator, 'b', alphabetBits(256));

    try writeSimpleSingleSymbolPrefix(allocator, writer, 704, 145);

    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 16);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 16);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 16);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 16);
    try writeSimpleSingleSymbolPrefix(allocator, writer, 66, 17);
}

fn writeMinimalCompressedHeaderForNinthDistanceContext(allocator: std.mem.Allocator, writer: *BitWriter) Error!void {
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESL
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESI
    try writeBlockTypeCount(allocator, writer, 1); // NBLTYPESD
    try writer.writeBits(allocator, 0, 2); // NPOSTFIX
    try writer.writeBits(allocator, 2, 4); // NDIRECT = 2
    try writer.writeBits(allocator, 0, 2); // literal context mode
